const CHAPTERS=[{"id":"permit","name":"Permits & Licensing","icon":"🪪","src":"Handbook: Driver Education & Permits","qs":[{"id":"per-1gzug3d","q":"What is the minimum age to get a Utah entry-level learner permit?","a":"15","o":["15","14","16","17"],"why":"Utah's entry-level learner permit starts at age 15. The 6-month learner permit starts at 16."},{"id":"per-1rubvg5","q":"A 16 or 17 year old needs to hold a learner permit for how long before getting a license?","a":"At least six months","o":["At least six months","At least 90 days","At least twelve months","At least thirty days"],"why":"Ages 16 and 17 must hold the permit six months and finish driver education."},{"id":"per-1c8b9qg","q":"Utah teens ages 15 to 18 must drive how many hours with a parent or guardian before licensing?","a":"40 hours, with 10 after sunset","o":["40 hours, with 10 after sunset","40 hours, with 20 after sunset","50 hours, with 10 after sunset","30 hours, with 10 after sunset"],"why":"The handbook requires 40 hours of driving, 10 of them after sunset."},{"id":"per-ivaaw9","q":"Which of these may supervise a minor learner permit driver under the 2026 change in the law?","a":"A licensed stepparent or foster parent","o":["A licensed stepparent or foster parent","A licensed older sibling who is 18","Any licensed friend who is 18","A licensed neighbor with no written permission"],"why":"SB 22 (2026) lets a stepparent or foster parent supervise a minor permit holder."},{"id":"per-18dqal5","q":"How must the learner permit be carried while you drive?","a":"In your immediate possession","o":["In your immediate possession","Stored in the trunk of the car","Left at home with a parent","Carried only when driving at night"],"why":"The permit must be in your immediate possession whenever you drive."},{"id":"per-13ij65x","q":"What does a Utah provisional license tell you about the holder?","a":"The driver is under 21","o":["The driver is under 21","The driver is new to Utah","The driver is under 18","The driver failed the first road test"],"why":"A provisional license is issued to every Utah driver under age 21."},{"id":"per-1pygyvk","q":"What is the minimum age for an original regular Utah Class D license?","a":"16","o":["16","15","17","18"],"why":"Class D, the regular car license, has a minimum age of 16."},{"id":"per-ir1der","q":"Which license class covers a regular passenger car?","a":"Class D","o":["Class D","Class A","Class B","Class C"],"why":"Class D covers vehicles that are not Class A, B, C, or a motorcycle."},{"id":"per-1qb5lhb","q":"A 19 year old with no license and no driver education must hold a learner permit for how long?","a":"90 days","o":["90 days","6 months","30 days","1 year"],"why":"Age 19 and older can skip driver education by holding the permit 90 days and logging 40 hours."},{"id":"per-huiyvm","q":"A first-time applicant who is 18 must do what?","a":"Finish an approved driver education course","o":["Finish an approved driver education course","Hold a learner permit for at least six months","Hold a learner permit for at least 90 days","Pass a second written knowledge test first"],"why":"At 18 there is no holding period, but driver education is required."},{"id":"per-100brcq","q":"How many behind-the-wheel hours are part of a Utah driver education course?","a":"6 hours","o":["6 hours","10 hours","4 hours","12 hours"],"why":"The course includes 6 hours behind the wheel plus classroom and observation time."},{"id":"per-1ib3fe","q":"Which endorsement lets you ride a motorcycle?","a":"M","o":["M","H","S","T"],"why":"The M endorsement covers motorcycles."},{"id":"per-1se74e4","q":"A 16 year old with a full license may not drive during which hours without a licensed adult 21 or older?","a":"12:00 a.m. to 5:00 a.m.","o":["12:00 a.m. to 5:00 a.m.","10:00 p.m. to 5:00 a.m.","11:00 p.m. to 6:00 a.m.","9:00 p.m. to 4:00 a.m."],"why":"Age 16 drivers have a midnight to 5 a.m. limit, with exceptions like work, school events, and emergencies."},{"id":"per-1cd7rso","q":"For the first six months, a licensed 16 year old may carry passengers who are:","a":"Immediate family only","o":["Immediate family only","Any friends","Anyone age 21 or younger","Anyone with written permission"],"why":"The passenger limit is immediate family until six months after the license is issued, with exceptions."},{"id":"per-58wl8o","q":"A visitor has a valid license from another state and is at least 16. In Utah, they may:","a":"Drive without a Utah license","o":["Drive without a Utah license","Drive only with a Utah permit","Drive only for 30 days","Drive only with a Utah driver in the car"],"why":"Out-of-state licensed drivers 16 and older may drive in Utah."},{"id":"per-1j0ekyg","q":"How soon must a Class D driver tell the division after moving to a new address?","a":"Within 10 days","o":["Within 10 days","Within 30 days","Within 90 days","At the next renewal"],"why":"Class D drivers notify the division within 10 days of an address change."},{"id":"per-12edkr9","q":"A 17 year old has held a learner permit for 4 months and has finished driver education. Can the teen get a regular license now?","a":"No, the permit must be held at least six months","o":["No, the permit must be held at least six months","Yes, finishing driver education replaces the waiting time","Yes, if the teen has logged 40 driving hours","No, the teen must wait until turning 18"],"why":"Ages 16 and 17 must hold the permit at least six months and finish driver education."},{"id":"per-tnfl69","q":"How many classroom hours does a Utah high school driver education course require?","a":"27 hours","o":["27 hours","18 hours","30 hours","36 hours"],"why":"High school courses use 27 classroom hours. Private schools use 18 and online or home study uses 30."},{"id":"per-v22yoo","q":"A commercial or private driving school course has how many classroom hours?","a":"18 hours","o":["18 hours","27 hours","30 hours","12 hours"],"why":"Commercial and private schools teach 18 classroom hours. High schools use 27."},{"id":"per-oc8s9q","q":"An approved online or home study driver education course has how many classroom hours?","a":"30 hours","o":["30 hours","27 hours","18 hours","40 hours"],"why":"Utah approved online and home study courses are 30 classroom hours."},{"id":"per-1vq5fni","q":"How long is an entry-level learner permit valid?","a":"18 months","o":["18 months","6 months","12 months","24 months"],"why":"An entry-level learner permit lasts 18 months, and so does the passing written test score."},{"id":"per-1g0jw2j","q":"A 15 year old's parent does not drive. A licensed neighbor, age 25, did not sign for the permit but will supervise. What else must the neighbor have?","a":"A note or proof from the parent allowing it","o":["A note or proof from the parent allowing it","A letter from the school principal","A driver education certificate of their own","Nothing else, since a valid license is enough"],"why":"Handbook Section 3B: when the parent is not a licensed driver, a licensed adult 21 or older who is not the guardian and did not sign for the permit needs a note or proof from the parent allowing them to supervise."},{"id":"per-8xcbts","q":"A teen's parent does not have a driver license. Who may supervise the teen's learner permit driving?","a":"A licensed adult 21 or older who carries the parent's written permission","o":["A licensed adult 21 or older who carries the parent's written permission","A licensed friend who is 18 with the parent's written permission","No one, so the teen must wait until the parent gets a license","A licensed adult 21 or older who has the parent's verbal permission by phone"],"why":"If the parent is not a licensed driver, another adult may supervise but must carry the parent's written authorization."},{"id":"per-1kavp7l","q":"An 18 year old with a learner permit is driving. Who must sit in the front seat?","a":"A licensed driver 21 or older","o":["A licensed driver 21 or older","A licensed driver 18 or older","A licensed driver 19 or older","Nobody, if it is daytime"],"why":"At 18 and older, a permit holder needs a licensed driver 21 or older in the front seat."},{"id":"per-ztufb8","q":"A 16 year old with a license may drive between midnight and 5 a.m. only when:","a":"A licensed driver 21 or older is in the front seat","o":["A licensed driver 21 or older is in the front seat","A licensed friend who is 18 or older rides along in front","The teen stays on main roads and avoids the freeway","A parent knows where the teen is going and when to be home"],"why":"The midnight to 5 a.m. limit has exceptions such as a licensed driver 21 or older in front, work, school activities, and emergencies."},{"id":"per-7mu4nn","q":"A 16 year old with a license is driving home from work at 1 a.m. Is this allowed?","a":"Yes, driving to or from work is an exception","o":["Yes, driving to or from work is an exception","No, the midnight limit has no exceptions for work trips","No, the exceptions cover school events but not work trips","Yes, if you stay on main roads and text a parent"],"why":"Work, school activities, farm work, emergencies, or a licensed driver 21 or older in front are exceptions to the midnight limit."},{"id":"per-fwy7op","q":"A 16 year old got a license two months ago. Which passenger may ride with the teen when no adult 21 or older is along?","a":"The teen's sister","o":["The teen's sister","A best friend from school","A teammate going to practice","A neighbor who is 17"],"why":"For the first six months, passengers must be immediate family unless an exception applies."},{"id":"per-ob87mb","q":"When does the immediate-family passenger limit for a new 16 year old driver end?","a":"Six months after the license is issued","o":["Six months after the license is issued","On the teen's 17th birthday","Ninety days after the license is issued","One year after the license is issued"],"why":"The limit lasts until six months after the license is issued."},{"id":"per-1h17uma","q":"A provisional Class D license, for drivers under 21, expires on the birthday how many years after issue?","a":"Five years","o":["Five years","Eight years","Three years","Ten years"],"why":"Provisional licenses expire five years after issue. Regular licenses for adults last eight years."},{"id":"per-erc8gn","q":"A regular Class D license for a driver 21 or older expires on the birthday how many years after issue?","a":"Eight years","o":["Eight years","Five years","Seven years","Ten years"],"why":"Regular adult licenses last eight years."},{"id":"per-zwp7ad","q":"How early can you renew your Utah license?","a":"Up to six months before it expires","o":["Up to six months before it expires","Up to three months before it expires","Up to 90 days before it expires","Up to two years before it expires"],"why":"You can schedule an online renewal appointment up to six months ahead."},{"id":"per-1nfev2b","q":"A visitor with a valid license from another state may drive in Utah for up to:","a":"Six months","o":["Six months","90 days","Nine months","One year"],"why":"Visitors with a valid out-of-state or out-of-country license may drive in Utah for up to six months."},{"id":"per-1di6ii","q":"Can someone use an out-of-state learner permit to drive in Utah?","a":"No, out-of-state learner permits do not allow driving here","o":["No, out-of-state learner permits do not allow driving here","Yes, for up to six months if a licensed adult rides beside you","Yes, if a Utah resident 21 or older rides in the front seat","Yes, if you stay on local streets during daylight hours"],"why":"Out-of-state learner permits are not valid for driving in Utah."},{"id":"per-1gpypnd","q":"Which person is treated as a Utah resident who needs a Utah license?","a":"Someone who stays in Utah six months or more in a calendar year","o":["Someone who stays in Utah six months or more in a calendar year","Someone who stays in Utah for four months during a calendar year","Someone on a short work assignment from another state","Someone passing through Utah on a long road trip"],"why":"Staying six months or more in a year makes you a resident. Temporary assignments do not count."},{"id":"per-20gp1w","q":"Which person may NOT be given a Utah driver license?","a":"Someone whose license is suspended in another state","o":["Someone whose license is suspended in another state","A 16 year old who finished driver education and six months with a permit","A new Utah resident with a valid out-of-state license","Someone who wears glasses to drive"],"why":"You cannot be licensed in Utah if your license is denied, suspended, or revoked in any state."},{"id":"per-138qdx2","q":"A teen moves to Utah with an out-of-state online driver education certificate. Will Utah accept it?","a":"No, out-of-state online certificates are not accepted","o":["No, out-of-state online certificates are not accepted","Yes, if it shows 30 hours of online study and 6 hours behind the wheel","Yes, if a parent signs it in front of a notary public","Yes, if the school district approves it for credit"],"why":"Utah does not accept out-of-state online or home study driver education. Missing hours can be made up at an approved Utah school."},{"id":"per-1q188j8","q":"How many documents proving Utah residency must you bring when you apply for a license?","a":"Two","o":["Two","One","Three","Four"],"why":"Two acceptable residency documents are required."},{"id":"per-qbfarp","q":"Residency documents such as a bank statement or utility bill must be dated within:","a":"90 days","o":["90 days","30 days","6 months","One year"],"why":"Each residency proof must show your name and address and be dated within 90 days."},{"id":"per-fiv32c","q":"Which of these can be used as proof of where you live?","a":"A utility bill with your name and address","o":["A utility bill with your name and address","A library card with your name and picture","A gym membership card with your signature","A store receipt from last week's groceries"],"why":"Accepted proofs include utility bills, bank statements, rental contracts, and property tax notices."},{"id":"per-1jghe8e","q":"Which birth certificate will the Driver License Division accept?","a":"A certified copy from the state of birth","o":["A certified copy from the state of birth","A hospital certificate with the baby's footprints","A laminated copy you made at a print shop","A photocopy that a notary public has stamped"],"why":"Use a state-certified birth certificate. Hospital, laminated, or photocopied ones are not accepted."},{"id":"per-rq8vl9","q":"Your name changed after you got married. What do you need to get a license in the new name?","a":"A certified marriage certificate or other legal paperwork","o":["A certified marriage certificate or other legal paperwork","A signed letter from your employer about the change","A new credit card and a utility bill with the new last name","A signed statement from two relatives who know you well"],"why":"A legal document such as a marriage certificate, divorce decree, or court order is needed for a name change."},{"id":"per-1wrz444","q":"You moved last week. Will the post office forward your Driver License Division mail?","a":"No, you must update your address with the division","o":["No, you must update your address with the division","Yes, forwarding updates your address with the division","Yes, the post office forwards it for the first year","No, but you have 30 days before you must tell anyone"],"why":"The post office does not forward division mail. Tell the division within 10 days."},{"id":"per-tp6fob","q":"Which endorsement lets a driver operate a school bus?","a":"S","o":["S","P","T","H"],"why":"S is the school bus endorsement. P is passenger, T is doubles or triples, and H is hazardous materials."},{"id":"per-1gpwvle","q":"A Commercial Driver License (CDL) is needed for a vehicle rated at what weight or more?","a":"26,001 pounds","o":["26,001 pounds","10,001 pounds","16,001 pounds","20,000 pounds"],"why":"A CDL is required at 26,001 pounds GVWR or more, or for buses, hazmat, and similar vehicles."},{"id":"per-1lrj2gq","q":"What can a Driving Privilege Card (DPC) be used for?","a":"Driving only, not as ID or to prove your age","o":["Driving only, not as ID or to prove your age","Driving and boarding a plane inside the country","Driving and buying age restricted items in stores","Driving and proving identity at a bank"],"why":"A DPC is for driving only and is not valid identification or age verification."},{"id":"per-f4aj9f","q":"Can a person hold a Utah driver license and a Utah ID card at the same time?","a":"No, only one at a time","o":["No, only one at a time","Yes, if the ID is for a different address","Yes, if the person is under 21","Yes, with a doctor's note"],"why":"A person may not hold a driver license and an ID card at the same time."},{"id":"per-8kig60","q":"A 20 year old completes an approved driver education course. What happens to the 90 day permit holding rule?","a":"It is waived","o":["It is waived","It is doubled","It still must be done in full","It becomes six months"],"why":"Finishing an approved course waives the 90 day permit requirement for adults 19 and older."},{"id":"per-zyim1q","q":"The written knowledge test score for a 6-month learner permit is valid for how long?","a":"12 months","o":["12 months","18 months","6 months","24 months"],"why":"Handbook Section 3B: scores for the 6-month learner permit stay valid 12 months."},{"id":"per-ix4tav","q":"Your entry-level learner permit expires before you use it to get licensed. What must you do?","a":"Retake the written knowledge test","o":["Retake the written knowledge test","Only pay the permit fee again","Retake the driving skills test only","Nothing, the old score still counts"],"why":"Handbook Section 3B: if you renew or let the permit expire, you must retake the written test."},{"id":"per-1nm9ks3","q":"A learner permit holder has a licensed supervisor in the front seat. May other passengers ride in the car?","a":"Yes, passengers may be in the vehicle","o":["Yes, passengers may be in the vehicle","No, the supervisor must be the only other person","Only passengers under 12","Only family members"],"why":"Handbook Section 3B: passengers may be in the vehicle with the permit holder and supervisor."},{"id":"per-5s8wfh","q":"Who can be issued a limited-term driver license?","a":"A non-citizen whose lawful status in the U.S. has been verified","o":["A non-citizen whose lawful status in the U.S. has been verified","A U.S. citizen over age 65 who wants a longer renewal period","A teen who has finished driver education and held a permit","A visitor who holds a valid license from another state or country"],"why":"Handbook Section 4A: it is for a non-U.S. citizen with verified lawful status."},{"id":"per-1cbr6hg","q":"A Driving Privilege Card (DPC) expires:","a":"Every year on the holder's birthday","o":["Every year on the holder's birthday","Eight years after it is issued, like a regular license","Five years after it is issued","Six months after it is issued"],"why":"Handbook Section 4A: the DPC expires each year on the applicant's birthday."},{"id":"per-iebsu0","q":"A person applies for a Driving Privilege Card. Can the person drive while waiting for the card?","a":"No, no driving until the plastic card arrives by mail","o":["No, no driving until the plastic card arrives by mail","Yes, with a temporary license that is good for up to six months","Yes, with a temporary license for 30 days","Yes, if a licensed adult rides along"],"why":"Handbook Section 4A: Utah law does not allow a temporary license for a DPC."},{"id":"per-gnho0p","q":"A regular Class D license allows you to drive personal vehicles up to what weight?","a":"26,000 pounds","o":["26,000 pounds","10,000 pounds","16,000 pounds","20,000 pounds"],"why":"Handbook Section 4A: Class D covers personal vehicles up to 26,000 pounds."},{"id":"per-9ldur4","q":"Which endorsement code is for a taxicab?","a":"Z","o":["Z","T","N","X"],"why":"Handbook Section 4B: Z is taxicab, T is doubles or triples, N is tanker, X is hazmat and tanker."},{"id":"per-1rw9kzl","q":"Which endorsement code is for a tanker?","a":"N","o":["N","H","P","Z"],"why":"Handbook Section 4B: N is Tanker. H is hazardous materials and P is passenger."},{"id":"per-1lq545x","q":"A license shows restriction B. What does it mean?","a":"The driver must wear corrective lenses","o":["The driver must wear corrective lenses","The driver may drive only in daylight","The driver may drive only an automatic","The driver may not carry passengers"],"why":"Handbook Section 4B: restriction B means the driver must wear corrective lenses."},{"id":"per-1a1qjnm","q":"A license shows restriction G. What does it mean?","a":"The driver may drive only during daylight hours","o":["The driver may drive only during daylight hours","The driver must wear corrective lenses","The driver must use a prosthetic aid","The driver may drive only on roads posted 40 mph or less"],"why":"Handbook Section 4B: restriction G limits the driver to daylight hours only."},{"id":"per-f7i842","q":"A license shows restriction 7. What does it mean?","a":"The driver may operate only a vehicle with an automatic transmission","o":["The driver may operate only a vehicle with an automatic transmission","The driver may drive only on roads with a posted speed of 40 mph or less","The driver may operate only a motorcycle with an engine of 90 cc or less","The driver may operate only a street legal all-terrain vehicle"],"why":"Handbook Section 4B: restriction 7 means an automatic transmission only."},{"id":"per-1nzjoiq","q":"What does the Driver License Compact let member states do?","a":"Exchange driver records and forward convictions to the home state","o":["Exchange driver records and forward convictions to the home state","Issue one national driver license that every member state accepts","Waive the written test for drivers who move between member states","Share vehicle registration fees and insurance records between states"],"why":"Handbook Section 2B: members exchange driver records and forward convictions to the driver's home state."},{"id":"per-1bp4ez0","q":"A Utah driver ignores a citation received in another member state. What can the home state do?","a":"Suspend the driving privilege until the citation is settled","o":["Suspend the driving privilege until the citation is settled","Cancel the vehicle registration until the fine is paid","Send the driver to jail right away and cancel the registration","Nothing, because tickets from other states do not count"],"why":"Handbook Section 2B: the home state suspends the privilege until proof of compliance is received."},{"id":"per-do113j","q":"Which of these can prove your identity and lawful status for a regular Class D license?","a":"A valid, unexpired U.S. passport","o":["A valid, unexpired U.S. passport","A student ID card with a photo","A library card from your city","An insurance ID card in your name"],"why":"Handbook Section 4E: a valid, unexpired U.S. passport or passport card is accepted."},{"id":"per-rd813t","q":"You do not have your Social Security card. Which document with your name and full number may you present?","a":"A W-2 form","o":["A W-2 form","A school transcript","A utility bill","A vehicle title"],"why":"Handbook Section 4E: a W-2, SSA-1099, non-SSA-1099, or pay stub may be used."},{"id":"per-rcau8b","q":"A first-time Utah applicant under 19 needs proof of driving experience. What shows it?","a":"Completion of a driver education course","o":["Completion of a driver education course","A letter from a parent","One full year of verified paid work history","A passing score on a vision test"],"why":"Handbook Section 4E: evidence of a driver education course if under 19, or a license from another state."},{"id":"per-x9spl8","q":"What happens to your out-of-state driver license when you apply for a Utah license?","a":"It must be surrendered","o":["It must be surrendered","You keep it as a second ID","It is returned after 90 days","It is mailed to your old state by you"],"why":"Handbook Section 4F: the out-of-state license must be surrendered upon application."},{"id":"per-18i1mpf","q":"A replacement driver license has what expiration date?","a":"The same date as the license it replaces","o":["The same date as the license it replaces","Eight years from the date the replacement is issued","Five years from the replacement date","Six months from the replacement date"],"why":"Handbook Section 4G: a replacement keeps the expiration date of the license it replaces."},{"id":"per-1c3unqj","q":"What must happen when you get a duplicate license?","a":"You pass an eye exam and have a new photo taken","o":["You pass an eye exam and have a new photo taken","You retake the written test and the driving test","You pass an eye exam and retake the written test","You bring a new birth certificate and a new photo"],"why":"Handbook Section 4G: an eye exam must be passed and a new photograph taken."},{"id":"per-zs0t8m","q":"Utah's good driver program requires no more than how many reportable violations in the past eight years?","a":"Six","o":["Six","Two","Four","Ten"],"why":"Handbook Section 4G: you must not have more than six reportable violations in eight years."},{"id":"per-1qqm1xi","q":"Your driver license has been expired for a long time. What may you have to do?","a":"Pass the written and driving skills tests again","o":["Pass the written and driving skills tests again","Pay a late fee and have a new photo taken","Wait six months, then apply for a new permit","Take a vision test and a defensive driving class"],"why":"Handbook Section 4G: you may have to retake both tests, depending on how long it has been expired."},{"id":"per-1meixb6","q":"A military member had a valid Utah license when entering the service. For how long after discharge may it still be used?","a":"Up to 90 days","o":["Up to 90 days","Up to 30 days","Up to six months","Up to one year"],"why":"Handbook Section 4G: up to 90 days after discharge or termination of orders."},{"id":"per-1ihtrfq","q":"How soon must a CDL holder apply in person for a duplicate license after a change of address?","a":"Within 30 days","o":["Within 30 days","Within 10 days","Within 90 days","At the next renewal"],"why":"Handbook Section 4H: Class A, B, and C holders apply in person within 30 days. Class D holders notify within 10 days."},{"id":"per-fa33a8","q":"Who may get a Utah identification card?","a":"Only a Utah resident","o":["Only a Utah resident","Any U.S. citizen anywhere","Anyone with a passport","Any licensed driver from another state"],"why":"Handbook Section 4I: only a Utah resident may obtain a Utah ID card."},{"id":"per-n503en","q":"Does a person driving a farm tractor for agricultural work need a Utah driver license?","a":"No, not when driving it for the agricultural activity","o":["No, not when driving it for the agricultural activity","Yes, a Class D license is needed for any tractor","Yes, a license is needed when it is on any public road","Yes, if the tractor weighs more than 10,000 pounds"],"why":"Handbook Section 2A: no license is needed for farm tractors used with agricultural activity."},{"id":"per-1i65466","q":"Which of these keeps you from getting a Utah driver license?","a":"A traffic citation or warrant that has not been settled","o":["A traffic citation or warrant that has not been settled","Wearing glasses or contact lenses while you drive","Living in a rented apartment rather than owning a home","Being a full-time student at a high school in your own city"],"why":"Handbook Section 2A: an unsettled citation or warrant is a reason you may not be licensed."},{"id":"per-11tx9dy","q":"Which agency handles vehicle plates and titles?","a":"The DMV, under the Utah State Tax Commission","o":["The DMV, under the Utah State Tax Commission","The Utah Highway Patrol and local police departments","The Utah Highway Patrol","The State Office of Education"],"why":"Handbook History: the DMV handles plates and titles. The Driver License Division is not part of the DMV."},{"id":"per-houlm3","q":"Who is served first at a Driver License Division office?","a":"People with appointments","o":["People with appointments","Walk-in customers","Customers over age 65","Whoever arrived earliest that day"],"why":"Handbook Section 4C: appointments take priority over walk-ins."},{"id":"per-hobtba","q":"What happens to the documents you bring to the Driver License Division?","a":"They are imaged and returned to you right away","o":["They are imaged and returned to you right away","They are kept in the office file for at least 30 days","They are mailed back to you within two weeks","They are kept by the division for one year"],"why":"Handbook Section 4C: documents are imaged and stored securely and immediately returned."},{"id":"per-r9om3b","q":"A bank returns your check for a license fee. What must you pay to keep your driving privilege?","a":"A $20 service charge","o":["A $20 service charge","A $5 service charge","A $100 reinstatement fee","Nothing, if you pay within a week"],"why":"Handbook Section 4C: a returned check costs a $20 service charge."},{"id":"per-1fxtxqj","q":"What is the handbook fee for a learner permit?","a":"$19.00","o":["$19.00","$9.00","$29.00","$42.00"],"why":"Handbook Section 3C fee table lists the learner permit at $19.00."},{"id":"per-1p7dk5n","q":"What is the handbook fee for a provisional Class D license for drivers under 21?","a":"$39.00","o":["$39.00","$52.00","$19.00","$27.00"],"why":"Handbook Section 3C fee table lists the provisional Class D license at $39.00."},{"id":"per-4a63e9","q":"An out-of-state driver education course is a few hours short of Utah's requirement. What may you do?","a":"Make up the remaining hours at an approved Utah driving school","o":["Make up the remaining hours at an approved Utah driving school","Take an extra written test that covers the topics you missed","Ask your high school principal to sign off on the missing hours","Drive extra hours with a parent or guardian to make up the time"],"why":"Handbook Section 3A: if additional training is needed, you may make up the remaining hours at an approved Utah driving school."},{"id":"per-1lap73s","q":"A limited-term driver license is issued to a non-citizen whose status qualifies for what?","a":"A REAL ID certificate","o":["A REAL ID certificate","A commercial driver license","A motorcycle endorsement","A driving privilege card"],"why":"Handbook Section 4A: a limited-term license goes to a non-U.S. citizen with verified lawful status who qualifies for a REAL ID certificate. A driving privilege card is for people who do not qualify."}]},{"id":"tests","name":"Tests & Paperwork","icon":"📝","src":"Handbook: Examinations","qs":[{"id":"tes-1a6nw4g","q":"What score do you need to pass the Utah written knowledge test?","a":"80% or better","o":["80% or better","70% or better","75% or better","90% or better"],"why":"The written test passing score is 80% or better."},{"id":"tes-qp3yzd","q":"How long is a passing written test score valid for an entry-level permit?","a":"18 months","o":["18 months","6 months","12 months","24 months"],"why":"A passing score stays valid 18 months for the entry-level permit."},{"id":"tes-14zfckv","q":"How is the written knowledge test timed?","a":"It is untimed","o":["It is untimed","30 minutes total","60 minutes total","15 minutes total"],"why":"The test is untimed. Most people take 30 to 45 minutes."},{"id":"tes-azm09c","q":"The written test fee covers how many attempts within 12 months?","a":"Up to three","o":["Up to three","Up to two","Five in a year","Unlimited tries"],"why":"The fee covers up to three attempts in 12 months. Three more need another fee."},{"id":"tes-q8t8j9","q":"What score is required on the online Traffic Safety and Trends Exam?","a":"100%","o":["100%","80%","70%","90%"],"why":"First-time Class D applicants must score 100%, and they may retake it as needed."},{"id":"tes-11m2n0z","q":"Who may be in the car during the driving skills test?","a":"Only you and the examiner","o":["Only you and the examiner","You, the examiner, and a parent","You and a friend","You, the examiner, and your instructor"],"why":"Only the applicant and the examiner ride along."},{"id":"tes-1q9dkzu","q":"Who provides the vehicle for the driving skills test?","a":"The applicant","o":["The applicant","The testing office","The examiner","A rental service"],"why":"You bring a registered, clean, safe vehicle."},{"id":"tes-un4z63","q":"Which of these is NOT required on a skills test vehicle?","a":"A front license plate","o":["A front license plate","A working horn designed for the vehicle","A driver's side window that rolls down","Tires with no bald spots"],"why":"The front plate is not required after January 1, 2025. The rest still are."},{"id":"tes-1fys8az","q":"Which of these will automatically fail a skills test?","a":"Failing to yield to a pedestrian","o":["Failing to yield to a pedestrian","Asking the examiner to repeat a direction","Checking mirrors before a lane change","Adjusting your seat before you start"],"why":"Failing to yield to others is an automatic fail, along with speeding, rolling stops, and avoidable crashes."},{"id":"tes-1e1vbvh","q":"What must you bring to the skills test besides your permit?","a":"Valid registration and insurance for the vehicle","o":["Valid registration and insurance for the vehicle","Your school transcript and the receipt for your test fee","A certified copy of your birth certificate again","A written note from a parent or your school"],"why":"Bring your permit, valid registration, and valid insurance."},{"id":"tes-10iew1c","q":"How many driving skills tests can you take in one day?","a":"One","o":["One","Two","Three","As many as you need"],"why":"Only one skills test per day is allowed."},{"id":"tes-1mgl3he","q":"Tests must be completed within how long after paying the test fee?","a":"Six months","o":["Six months","Three months","One year","Eighteen months"],"why":"All tests must be finished within six months of paying."},{"id":"tes-1jny5ay","q":"Which of these must be working on a vehicle you bring to the driving skills test?","a":"The horn and the brake lights","o":["The horn and the brake lights","A backup camera and parking sensors","Cruise control and the radio","The air conditioning and the heater"],"why":"The checklist requires a working horn, brake lights, turn signals, safety belts, and a parking brake."},{"id":"tes-wuu8wz","q":"The Utah Class D vision standard requires acuity of at least:","a":"20/40 in at least one eye","o":["20/40 in at least one eye","20/20 in each of your eyes","20/30 in at least one eye","20/60 in at least one eye"],"why":"Class D needs 20/40 in at least one eye and a 90 degree visual field."},{"id":"tes-zk03n7","q":"What is the most written knowledge tests you can take in one day?","a":"Two, if the division can fit them in","o":["Two, if the division can fit them in","One, because each test needs its own visit","Three, if you arrive early in the day","Four, if you pay an extra fee for each"],"why":"The division gives up to two written tests per day when it can."},{"id":"tes-g3m5mo","q":"You failed the written test and need to come back. What must you do?","a":"Schedule a written retest appointment","o":["Schedule a written retest appointment","Walk in the next morning without an appointment","Wait 30 days before you try the test again","Retake driver education before the next try"],"why":"A failed attempt that needs a return trip requires a scheduled retest appointment."},{"id":"tes-19vm4tx","q":"You fail the written test three times. What happens next?","a":"You pay another fee for three more tries","o":["You pay another fee for three more tries","You wait one year before you can try again","You must retake driver education and start over","You lose your permit and start the process over"],"why":"The fee covers three tries in 12 months. After that, another fee buys three more."},{"id":"tes-1isx1sf","q":"Who must take the online Traffic Safety and Trends Exam?","a":"All first-time regular Class D applicants","o":["All first-time regular Class D applicants","First-time applicants who are under age 18","Drivers who failed the skills test one time","Drivers renewing a license after 8 years"],"why":"First-time Class D applicants must pass it, and they can retake it as often as needed."},{"id":"tes-19dn4mc","q":"About how much of the Traffic Safety and Trends Exam covers the main causes of traffic deaths?","a":"50 percent","o":["50 percent","10 percent","25 percent","90 percent"],"why":"Half of its questions are based on Utah Highway Safety Office data about leading causes of traffic deaths."},{"id":"tes-b9ghjy","q":"What is the minimum age to take the driving skills test at a Driver License Division office?","a":"16","o":["16","15","17","18"],"why":"The division tests at 16 and older. Third-party testers and high schools can test at 15."},{"id":"tes-fwaowb","q":"What may happen if you fail the driving skills test three times?","a":"You pay another fee","o":["You pay another fee","You wait one full year","You must retake driver education","Your permit is cancelled"],"why":"Handbook Section 6C: failing to pass in three attempts will result in paying another fee."},{"id":"tes-78ef5v","q":"Which mirror setup must a skills test vehicle have?","a":"Two rear view mirrors, one outside on the driver's left","o":["Two rear view mirrors, one outside on the driver's left","One inside mirror, plus a backup camera on the screen","One outside mirror on the passenger's right and a backup camera","Two rear view mirrors, one outside on the passenger's right"],"why":"The checklist requires two rear view mirrors, with one on the outside to the driver's left."},{"id":"tes-12ps5gw","q":"Which of these is required on a skills test vehicle?","a":"A working emergency or parking brake","o":["A working emergency or parking brake","A navigation screen mounted on the dashboard","A cruise control system that works well","Tinted windows on the rear and side doors"],"why":"The test car needs a working emergency or parking brake, a horn, brake lights, and safety belts."},{"id":"tes-1qtfy6l","q":"What must be true about the tires on your skills test vehicle?","a":"They have no bald spots","o":["They have no bald spots","They are all brand new","They are all winter tires","They are the same brand"],"why":"The checklist says tires cannot have bald spots."},{"id":"tes-1eq40pd","q":"Your skills test vehicle has an unregistered plate. What will happen at the test?","a":"The test will not be given","o":["The test will not be given","The examiner will add points to your score","You can take the test but must pay a fine","The test will be given with a warning"],"why":"Skills tests are not given with unregistered or unsafe vehicles."},{"id":"tes-k4u62g","q":"You drive over a curb for no reason during the skills test. What is the result?","a":"An automatic failure","o":["An automatic failure","One minor point off","A warning only","Nothing, if you did not hit anyone"],"why":"Driving over sidewalks or curbs unnecessarily is an automatic failure."},{"id":"tes-719l0r","q":"Which of these is an automatic failure on the skills test?","a":"The examiner has to take control of the vehicle","o":["The examiner has to take control of the vehicle","You ask the examiner to repeat a direction you missed","You check your mirrors before every turn and lane change","You turn on the heater or the windshield wipers"],"why":"If the examiner must take control, the test is failed."},{"id":"tes-zoib0i","q":"During the skills test, you roll through a stop sign without stopping. What happens?","a":"You automatically fail","o":["You automatically fail","You lose a few points","You get a warning","Nothing, if no one was near"],"why":"Rolling through stops is an automatic failure."},{"id":"tes-1spil86","q":"Which of these is scored on the driving skills test?","a":"Parallel parking and parking on a hill","o":["Parallel parking and parking on a hill","How quickly you finish the whole route","The age and brand of the car you drive","Your score on the written knowledge test"],"why":"The test scores turns, starting and stopping, backing, and parking on hills, between cars, and parallel."},{"id":"tes-1nv3txd","q":"Your learner permit expires before you finish all your testing. What may happen?","a":"You may have to take additional tests","o":["You may have to take additional tests","Nothing changes, your scores still count","You pass the skills test automatically","You must wait a full year to reapply"],"why":"Expired permits or expired earlier tests may mean more testing."},{"id":"tes-hishpd","q":"Which steering styles are accepted during the skills test?","a":"Hand-over-hand or push-pull, hands on the outside","o":["Hand-over-hand or push-pull, hands on the outside","Only hand-over-hand, with one hand inside the rim","One hand on top of the wheel the whole time","Both hands on the inside spokes of the wheel"],"why":"Both hand-over-hand and push-pull are fine if your hands stay on the outside of the wheel."},{"id":"tes-129j09i","q":"You booked a renewal appointment but really need a skills test. What can happen?","a":"Your appointment may be voided","o":["Your appointment may be voided","The clerk gives the skills test anyway","Nothing, since all appointments are the same","You get a free retest"],"why":"Booking the wrong service can void your appointment, so book the right one."},{"id":"tes-17p090b","q":"Which documents does the Driver License Division accept?","a":"Originals or certified copies from the issuing agency","o":["Originals or certified copies from the issuing agency","Photocopies of your birth certificate and other papers","Faxes sent straight from the agency that issued them","Phone pictures of your documents on your screen"],"why":"Faxes and photocopies are not accepted."},{"id":"tes-189u2ro","q":"Which testing service gives driving skills tests besides the Driver License Division?","a":"Third-party testers","o":["Third-party testers","Insurance agents","Auto repair shops","Licensed car dealers"],"why":"Third-party testers and some high schools give skills tests and may charge their own fee."},{"id":"tes-19g5ilg","q":"Skills test vehicles must have turn signals working where?","a":"Both front and back","o":["Both front and back","Only in the back","Only on the driver's side","Only in the front"],"why":"Handbook Section 6C: the vehicle needs both front and back turn signal lights."},{"id":"tes-lsvvah","q":"What must be true of the driver's side window on a skills test vehicle?","a":"It rolls down","o":["It rolls down","It is tinted","It is cracked open","It has a sun shade on it"],"why":"Handbook Section 6C: the driver's side window must roll down."},{"id":"tes-1kmkvkn","q":"What must be true of the windshield on a skills test vehicle?","a":"It allows an entire unobstructed field of vision","o":["It allows an entire unobstructed field of vision","It may have a small crack as long as it is away from the driver's view","It has a tinted strip across the top","It has stickers on the driver's side"],"why":"Handbook Section 6C: the windshield must allow an entire unobstructed view."},{"id":"tes-wt7afj","q":"What must be true of the doors on a skills test vehicle?","a":"The driver and front passenger doors open from inside and outside","o":["The driver and front passenger doors open from inside and outside","The doors lock automatically once the car reaches ten miles per hour","The front doors have power windows and power locks","The rear doors are child-locked from the inside"],"why":"Handbook Section 6C: front doors must open from both the inside and outside."},{"id":"tes-2jnvpl","q":"What must be true of the passenger seat on a skills test vehicle?","a":"It is permanently attached","o":["It is permanently attached","It folds flat","It has a built-in cup holder","It is a removable bench"],"why":"Handbook Section 6C: a passenger seat permanently attached to the vehicle."},{"id":"tes-14tz5ds","q":"A skills test vehicle should be:","a":"Registered, clean, free of unnecessary debris and odor, and safe to drive","o":["Registered, clean, free of unnecessary debris and odor, and safe to drive","With a full tank of gas, a spare tire, a first aid kit, and jumper cables in the trunk","A newer model with an automatic transmission and low mileage","Rented from the test site or from a third-party tester"],"why":"Handbook Section 6C: the vehicle must be registered, clean, free of debris and odor, and safe."},{"id":"tes-1pkijpc","q":"Who may come with you to the license office carrying a valid license for your skills test?","a":"A parent, guardian, or spouse who is at least 18","o":["A parent, guardian, or spouse who is at least 18","A friend who is 19 and has had a license for two years","A sibling who is 20 and has a valid driver license","No one, because you must come to the office alone"],"why":"Handbook Section 6C: a person 21 or older, or a parent, guardian, or spouse at least 18."},{"id":"tes-1jba2mt","q":"How are driving skills tests scheduled?","a":"By appointment only","o":["By appointment only","Walk in any day","By phone on the day of the test","At the end of the written test"],"why":"Handbook Section 6C: skills tests are given by appointment only."},{"id":"tes-9mtlkj","q":"Will the skills test examiner ask you to do anything unsafe or illegal?","a":"No","o":["No","Yes, to test your reactions","Yes, during a lane change","Only on the freeway"],"why":"Handbook Section 6C: you will not be asked to do anything unsafe or illegal."},{"id":"tes-5msotr","q":"During the skills test the examiner will:","a":"Ask questions or give directions but not make general conversation","o":["Ask questions or give directions but not make general conversation","Chat with you throughout the whole test to help you stay calm and relaxed","Stay silent until the test is over, then give your score","Coach you on each turn and warn you before each mistake"],"why":"Handbook Section 6C: the examiner will not engage in general conversation."},{"id":"tes-se6ndn","q":"Which of these will you be asked to do during the skills test?","a":"Complete multiple lane changes","o":["Complete multiple lane changes","Drive only on the freeway during the test","Drive without using a signal","Parallel park twice in a row"],"why":"Handbook Section 6C: you will be asked to complete multiple lane changes."},{"id":"tes-kcxrpr","q":"After the driving skills test, the examiner will:","a":"Discuss your results and give recommendations","o":["Discuss your results and give recommendations","Mail your score and a letter of advice within a week","Allow a second test the same day","Give the results to your parent only"],"why":"Handbook Section 6C: the examiner discusses the results and gives recommendations."},{"id":"tes-e86sbz","q":"You fail the skills test. What are you expected to do?","a":"Practice before taking another test","o":["Practice before taking another test","Retake it later the same day after a short break","Retake it right away","Take driver education again"],"why":"Handbook Section 6C: you are expected to practice, and may wait days or weeks."},{"id":"tes-1md6aav","q":"Which of these is part of what you are scored on during the skills test?","a":"Driving posture and adequate use of lanes","o":["Driving posture and adequate use of lanes","The brand and model year of your own vehicle","The opinion of the parent waiting in the lobby","How much fuel you use on the test route"],"why":"Handbook Section 6C: scoring includes driving posture and adequate use of lanes."},{"id":"tes-1wdqkr4","q":"The written knowledge test questions are based on:","a":"The information in the Driver Handbook","o":["The information in the Driver Handbook","Questions copied from other states' tests","Material taught only in class","Insurance company guides"],"why":"Handbook Section 6A: the questions are based on the information in the handbook."},{"id":"tes-117strz","q":"Besides the written test, what must an entry-level learner permit applicant pass?","a":"An eye test","o":["An eye test","A driving skills test","A hearing test","A road sign sorting test"],"why":"Handbook Section 3B: the applicant must pass the written test and an eye test."},{"id":"tes-reclp7","q":"You cannot pass the vision test at the office. What form do you take to an ophthalmologist?","a":"A Certificate of Visual Examination","o":["A Certificate of Visual Examination","A Functional Ability Evaluation","A Medical Advisory form for the DMV","A vision waiver"],"why":"Handbook Section 5A: you take a Certificate of Visual Examination (CVE) to an ophthalmologist."},{"id":"tes-rx0quq","q":"Third-party driving testers are certified and licensed as what?","a":"Commercial driver education instructors","o":["Commercial driver education instructors","State highway patrol troopers","Insurance adjusters licensed by the state","Retired driver license office clerks"],"why":"Handbook Section 6C: third-party testers are licensed commercial driver education instructors."},{"id":"tes-hk872m","q":"Which condition can lead a driving skills test not to be given?","a":"Inclement weather","o":["Inclement weather","A bright sunny day","Dry pavement","A short route"],"why":"Handbook Section 4C: tests are not given when conditions such as inclement weather could create unsafe driving."},{"id":"tes-1ovgdnp","q":"What may a person who fails the skills test three times have to do?","a":"Pay another fee","o":["Pay another fee","Wait one full year","Retake driver education","Turn in the permit"],"why":"Handbook Section 6C: failing to pass in three attempts results in paying another fee."}]},{"id":"ready","name":"Get Ready to Drive","icon":"💺","src":"Handbook: Preparing Your Vehicle","qs":[{"id":"rea-hhwgzq","q":"Who in the car must wear a fastened safety belt or ride in a child seat?","a":"Everyone in the vehicle","o":["Everyone in the vehicle","Only the driver","The driver and front passenger","Anyone under 16"],"why":"Utah requires everyone to be belted or in a child seat."},{"id":"rea-1alby34","q":"How much space should you leave between your chest and the steering wheel?","a":"About 10 inches","o":["About 10 inches","About 4 inches","About 6 inches","About 15 inches"],"why":"Leave 10 inches so the air bag can inflate safely."},{"id":"rea-6291m3","q":"Where should the lap belt sit?","a":"Across your hips, not your stomach","o":["Across your hips, not your stomach","Across your stomach and ribs","Across your lower chest","Across your stomach, above the hips"],"why":"A lap belt crosses the hips. A belt on the stomach can injure organs."},{"id":"rea-1te3bqx","q":"Where should the shoulder belt cross your body?","a":"Over your shoulder and chest","o":["Over your shoulder and chest","Under your arm and across the ribs","Behind your back and across the lap","Across your neck and upper chest"],"why":"Never wear it under the arm or behind the back."},{"id":"rea-pk6rjv","q":"Children age 8 and under need an approved child seat unless they are how tall?","a":"57 inches","o":["57 inches","48 inches","52 inches","60 inches"],"why":"Children age 8 and under need a seat until they are 57 inches tall."},{"id":"rea-14g6jds","q":"How long should a child ride rear-facing, if the seat allows?","a":"Until at least age 2 and 30 pounds","o":["Until at least age 2 and 30 pounds","Until at least age 1 and 20 pounds","Until at least age 3 and 40 pounds","Until 6 months"],"why":"The handbook says rear-facing until at least age two and 30 pounds."},{"id":"rea-1h1p9tj","q":"A forward-facing child seat with a harness is used until at least:","a":"Age 4 and 40 pounds","o":["Age 4 and 40 pounds","Age 2 and 25 pounds","Age 6 and 60 pounds","Age 3 and 30 pounds"],"why":"After rear-facing, use a harness seat until at least age four and 40 pounds."},{"id":"rea-o0wwa9","q":"Where should children 12 and under ride?","a":"Buckled in a rear seat","o":["Buckled in a rear seat","In the front with a belt","In the front if they are tall","On an adult's lap"],"why":"Children 12 and under belong in the back seat."},{"id":"rea-h1fpgc","q":"Which is never safe for an infant?","a":"Riding in front of a passenger-side air bag","o":["Riding in front of a passenger-side air bag","Riding in an approved rear-facing seat in the back","Riding in the middle of the back seat, buckled in","Riding in a rear-facing seat behind the driver"],"why":"Infants should never ride in front of a passenger-side air bag."},{"id":"rea-13ezibj","q":"Where should the head restraint touch your head?","a":"The back of your head, above ear level","o":["The back of your head, above ear level","The base of your neck, below ear level","The top of your head, above ear level","The back of your head, at chin level"],"why":"Set it so it contacts the back of the head above ear level."},{"id":"rea-14ks7ba","q":"How should you set your outside mirrors?","a":"To cut blind spots and show adjacent lanes","o":["To cut blind spots and show adjacent lanes","To show as much of your own car as possible","To show the road directly behind your car","To point down so you can see the pavement"],"why":"Set them wide to minimize blind spots."},{"id":"rea-e2itau","q":"Smoking in a car with a passenger 15 or younger is:","a":"An infraction","o":["An infraction","Fine with a window open","Fine if a parent is driving","A felony"],"why":"Smoking while transporting a child 15 or younger is an infraction in Utah."},{"id":"rea-l80hpt","q":"Which type of vehicle is exempt from the belt law?","a":"A school bus","o":["A school bus","A pickup truck","A minivan","A taxi"],"why":"Exempt vehicles include school buses, motorcycles, mopeds, authorized emergency vehicles, and vehicles built without belts."},{"id":"rea-1vimshu","q":"A 7 year old is 50 inches tall. What does Utah require?","a":"An approved child seat or booster seat","o":["An approved child seat or booster seat","A lap and shoulder belt in the back seat","The front seat with a lap and shoulder belt","Nothing extra, since seven year olds can use belts"],"why":"Children 8 and under need a car or booster seat unless they are 57 inches tall."},{"id":"rea-sy6lap","q":"A child who is 8 or younger is already 57 inches tall. What may the child use?","a":"A regular safety belt","o":["A regular safety belt","Nothing, belts are not needed","The front seat with no restraint","A lap belt behind the back"],"why":"The child seat rule ends at 57 inches. Everyone still needs a belt."},{"id":"rea-1xkdq3q","q":"A booster seat is used from about age 4 and 40 pounds until:","a":"The belt fits correctly and the child is 57 inches tall","o":["The belt fits correctly and the child is 57 inches tall","The child turns six years old and weighs at least 50 pounds","The child can sit still and buckle the belt alone","The child reaches 4 feet 2 inches and weighs 60 pounds"],"why":"Use a booster until the adult belt fits properly and the child reaches 57 inches."},{"id":"rea-faf1z7","q":"How much force does a 150 pound person create in a crash at 30 mph?","a":"About 4,500 pounds","o":["About 4,500 pounds","About 450 pounds","About 1,500 pounds","About 9,000 pounds"],"why":"Crash force is body weight times speed. 150 times 30 is 4,500."},{"id":"rea-1g89qhd","q":"Being thrown from a car in a crash makes your chance of being killed how many times greater?","a":"23 times","o":["23 times","3 times","10 times","50 times"],"why":"The handbook says ejection makes death 23 times more likely."},{"id":"rea-9z4wf","q":"About 70 percent of crashes happen at speeds under:","a":"40 mph","o":["40 mph","20 mph","55 mph","65 mph"],"why":"Most crashes happen at speeds under 40 mph, so belts matter even on short trips."},{"id":"rea-cpr9mp","q":"How close to home do three of four fatal crashes happen?","a":"Within 25 miles","o":["Within 25 miles","Within 2 miles","Within 100 miles","Over 200 miles away"],"why":"Three of four fatal crashes happen within 25 miles of home."},{"id":"rea-1ve0c0q","q":"How can a safety belt ticket be waived in Utah?","a":"By completing an online 30 minute safety belt course","o":["By completing an online 30 minute safety belt course","By taking an in-person safety belt class for two hours","By paying the fine plus a late fee within 30 days","By writing an apology letter to the officer who cited you"],"why":"The fine may be waived by finishing the online safety belt course."},{"id":"rea-1e4ubew","q":"A 17 year old passenger is not wearing a belt. When can that passenger be cited?","a":"When the car is stopped for another reason","o":["When the car is stopped for another reason","Not at all, since belts are required under age 16","When the car is traveling faster than 55 mph","When the car is being driven after dark"],"why":"Passengers 16 and older can be cited for a belt violation if the car is stopped for something else."},{"id":"rea-gro0vv","q":"Air bags can inflate at up to how fast?","a":"200 mph","o":["200 mph","50 mph","100 mph","400 mph"],"why":"Air bags can open at up to 200 mph, so sit back from the wheel and wear your belt."},{"id":"rea-50csei","q":"Taking apart or changing an air bag system so it will not work is:","a":"A Class B misdemeanor","o":["A Class B misdemeanor","A parking ticket","Allowed for repairs","A Class C infraction only"],"why":"Disabling or modifying an air bag system is a Class B misdemeanor."},{"id":"rea-1dtf3xf","q":"Where should the top of the steering wheel be?","a":"Below your chin and no higher than your shoulders","o":["Below your chin and no higher than your shoulders","At eye level, so you can see over the top of the dash","Level with your nose and your arms fully extended","At the top of your head so you can see the whole dash"],"why":"Keep the wheel top at or below shoulder level, under your chin."},{"id":"rea-18xpov4","q":"If your car has a day/night inside mirror, how should it be set?","a":"For the time of day you drive","o":["For the time of day you drive","On the night setting for all driving","Aimed at the passenger seat to cut glare","To the setting your front passenger likes"],"why":"Handbook Section 7B: if you have a day/night mirror, set it for the time of day you drive."},{"id":"rea-152faua","q":"When your outside mirrors are set correctly, what can you barely see?","a":"The sides of your own vehicle","o":["The sides of your own vehicle","The road far behind your vehicle","Nothing of your own vehicle at all","The hood and front of your vehicle"],"why":"Handbook Section 7B: set the mirrors so you can barely see the left and right sides of your vehicle."},{"id":"rea-pvi49k","q":"Your inside mirror should be set so it:","a":"Frames the rear window","o":["Frames the rear window","Shows only the back seat","Points at the road behind the trunk","Shows only the left lane"],"why":"The inside mirror should frame your rear window."},{"id":"rea-1kgumiv","q":"How should your foot move between the gas and brake?","a":"Easily, with your heel resting on the floor","o":["Easily, with your heel resting on the floor","With your whole leg lifted off the floor each time","With your heel lifted and the ball of your foot down","With your heel braced against the door panel"],"why":"Keep your heel on the floor and pivot between the pedals."},{"id":"rea-31qlj8","q":"Which child car seat is acceptable?","a":"One that is crash tested and meets federal standards","o":["One that is crash tested and meets federal standards","One bought used that has been in a minor crash","One built at home from a store-bought safety kit","Any seat with a label showing the maker and the model year"],"why":"Seats must be crash tested and meet Federal Motor Vehicle Safety Standards."},{"id":"rea-1h4u21o","q":"How can drivers and front passengers lower their air bag risk?","a":"Sit as far back as is practical","o":["Sit as far back as is practical","Sit about four inches from the wheel","Disconnect the air bag in your car","Recline the seat for more room"],"why":"Sit as far back as practical and always wear the lap and shoulder belt."},{"id":"rea-vv3ndb","q":"A child must ride in the front seat. What should you do?","a":"Move the seat as far back as possible and use the right car seat","o":["Move the seat as far back as possible and use the right car seat","Put the child on an adult's lap and have them share the shoulder belt","Slide the seat forward so the child can see out the window","Recline the seat back and use a lap belt on the child"],"why":"If the front is the only choice, slide the seat back and secure the child in the right seat."},{"id":"rea-3mjqok","q":"Is a safety belt likely to trap you in a fire or in water?","a":"No, fire or water is in under 1 percent of injury crashes","o":["No, fire or water is in under 1 percent of injury crashes","Yes, belts jam in about half of all the crashes that involve fire","Yes, about one in five injury crashes involves fire or water","Yes, belts trap people in about one crash in ten"],"why":"Less than half of one percent of injury crashes involve fire or submersion."},{"id":"rea-pprkhy","q":"In Utah, about two of three motor vehicle deaths would not have happened if:","a":"Everyone had worn a safety belt","o":["Everyone had worn a safety belt","Speed limits had been lowered 5 mph","Every car had been fitted with air bags","Drivers had all taken a driving class"],"why":"About two of three deaths could be prevented by belts."},{"id":"rea-15we3rj","q":"Which of these must a driver check before moving the car?","a":"Lights and gauges, like fuel, ABS, and air bag lights","o":["Lights and gauges, like fuel, ABS, and air bag lights","The radio presets, the cabin temperature, and the clock","The tire brand, the paint color, and the floor mats","The clock, the air freshener, and the seat heater"],"why":"Check lights and gauges after turning on the ignition, before you shift and go."},{"id":"rea-skite1","q":"When starting an automatic car, it must first be in:","a":"Park","o":["Park","Reverse","Drive","Low gear"],"why":"Handbook Section 8A: be sure the vehicle is in P (park) before starting the engine."},{"id":"rea-4sb9q","q":"How should you sit when you adjust your seat?","a":"Straight, with your back against the seat and feet on the floor","o":["Straight, with your back against the seat and feet on the floor","Leaning back with one arm on the door and one hand on the wheel","Leaning forward with your chest close to the wheel to see better","Slightly reclined, with your arms straight out to the wheel"],"why":"Handbook Section 7A: sit straight with your back against the seat and feet on the floor."},{"id":"rea-m5tf71","q":"Children between 8 and 12 years old must be restrained by:","a":"A child restraint device or a safety belt","o":["A child restraint device or a safety belt","Nothing, as long as they ride in the back seat","Only a lap belt in the front seat","A booster seat only"],"why":"Handbook Section 7D: they must use a child restraint device or a safety belt."},{"id":"rea-1qhoafi","q":"Air bags are designed to:","a":"Work with safety belts, not replace them","o":["Work with safety belts, not replace them","Replace safety belts in most newer vehicles","Work only at low speeds","Protect only the front passenger"],"why":"Handbook Section 7E: air bags are designed to work with safety belts, not replace them."},{"id":"rea-1k4bh94","q":"How can drivers remove any danger to children from a deploying air bag?","a":"Properly restrain the children in the back seat","o":["Properly restrain the children in the back seat","Hold the child on an adult's lap in the front seat","Open a window slightly to let the pressure out","Cover the dashboard with a thick blanket"],"why":"Handbook Section 7E: restraining children in the back seat eliminates the danger."},{"id":"rea-1pd6wsa","q":"What can many vehicles do when a child is in the front seat?","a":"Turn off the passenger air bag","o":["Turn off the passenger air bag","Lock the doors when the car reaches speed","Shut off the engine","Move the seat forward"],"why":"Handbook Section 7E: many vehicles can turn off the air bag when a child is present."},{"id":"rea-1vijskw","q":"A driver is stopped and two passengers are not belted. How many citations can be issued?","a":"One for each unrestrained passenger","o":["One for each unrestrained passenger","One for the whole car, no matter who is unbelted","None, only a warning","One for the driver only"],"why":"Handbook Section 7C: a citation can be issued for each unrestrained passenger."},{"id":"rea-yn6m2t","q":"When may an officer stop a vehicle for an unrestrained passenger?","a":"When anyone under 16 is unrestrained","o":["When anyone under 16 is unrestrained","When the driver is under 21 years old","When it is dark and a passenger is unbuckled","When an adult passenger is unrestrained on a freeway"],"why":"Handbook Section 7C: you may be stopped and cited if anyone under 16 is unrestrained."},{"id":"rea-1jgj1um","q":"At what speeds should you wear a safety belt?","a":"At any speed, however slow","o":["At any speed, however slow","Only when driving faster than 40 mph","Only on freeways","Only above 55 mph"],"why":"Handbook Section 7C: belts should be worn at any speed, regardless of how slow."},{"id":"rea-qy2hmw","q":"About how many Utah children under age five are injured in motor vehicle crashes each year?","a":"About 500","o":["About 500","About 50","About 5,000","About 50,000"],"why":"Handbook Section 7D: approximately 500 children under five are injured each year."},{"id":"rea-cghbjv","q":"What should you do to start the engine?","a":"Apply the brake, turn it on, and check the lights and gauges","o":["Apply the brake, turn it on, and check the lights and gauges","Press the gas to prime it, then turn it on and shift into drive","Shift to drive, check traffic, then turn the engine on","Turn it on, then buckle up and adjust your mirrors"],"why":"Handbook Section 8A: apply the brake, turn or push the button on, and check lights and gauges."},{"id":"rea-1yb2c7k","q":"Safety belts help drivers in an emergency because they:","a":"Help the driver keep control of the vehicle","o":["Help the driver keep control of the vehicle","Make the car brake faster on wet or icy roads","Reduce the need to check your blind spots","Keep the engine from stalling on hills"],"why":"Handbook Section 7C: belts help you keep control of your vehicle."}]},{"id":"basic","name":"Basic Driving","icon":"🛞","src":"Handbook: Basic Driving","qs":[{"id":"bas-114bjt","q":"Where must you never back up?","a":"On a freeway or interstate","o":["On a freeway or interstate","In a private driveway","In a shopping center lot","On a quiet residential street"],"why":"The handbook says never back on a freeway or interstate."},{"id":"bas-1214bia","q":"When backing, how should you check behind you?","a":"Look through the rear window","o":["Look through the rear window","Use only the side mirrors","Use only the dashboard camera","Watch only the curb"],"why":"Mirrors do not show the area right behind the car."},{"id":"bas-wengrw","q":"When backing, which way should you steer?","a":"The way you want the back of the car to go","o":["The way you want the back of the car to go","The opposite way from where you want the back to go","Toward the curb until the car is straight","In the direction the front of the car is pointing"],"why":"Steer in the direction you want the rear to move."},{"id":"bas-62v5q2","q":"How long should you signal before a lane change?","a":"At least two seconds","o":["At least two seconds","About one second","Only when a car is nearby","Until the lane change is half done"],"why":"Signal at least two seconds before moving, then head check."},{"id":"bas-o629up","q":"Before changing lanes you should always:","a":"Check mirrors and do a head check","o":["Check mirrors and do a head check","Tap your horn to alert nearby drivers","Brake lightly to warn the traffic behind you","Flash your high beams at the car behind you"],"why":"Check mirrors, signal, and look over your shoulder."},{"id":"bas-hb0cav","q":"Changing lanes in the middle of an intersection is:","a":"Not allowed","o":["Not allowed","Fine if the lane is clear","Fine on a green light","Fine at night"],"why":"Do not change lanes in an intersection."},{"id":"bas-1e5ea02","q":"On a multi-lane road, which lane should you normally use?","a":"The far right lane, unless passing or blocked","o":["The far right lane, unless passing or blocked","The far left lane, to keep up with traffic","The center lane, to stay away from merging cars","Whichever lane seems to be moving the fastest"],"why":"Stay right unless you are passing or the lane is blocked."},{"id":"bas-se6kw1","q":"At a zipper merge, you should:","a":"Use both lanes, then alternate at the merge point","o":["Use both lanes, then alternate at the merge point","Merge early into one lane and keep a large gap","Speed up to get ahead of the cars in the other lane","Stop at the merge point and wait for a big gap"],"why":"With a zipper merge, drivers alternate at the merge point."},{"id":"bas-4la8wi","q":"When you park at a curb, how close should your wheels be?","a":"Within 12 inches","o":["Within 12 inches","Within 24 inches","Within 6 inches","Within 18 inches"],"why":"Park as close as possible, within 12 inches of the curb."},{"id":"bas-1mo4ubm","q":"How close to a fire hydrant may you park?","a":"No closer than 15 feet","o":["No closer than 15 feet","No closer than 5 feet","No closer than 10 feet","No closer than 25 feet"],"why":"Keep 15 feet clear of a hydrant."},{"id":"bas-1z12e0b","q":"How close to a crosswalk may you park?","a":"No closer than 20 feet","o":["No closer than 20 feet","No closer than 10 feet","No closer than 15 feet","No closer than 5 feet"],"why":"Stay at least 20 feet back from a crosswalk."},{"id":"bas-1vifrti","q":"How close to the rail at a railroad crossing may you park?","a":"No closer than 50 feet","o":["No closer than 50 feet","No closer than 25 feet","No closer than 15 feet","No closer than 100 feet"],"why":"Do not park within 50 feet of a crossing unless signs allow it."},{"id":"bas-ppz40l","q":"When parking downhill next to a curb, turn your wheels:","a":"Toward the curb","o":["Toward the curb","Away from the curb","Straight ahead","Toward the road"],"why":"Downhill, wheels turn toward the curb so the car rolls into it."},{"id":"bas-avlzg4","q":"When parking uphill next to a curb, turn your wheels:","a":"Away from the curb","o":["Away from the curb","Toward the curb","Straight ahead","It does not matter"],"why":"Uphill, wheels turn away from the curb."},{"id":"bas-1rxnv64","q":"After passing, you may return to the right lane no less than how far from an oncoming vehicle?","a":"200 feet","o":["200 feet","50 feet","100 feet","500 feet"],"why":"Return to the right lane at least 200 feet ahead of oncoming traffic."},{"id":"bas-k6ie46","q":"Which of these is a place where you must not pass?","a":"Before a railroad crossing or bridge","o":["Before a railroad crossing or bridge","On a straight road with a clear view","In the left lane of a multi-lane road","On a road with a broken yellow line on your side"],"why":"Never pass before a railroad crossing or bridge, at intersections, or where view is blocked."},{"id":"bas-dg8oos","q":"Where should your hands be on the steering wheel?","a":"On the outside of the wheel","o":["On the outside of the wheel","At the very top of the wheel","One hand on the inside spokes","Anywhere that feels comfortable"],"why":"Keep both hands on the outside of the wheel."},{"id":"bas-aebhe3","q":"What following distance does the handbook give for normal conditions?","a":"At least two seconds","o":["At least two seconds","At least one second","At least three car lengths","At least ten seconds"],"why":"Use a two-second gap, and more in bad weather."},{"id":"bas-99zrks","q":"When stopped behind another car, you should be able to see:","a":"The bottom of its rear tires","o":["The bottom of its rear tires","Its rear bumper and license plate","The trunk and the rear window","Its brake lights and tailpipe"],"why":"Seeing its rear tires leaves room to pull around."},{"id":"bas-1y36fzr","q":"Where is a U-turn never allowed?","a":"On a freeway","o":["On a freeway","On a wide quiet street with no sign","At a signal with no sign forbidding it","From the left lane of a wide street"],"why":"U-turns are illegal on a freeway, on railroad tracks, and where signs forbid them."},{"id":"bas-1u4v2io","q":"Before you pull out of a parking space, what is the right order?","a":"Shift, check traffic and head, signal, then speed up smoothly","o":["Shift, check traffic and head, signal, then speed up smoothly","Signal, speed up quickly, then check traffic and your head","Speed up, check traffic and head, signal, then shift into gear","Look in the mirror, then signal and pull out right away"],"why":"Shift into gear, do a traffic check and head check, signal if needed, then speed up smoothly."},{"id":"bas-cwazil","q":"Why should you walk around your car before backing out?","a":"Small kids and objects can hide behind your car","o":["Small kids and objects can hide behind your car","It gives your tires time to warm up before you go","Your mirrors already show every spot behind the car","State law requires a walk around before every trip"],"why":"Small kids and objects can hide in the area right behind the car."},{"id":"bas-1vcvjtu","q":"When you back up, what should your hands do?","a":"Left hand on the wheel, right arm over the seat back","o":["Left hand on the wheel, right arm over the seat back","Both hands at the top of the wheel, eyes on the mirrors","Right hand on the wheel, left arm out the window","Left hand on the wheel, right hand on the gearshift"],"why":"Hold the wheel with your left hand, turn, and look through the rear window."},{"id":"bas-cx371w","q":"How should you back up?","a":"Slowly, while looking to the rear until you stop","o":["Slowly, while looking to the rear until you stop","Quickly, so you clear the lane as soon as you can","Slowly, using your mirrors and a quick glance back","At a medium speed, with a glance back at the start"],"why":"Back slowly and keep looking to the rear until you have stopped."},{"id":"bas-wpo2ay","q":"You finish a left turn on a road with two lanes going each way. Which lane do you turn into?","a":"The left lane, right of the centerline","o":["The left lane, right of the centerline","The right lane, as far from the center as possible","The center turn lane, until traffic has cleared","Whichever lane has the fewest cars in it"],"why":"Handbook Section 8C: finish a single left turn in the far-left lane, the lane that matches the one you started from."},{"id":"bas-1rcoeag","q":"You finish a right turn on a multi-lane road. Which lane do you turn into?","a":"The right-most lane","o":["The right-most lane","The left lane","The center turn lane","Whichever lane is empty"],"why":"Handbook Section 8C: finish in the lane that matches the one you started from, then keep right when safe."},{"id":"bas-11ewnnd","q":"You merge into a lane where some cars are close behind you. Who must yield?","a":"The merging driver yields to cars that are a threat","o":["The merging driver yields to cars that are a threat","The cars already in the lane must make room for you","Whichever driver has the bigger vehicle goes first","The driver who is going faster has the right of way"],"why":"Merging drivers yield to continuing traffic that is close enough to be a threat."},{"id":"bas-bavayo","q":"Not using the zipper merge where it is required is:","a":"An infraction","o":["An infraction","A felony","Not a violation","A Class A misdemeanor"],"why":"Violating the zipper merge rule is an infraction."},{"id":"bas-x6ko26","q":"Where should you stop at a stop sign that has a stop line?","a":"Behind the stop line","o":["Behind the stop line","On top of the crosswalk","In the middle of the intersection","Past the line so you can see better"],"why":"Stop behind the stop line or crosswalk, not on top of it."},{"id":"bas-t64x9l","q":"You must stop before the sidewalk when you drive out of:","a":"An alley, a private driveway, or a building","o":["An alley, a private driveway, or a building","A freeway off-ramp onto a quiet city street","A one-way street onto a wider two-way street","A roundabout onto the next county road"],"why":"Stop before the sidewalk or street when entering from an alley, driveway, private road, or building."},{"id":"bas-1jem4uq","q":"You are in a crash. When may you leave the scene?","a":"After the legal requirements have been met","o":["After the legal requirements have been met","Right away, if no one seems to be hurt","After about five minutes of waiting nearby","As soon as the other driver drives away"],"why":"You must stay until you have given your information and helped anyone hurt."},{"id":"bas-1g68d3b","q":"How close to a stop sign may you park?","a":"No closer than 30 feet","o":["No closer than 30 feet","No closer than 10 feet","No closer than 5 feet","No closer than 50 feet"],"why":"Do not park within 30 feet of a stop sign, yield sign, flashing beacon, or traffic signal."},{"id":"bas-1pj7zkh","q":"How close to a fire station driveway may you park?","a":"No closer than 20 feet","o":["No closer than 20 feet","No closer than 10 feet","No closer than 30 feet","No closer than 5 feet"],"why":"Keep 20 feet clear of a fire station entrance."},{"id":"bas-13zfnab","q":"Which of these is a legal place to park?","a":"In a marked stall in a parking lot","o":["In a marked stall in a parking lot","Within 10 feet of a fire hydrant","In front of a driveway you do not use","Double parked beside a parked car"],"why":"Marked stalls are legal. Red curbs, driveways, and double parking are not."},{"id":"bas-1ue41mo","q":"Where may you park on an interstate shoulder?","a":"Only if your vehicle breaks down or you are in distress","o":["Only if your vehicle breaks down or you are in distress","Anywhere the shoulder is wide enough to fit your car","Only for a quick rest or phone call with flashers on","Only if you stay for less than an hour with flashers on"],"why":"Do not park on an interstate shoulder except for a breakdown or distress."},{"id":"bas-pm0uuv","q":"Where is parking never allowed?","a":"On a bridge or in a tunnel","o":["On a bridge or in a tunnel","In a marked stall","Beside an unpainted curb with no signs","In a driveway you own"],"why":"You may not park on a bridge, elevated highway, or in a tunnel."},{"id":"bas-1wv4xl8","q":"What should you do before you leave your parked car?","a":"Set the parking brake, turn off the engine, and lock the doors","o":["Set the parking brake, turn off the engine, and lock the doors","Leave the engine running and the heater on so the car stays warm","Turn off the engine, leave the keys in, and lock the doors","Roll down the windows a little so the car does not overheat"],"why":"Secure the car before you walk away."},{"id":"bas-19euvwk","q":"You park uphill where there is no curb. Which way should you turn your front wheels?","a":"To the right","o":["To the right","To the left","Straight ahead","Toward the road center"],"why":"With no curb, turn the wheels to the right so the car rolls off the road, not into the lane."},{"id":"bas-7tpokf","q":"When you parallel park, where do you first stop?","a":"Parallel to the car you will park behind","o":["Parallel to the car you will park behind","At an angle to the car you will park behind","Two lanes over from the car you will park behind","Half a car length behind the open space"],"why":"Pull up even with the car in front of the space, then back in."},{"id":"bas-1mnlxp4","q":"On a multi-lane road, the left lane is mainly for:","a":"Passing slower vehicles","o":["Passing slower vehicles","Driving slowly to save fuel","Parking for short stops","Trucks and large vehicles only"],"why":"Use the left lane to pass, then move back right."},{"id":"bas-1v2lkp5","q":"Passing another car by driving on the shoulder is:","a":"Never allowed","o":["Never allowed","Allowed on freeways","Allowed at night","Allowed if the car ahead is slow"],"why":"Never pass on the shoulder or by leaving the road."},{"id":"bas-n3ovi1","q":"Someone is passing you. What should you do?","a":"Stay in your lane and keep a steady speed","o":["Stay in your lane and keep a steady speed","Speed up to stay even with the other car","Move toward the edge of the road to give room","Brake firmly so the other driver can finish sooner"],"why":"Do not speed up. Hold your lane and speed so the other driver can finish the pass."},{"id":"bas-1g9ky1o","q":"When may you return to the lane after passing a car?","a":"Once you can see the passed car in your rearview mirror","o":["Once you can see the passed car in your rearview mirror","As soon as your front bumper is past the other car","When you are even with the other car's rear door","As soon as you are at least 100 feet from oncoming traffic"],"why":"Wait until the passed vehicle shows in your mirror, and be at least 200 feet ahead of oncoming traffic."},{"id":"bas-1iu9azl","q":"When is it illegal to pass?","a":"When a hill or curve blocks your view","o":["When a hill or curve blocks your view","When the road ahead is straight and clear","In a marked passing zone with no cars coming","When you are in the left lane on a multi-lane road"],"why":"Never pass where a hill or curve blocks your view."},{"id":"bas-q3fkh2","q":"A car is stopped at a crosswalk. Passing it is:","a":"Never allowed","o":["Never allowed","Allowed if you go slowly","Allowed if you honk","Allowed if no one is crossing now"],"why":"The stopped car may be letting a pedestrian cross, so never pass it."},{"id":"bas-qg9uwo","q":"A snowplow has flashing yellow lights and its blade down. You may not pass on:","a":"The side where the blade is deployed","o":["The side where the blade is deployed","The side away from the blade, at any time","Either side, whenever it is moving slowly","Neither side, even when the blade is up"],"why":"Do not pass on the side where the plow blade is down. With three or more plows in a row, pass on neither side."},{"id":"bas-sbi0wp","q":"You are about to pull away from the curb. Should you signal?","a":"Yes, signal whenever you pull to or from a curb","o":["Yes, signal whenever you pull to or from a curb","No, signals are only needed for turns at corners","Only at night or when it is raining outside","Only when other cars are close by"],"why":"Signal when pulling to or from a curb."},{"id":"bas-1wmamhy","q":"When should you use emergency flashers?","a":"When your vehicle is disabled on the highway","o":["When your vehicle is disabled on the highway","When you are in a hurry to pass slow traffic","When you stop for a minute in a no-parking spot","When you are driving slowly in heavy rain"],"why":"Flashers warn others that your car is stopped or broken down."},{"id":"bas-1rxf1sb","q":"How should you grip the steering wheel?","a":"Firmly but gently with your fingers, not your palms","o":["Firmly but gently with your fingers, not your palms","Tightly, with your palms flat against the rim","Loosely, with one hand held on the inside of the wheel rim","Firmly, with your thumbs hooked through the spokes"],"why":"Use your fingers and keep your thumbs up along the wheel face."},{"id":"bas-1kgidug","q":"Which kind of steering is best for parking, sharp right turns, and fixing a skid?","a":"Hand-over-hand","o":["Hand-over-hand","Pull-push","One-hand steering","Palm spinning"],"why":"Use hand-over-hand for critical steering. Pull-push is smoother for turning."},{"id":"bas-um8its","q":"What is a mistake to avoid in a right turn?","a":"Swinging wide or cutting the corner","o":["Swinging wide or cutting the corner","Using your turn signal for two full seconds","Doing a head check over your right shoulder","Slowing down before you start the turn"],"why":"Do not cut the corner or swing wide. Do a right head check."},{"id":"bas-gf4hb1","q":"You are turning on a road with multiple turn lanes. What should you do?","a":"Stay in your lane until the turn is complete","o":["Stay in your lane until the turn is complete","Move to the next lane once you are halfway through","Use the island to shorten the turn if it is clear","Cut into the next lane to get around slower cars"],"why":"Pick the right lane before the turn and stay in it."},{"id":"bas-1g272aa","q":"You may drive over, across, or within an island:","a":"Never","o":["Never","When no cars are near","When you are turning left","When it is raining"],"why":"Do not drive over, across, or within any part of an island."},{"id":"bas-e26u3v","q":"When is a three-point turn the right choice?","a":"On a two-lane road that is too narrow for a U-turn","o":["On a two-lane road that is too narrow for a U-turn","On a busy four-lane road with no center median","On the freeway shoulder when you miss your exit","On any road where you miss a turn and want to turn back"],"why":"Use it only on a two-lane road too narrow for a U-turn. Going around the block is better."},{"id":"bas-c7crf2","q":"Where is a U-turn not allowed?","a":"On a curve where you cannot see 500 feet each way","o":["On a curve where you cannot see 500 feet each way","On a quiet, wide street where no sign is posted","In your own driveway when you can see clearly","In an empty parking lot with no other cars around"],"why":"Never U-turn where you cannot see traffic for 500 feet in both directions."},{"id":"bas-i9j2oa","q":"From where should you start a legal U-turn?","a":"From the left lane or just right of the center line","o":["From the left lane or just right of the center line","From the right-hand lane, close to the curb or shoulder","From the middle of the nearest crosswalk or stop line","From any lane that has the least traffic in it"],"why":"Start from the left-hand lane or just right of center, with a signal and a head check."},{"id":"bas-hjhm4l","q":"Where should you look for hazards at intersections?","a":"Left and right at driveways, store entrances, and tracks","o":["Left and right at driveways, store entrances, and tracks","Straight ahead, because that is where your car is going to go","At your speedometer and gauges to keep a safe speed","In your rearview mirror for drivers coming up behind you"],"why":"Scan left and right in busy places and where people may step out."},{"id":"bas-1hhjqkc","q":"What is a blind spot?","a":"An area around your car that you cannot see in your mirrors","o":["An area around your car that you cannot see in your mirrors","The part of the road where your headlights do not reach","A stretch of road with no street lights or road signs","A part of the dashboard that is hidden behind the steering wheel"],"why":"Blind spots are areas your mirrors do not show."},{"id":"bas-x8o58l","q":"What is a head check?","a":"Turning your head to look over your shoulder","o":["Turning your head to look over your shoulder","A quick glance at the rearview and side mirrors","Checking your seat belt and head restraint","Looking at the car directly in front of you"],"why":"A head check means looking over your shoulder to see your blind spot."},{"id":"bas-3snktk","q":"After you finish a turn or lane change you should:","a":"Cancel your signal","o":["Cancel your signal","Leave your signal on for a block","Flash your high beams","Honk twice"],"why":"Cancel the signal once the move is complete."},{"id":"bas-105y98t","q":"Right before you turn left, you should do a head check over which shoulder?","a":"Left shoulder","o":["Left shoulder","Right shoulder","Neither","Both at the same time"],"why":"For a left turn, do a head check over your left shoulder."},{"id":"bas-fegbxh","q":"When you stop behind a crosswalk or stop line, you should:","a":"Stop behind it, not on top of it","o":["Stop behind it, not on top of it","Stop with your front tires on the line","Stop past it so you can see better","Stop in the crosswalk if no one is crossing"],"why":"Stay behind the line so pedestrians have room."},{"id":"bas-4srmmv","q":"When you must back up, which side of the road should you keep the vehicle on?","a":"The right-hand side","o":["The right-hand side","The center line","The left-hand side","Whichever side is clearer"],"why":"Handbook Section 8B: keep your vehicle on the right-hand side and do not back unnecessarily long distances."},{"id":"bas-ayisxu","q":"If you are turning while backing, you should:","a":"Make quick checks to the front and sides","o":["Make quick checks to the front and sides","Look only at your side mirrors and rear mirror","Look only through the rear window","Close your eyes and listen"],"why":"Handbook Section 8B: make quick checks to the front and sides while turning in reverse."},{"id":"bas-1o8ty71","q":"Which steering rule applies to both forward and reverse driving?","a":"Turn the wheel in the direction you want to go","o":["Turn the wheel in the direction you want to go","Turn the wheel away from the direction you want to go","Turn the wheel only with one hand","Steer from the bottom of the wheel"],"why":"Handbook Section 8G: always turn the steering wheel in the direction you want to go, forward or in reverse."},{"id":"bas-qa4w2d","q":"When may you straddle or drive over a painted lane marking?","a":"Only to make a legal and safe maneuver","o":["Only to make a legal and safe maneuver","Whenever the lane ahead is moving slowly for you","Anytime at night","Any time you are in a hurry"],"why":"Handbook Section 8C: do not straddle painted lane lines unless it is a legal and safe maneuver."},{"id":"bas-l3f493","q":"What is the gore area?","a":"The area between the solid white lines of a lane and an entering or exiting lane","o":["The area between the solid white lines of a lane and an entering or exiting lane","The paved area outside the solid white line that is kept clear for emergency vehicles","The area between the broken white lines of two lanes that run side by side","A carpool lane that is marked with double white lines on both sides"],"why":"Handbook Section 8C: the gore area lies between solid white lines where lanes enter or exit."},{"id":"bas-l4iato","q":"At a zipper merge, when do vehicles alternate?","a":"When they reach the merge point","o":["When they reach the merge point","As soon as they see the warning sign","A mile before the merge","Never, the first car goes alone"],"why":"Handbook Section 8C: use both lanes until the merge point, then alternate."},{"id":"bas-1r0ojy8","q":"Where is the zipper method most useful?","a":"At a congested merge point, like a construction zone","o":["At a congested merge point, like a construction zone","On an open rural road where lanes stay separate","In a parking lot with many cars backing out","At a four-way stop where all the cars take turns in order"],"why":"Handbook Section 8C: it is for alternating at a congested merge point such as a construction zone."},{"id":"bas-nrq5ay","q":"Traffic is backed up beyond an intersection. What should you do?","a":"Do not stop your vehicle in the intersection","o":["Do not stop your vehicle in the intersection","Stop in the intersection and wait for a gap","Pull into the crosswalk until traffic clears","Honk to get the cars ahead moving again"],"why":"Handbook Section 8C: do not stop the vehicle in the intersection."},{"id":"bas-1ehxyze","q":"Turn signals should be used:","a":"When required, not too early or too late, and canceled after the move","o":["When required, not too early or too late, and canceled after the move","As early as you can, and left on through the whole next block","Whenever other cars are close, and turned off once the turn is half done","At the moment you start turning, and left on until you straighten out"],"why":"Handbook Section 8C: do not signal too early or too late. Cancel after the turn or lane change."},{"id":"bas-vvnptl","q":"Which of these is a place where you may not park?","a":"On a sidewalk","o":["On a sidewalk","In a marked stall in a lot","Beside an unmarked curb with no signs","In your own driveway"],"why":"Handbook Section 8D: you may not park on a sidewalk."},{"id":"bas-v2i08j","q":"If signs are posted, you may not park on the opposite side of the road within how far of a fire station entrance?","a":"75 feet","o":["75 feet","20 feet","50 feet","100 feet"],"why":"Handbook Section 8D: within 75 feet of the entrance on the opposite side, if signs are posted."},{"id":"bas-1p2co36","q":"How close may you park to the edge of an area posted for pedestrian use?","a":"No closer than 30 feet","o":["No closer than 30 feet","No closer than 10 feet","No closer than 50 feet","No closer than 5 feet"],"why":"Handbook Section 8D: not within 30 feet of the edges of a posted pedestrian area."},{"id":"bas-1nb41pd","q":"Colored curb markings may show:","a":"Some no-parking zones","o":["Some no-parking zones","Free all day parking for any vehicle","Bike lanes only","School bus routes"],"why":"Handbook Section 8D: colored curb markings indicate some no-parking zones."},{"id":"bas-q0h8q9","q":"When you park downhill next to a curb, your front tire should:","a":"Touch the curb","o":["Touch the curb","Stay a foot away from the curb","Point straight at the road","Face away from the curb"],"why":"Handbook Section 8D: turn the wheel toward the curb so the front tire touches it."},{"id":"bas-1m1aald","q":"Before you pull to the curb on a hill, do a head check over which shoulder?","a":"The right shoulder","o":["The right shoulder","The left shoulder","Both shoulders in turn","Neither, the mirrors are enough"],"why":"Handbook Section 8D: signal right and do a head check over your right shoulder."},{"id":"bas-x57s2n","q":"When parallel parking, you back until your front bumper is:","a":"In line with the rear bumper of the car you are parking behind","o":["In line with the rear bumper of the car you are parking behind","Even with the front bumper of the car you are parking behind","Touching the bumper of the car you are parking behind","Pointing toward the curb, just past the car you are parking behind"],"why":"Handbook Section 8D: back until your front bumper is in line with that car's rear bumper."},{"id":"bas-1minzkz","q":"When leaving a parallel parking space, when do you move into the traffic lane?","a":"When your car clears the rear bumper of the car ahead","o":["When your car clears the rear bumper of the car ahead","As soon as you shift to drive and signal left","When your front bumper gently touches the car ahead of you","As soon as you can see the lane is clear behind"],"why":"Handbook Section 8D: move into the lane when you clear the rear bumper of the vehicle ahead."},{"id":"bas-a8av4v","q":"When leaving a perpendicular or angle space, you move straight back until:","a":"Your front bumper clears the vehicle parked beside you","o":["Your front bumper clears the vehicle parked beside you","Your rear tires are touching the curb or wheel stop behind you","You can see down the whole lane in both mirrors","You hear a horn from a nearby vehicle"],"why":"Handbook Section 8D: continue straight back until your front bumper clears the vehicle beside you."},{"id":"bas-1bwad2f","q":"What is the first step when passing another vehicle?","a":"Check for oncoming traffic","o":["Check for oncoming traffic","Sound your horn once","Move into the left lane","Speed up to get close behind"],"why":"Handbook Section 8E: how to pass starts with checking for oncoming traffic."},{"id":"bas-1i9pr7i","q":"When you pass, how long should you stay alongside the other vehicle?","a":"No longer than you have to","o":["No longer than you have to","About ten seconds","Until you see the next sign","As long as the road is clear"],"why":"Handbook Section 8E: do not stay alongside the other vehicle any longer than you have to."},{"id":"bas-cnw5mc","q":"If you pass on the right, you must:","a":"Stay on the roadway","o":["Stay on the roadway","Use the shoulder","Drive off the pavement","Use the center turn lane"],"why":"Handbook Section 8E: when passing on the right, it is illegal to leave the roadway."},{"id":"bas-1pcesju","q":"When you pass a bicyclist, you should:","a":"Slow down and give as much space as possible","o":["Slow down and give as much space as possible","Pass quickly while tapping your horn to warn them","Pass close to them so you return to your lane sooner","Follow closely until they move onto the sidewalk"],"why":"Handbook Section 8E: slow down when passing bicyclists to give them as much space as possible."},{"id":"bas-17oeksq","q":"How early should you signal before a turn?","a":"Two seconds","o":["Two seconds","One second","Just as you start turning","Only at night"],"why":"Handbook Section 8F: signals are required for two seconds before turning."},{"id":"bas-y3k3qm","q":"How do you signal that you are slowing down or stopping?","a":"Your brake lights do it if they work and can be seen","o":["Your brake lights do it if they work and can be seen","You must use hand signals each time you slow down or stop","You flash your headlights twice before you brake","You tap your horn once as you start to slow down"],"why":"Handbook Section 8F: working, visible brake lights show you are slowing or stopping."},{"id":"bas-dvma35","q":"Which of these may be used to give signals?","a":"Turn signals, stoplights, or your hand and arm","o":["Turn signals, stoplights, or your hand and arm","Turn signals, headlights, or your hand and arm","Stoplights, your horn, or your high beams","Your horn, your high beams, or your headlights"],"why":"Handbook Section 8F: signals are given by turn signals, stoplights, or hand and arm."},{"id":"bas-195p14t","q":"Is a rolling stop acceptable where a stop is required?","a":"No, you must make a complete stop","o":["No, you must make a complete stop","Yes, when no other cars are in sight","Yes, at a stop sign on a quiet street","Yes, if you slow to under 5 mph first"],"why":"Handbook Section 8H: many people feel a rolling stop is adequate, but you must stop completely."},{"id":"bas-1drnoif","q":"Which of these is a safe stopping habit?","a":"Brake smoothly and do not coast to a stop","o":["Brake smoothly and do not coast to a stop","Brake hard at the last moment before the stop line","Shift to neutral and coast","Pump the gas before stopping"],"why":"Handbook Section 6C tips: stop gently, begin braking early, do not coast to a stop."},{"id":"bas-dxyp6","q":"Stopped to turn, which way should your front wheels point?","a":"Straight ahead","o":["Straight ahead","Toward the turn","Toward the curb","Toward the center line"],"why":"Handbook Section 8I: keep the front wheels aimed straight ahead."},{"id":"bas-1plj9uf","q":"After you finish a turn, you should:","a":"Accelerate to the speed of traffic and move into the right-most lane when safe","o":["Accelerate to the speed of traffic and move into the right-most lane when safe","Stop briefly to check your mirrors and signals, then accelerate to the speed of traffic","Slow down, then switch to the fastest lane as soon as it is clear","Accelerate to the posted speed and stay in the lane you finished in"],"why":"Handbook Section 8I: accelerate to traffic speed, then move into the right-most lane when safe."},{"id":"bas-1jkoov","q":"A two-point turn is used when:","a":"You cannot drive around the block","o":["You cannot drive around the block","A road is wider than four lanes across","You are on a freeway","You want to park faster"],"why":"Handbook Section 8I: a street, alley, or driveway can be used when you cannot drive around the block."},{"id":"bas-zquaq6","q":"In a reverse two-point turn, how far past the driveway or alley do you drive before backing in?","a":"One car length","o":["One car length","Two car lengths","Ten feet","Fifty feet"],"why":"Handbook Section 8I: drive one car length past the driveway or alley."},{"id":"bas-1qt75ss","q":"Before backing in a three-point turn, you do a head check over:","a":"Both shoulders","o":["Both shoulders","Only the left shoulder","Only the right shoulder","Neither shoulder"],"why":"Handbook Section 8I: check traffic and head check over both shoulders before reversing."},{"id":"bas-11szg3p","q":"Who sets the rules about U-turns in a city?","a":"Each city has its own laws, so know the law where you drive","o":["Each city has its own laws, so know the law where you drive","The state sets one law for every city, and cities cannot change it","The county sets the rule for every city inside the county","The Driver License Division posts the rules for each city"],"why":"Handbook Section 8I: each city has its own U-turn laws."},{"id":"bas-pkud1t","q":"When should you check traffic and mirrors at an intersection?","a":"Before, during, and after it","o":["Before, during, and after it","Only before entering the intersection","Only after leaving","Only at stop signs"],"why":"Handbook Section 8C: check traffic and mirrors before, during, and after an intersection, turn, or lane change."}]},{"id":"signs","name":"Road Signs","icon":"🛑","src":"Handbook: Signs","qs":[{"id":"sig-tlcf1r","q":"What does this sign mean?","a":"Come to a full stop, then go when it is safe","o":["Come to a full stop, then go when it is safe","Slow down, look both ways, and go if clear","Stop if cars are coming, then wait for green","Stop and wait for a flagger to wave you on"],"why":"A STOP sign always means a complete stop, then yield where required.","vis":"stop"},{"id":"sig-9h8sk0","q":"What should you do at this sign?","a":"Slow down and let other traffic go first","o":["Slow down and let other traffic go first","Come to a full stop every single time","Speed up to merge ahead of other traffic","Stop only if a pedestrian is crossing"],"why":"A YIELD sign means slow down and let traffic with the right-of-way go first.","vis":"yield"},{"id":"sig-1lfqs59","q":"This sign tells you:","a":"The maximum legal speed is 25 mph","o":["The maximum legal speed is 25 mph","The minimum legal speed is 25 mph","The suggested speed is 25 mph","The speed limit changes in 25 miles"],"why":"A speed limit sign shows the highest legal speed in good conditions.","vis":"speed25"},{"id":"sig-q9x6d8","q":"This round yellow sign means:","a":"A railroad crossing is ahead; slow and look","o":["A railroad crossing is ahead; slow and look","A train station is ahead; watch for pedestrians","A roundabout is ahead; slow down and yield","A truck crossing is ahead; slow and look"],"why":"The round yellow RR sign warns that a crossing is ahead. Be ready to stop.","vis":"rr"},{"id":"sig-vchlo","q":"This white X sign at a crossing means:","a":"A railroad crossing; stop behind the line if a train is coming","o":["A railroad crossing; stop behind the line if a train is coming","Road closed to all traffic ahead; follow the detour signs around it","A railroad museum is just ahead with parking","No parking within 50 feet of the tracks"],"why":"Handbook Section 9I: a white, X-shaped Railroad Crossing sign cautions that a train or railroad vehicle is coming. You must stop behind the stop line.","vis":"crossbuck"},{"id":"sig-1ux0q30","q":"This five-sided sign means:","a":"A school zone or school crossing is near","o":["A school zone or school crossing is near","A playground or park crossing is near","A school bus stop is coming up ahead","A hospital zone is near; keep noise down"],"why":"A pentagon sign warns of a school zone or crossing.","vis":"school"},{"id":"sig-9nhvc3","q":"This sign means:","a":"Do not enter","o":["Do not enter","No parking","One way street","Road closed for the season"],"why":"A red circle with a white bar means you may not enter. You would be going the wrong way.","vis":"dne"},{"id":"sig-t2arsh","q":"You see this sign. What does it tell you?","a":"You are driving against traffic","o":["You are driving against traffic","You are in the wrong lane to turn","You are in a no-passing zone","A detour is ahead"],"why":"WRONG WAY warns you are heading the wrong direction. Stop and turn around safely.","vis":"wrongway"},{"id":"sig-w0next","q":"This sign means:","a":"Traffic moves only the way the arrow points","o":["Traffic moves only the way the arrow points","Two-way traffic begins just past this sign","The detour route leads in the arrow's direction","Only right turns are allowed in that direction"],"why":"ONE WAY means traffic flows only the way the arrow points. Never drive against it.","vis":"oneway"},{"id":"sig-xlxfgz","q":"This sign means:","a":"U-turns are not allowed","o":["U-turns are not allowed","Left turns are not allowed","The road ends ahead","You must turn around"],"why":"A red circle with a slash cancels the picture inside it. This sign bans U-turns.","vis":"nouturn"},{"id":"sig-1s0b41t","q":"Orange signs like this one tell you:","a":"You are near a work zone: slow down","o":["You are near a work zone: slow down","A detour route for slow farm vehicles","A school zone is near: slow down","A rest area is near: slow down to exit"],"why":"Orange signs mark work zones. Slow down even if no workers are in sight.","vis":"roadwork"},{"id":"sig-1mena9k","q":"This yellow diamond warns of:","a":"Pedestrians crossing ahead","o":["Pedestrians crossing ahead","A sidewalk that is ending ahead","Bicycles crossing ahead","A school bus stop ahead"],"why":"Yellow diamonds warn about conditions ahead. This one warns people may be crossing.","vis":"ped"},{"id":"sig-1k64chx","q":"This blue sign tells you:","a":"A hospital is nearby","o":["A hospital is nearby","A rest area is ahead","A helicopter pad is ahead","Handicap parking only"],"why":"Blue signs give services. A white H on blue marks a hospital.","vis":"hospital"},{"id":"sig-12v7mh8","q":"This shield tells you what kind of road?","a":"An interstate highway","o":["An interstate highway","A Utah state route","A U.S. highway route","A county or city road"],"why":"The red, white, and blue shield marks an interstate.","vis":"shield"},{"id":"sig-zgz66p","q":"What shape and color are warning signs?","a":"Yellow diamonds","o":["Yellow diamonds","Red octagons","White rectangles","Green squares"],"why":"Warning signs are yellow diamonds with black symbols or words."},{"id":"sig-rrezky","q":"What color are work zone signs?","a":"Orange with black","o":["Orange with black","Yellow with black","White with black","Blue with white"],"why":"Handbook Section 9I: work zone signs have an orange background with black letters or symbols."},{"id":"sig-t4cao8","q":"What does a red circle with a slash through a picture mean?","a":"The pictured action is not allowed","o":["The pictured action is not allowed","The pictured action is required","The pictured thing is ahead","Do the pictured action with caution"],"why":"A slash means prohibited."},{"id":"sig-saxvaq","q":"A sign says CENTER LANE ONLY with left-turn arrows. The center lane is for:","a":"Left turns only, not for passing","o":["Left turns only, not for passing","Passing slower cars when it is clear","Through traffic that is going straight","Short stops to drop off passengers"],"why":"A shared center left-turn lane is for turning, not passing or through driving."},{"id":"sig-5dg59v","q":"Green, brown, and blue rectangular signs are:","a":"Guide signs","o":["Guide signs","Warning signs","Regulatory signs","Work zone signs"],"why":"Guide signs give directions, places, and services."},{"id":"sig-1sn0jka","q":"A sign has eight sides. What does it mean?","a":"Stop","o":["Stop","Yield","School zone","Railroad crossing"],"why":"A red eight-sided octagon is the STOP sign."},{"id":"sig-vk8gsx","q":"Which shape is a yield sign?","a":"A triangle pointing down","o":["A triangle pointing down","A triangle pointing up","An eight-sided red shape","A circle with a red slash"],"why":"The yield sign is a downward triangle."},{"id":"sig-8q0sxt","q":"Which shape and color is the railroad warning sign ahead of a crossing?","a":"Round and yellow with an X and RR","o":["Round and yellow with an X and RR","Round and white with a black X","Diamond and yellow with an X and RR","Square and blue with an X and RR"],"why":"The round yellow sign with an X and black RR warns of a crossing ahead."},{"id":"sig-shvx86","q":"Guide signs are what colors?","a":"Green, brown, or blue","o":["Green, brown, or blue","Yellow, orange, or white","Red, white, or black","Black, gray, or purple"],"why":"Guide signs give directions and information in green, brown, or blue."},{"id":"sig-rxyetd","q":"Regulatory signs, which tell you the rules, are usually:","a":"White with black, red, or green lettering","o":["White with black, red, or green lettering","Green with white lettering, arrows, or symbols","Yellow with black lettering or symbols","Blue with white lettering or symbols"],"why":"Regulatory signs are mostly white with black, red, or green."},{"id":"sig-1c2z9c5","q":"Warning signs are usually which shape and color?","a":"A yellow diamond with black symbols","o":["A yellow diamond with black symbols","A white rectangle with red lettering","A green square with white lettering","A blue circle with white symbols"],"why":"Warning signs are usually yellow diamonds."},{"id":"sig-1ye2vdz","q":"What do the shape and color of route signs tell you?","a":"The kind of road, like interstate, U.S., or state","o":["The kind of road, like interstate, U.S., or state","How fast traffic is allowed to go on that stretch of road","Which exit is next and how far away it is","Whether the road is a toll road or a free road"],"why":"Route signs show whether you are on an interstate, U.S., state, city, county, or local road."},{"id":"sig-1bz37pe","q":"A brown sign usually points to:","a":"Parks and recreation areas","o":["Parks and recreation areas","Distances to nearby cities","Railroad crossings ahead","Detours and work zones"],"why":"Brown guide signs mark parks, recreation, and cultural sites (MUTCD)."},{"id":"sig-1eftw50","q":"A flagger in a work zone gives you directions. You should:","a":"Follow the flagger","o":["Follow the flagger","Follow the signs only","Ignore the flagger if the road looks clear","Drive around the flagger"],"why":"Always follow a flagger's directions."},{"id":"sig-1tdiva1","q":"When may you drive at normal speed again after a road work zone?","a":"After you see the END ROAD WORK sign","o":["After you see the END ROAD WORK sign","As soon as no workers are in sight","After you have driven another half mile","When the car behind you passes you"],"why":"Obey work zone signs until you pass the end road work sign."},{"id":"sig-1xfr3qf","q":"A railroad crossing has two tracks. Is there always a sign saying so?","a":"No, so always look for more than one train","o":["No, so always look for more than one train","Yes, a sign is posted at every crossing","No, but a second train rarely follows the first","Yes, the number of tracks is painted on the road"],"why":"Not every crossing posts the number of tracks. Always check for a second train."},{"id":"sig-1lb99ri","q":"You see a Bicycle Crossing warning sign. What should you do?","a":"Slow down and watch for riders entering the road","o":["Slow down and watch for riders entering the road","Speed up and pass before the riders reach the road","Honk your horn to warn the riders of your car","Stop completely whether or not riders are present"],"why":"Slow down and be ready to yield to bicyclists."},{"id":"sig-1jrom0c","q":"A red circle with a slash over a left-turn arrow means:","a":"No left turns","o":["No left turns","Left turns only","Left turn ahead","Slow down for a left curve"],"why":"The red circle with a slash means the pictured action is not allowed."},{"id":"sig-xqv2ll","q":"Where may you not make a U-turn, even with no sign?","a":"On a freeway or on railroad tracks","o":["On a freeway or on railroad tracks","In a quiet, empty parking lot","On a wide road with a clear view","At the end of a quiet dead-end street"],"why":"U-turns are illegal on freeways and on railroad crossings.","vis":"nouturn"},{"id":"sig-pll09w","q":"You see this sign with flashing lights and children are going to school. What is the speed limit?","a":"20 mph","o":["20 mph","25 mph","30 mph","15 mph"],"why":"Near schools, the limit is 20 mph when children are present or the lights flash.","vis":"school"},{"id":"sig-lo48od","q":"You see this warning sign but the crosswalk looks empty. What should you do?","a":"Slow down and be ready to stop for anyone who steps out","o":["Slow down and be ready to stop for anyone who steps out","Keep your normal speed and glance at the crosswalk as you pass","Tap your horn to warn anyone near the crosswalk","Move to the next lane and speed up past the sign"],"why":"A warning sign means people may cross, so slow down and watch.","vis":"ped"},{"id":"sig-1t3bn8d","q":"At this sign, there is no stop line or crosswalk painted. Where do you stop?","a":"Before the intersection","o":["Before the intersection","In the middle of the intersection","After the intersection","Anywhere you want"],"why":"If no line or crosswalk is marked, stop before the intersection.","vis":"stop"},{"id":"sig-1e5r6l0","q":"A sign shows a one-way arrow. What must you never do?","a":"Drive against the arrow","o":["Drive against the arrow","Stop at the corner","Turn right at the arrow","Park at the curb"],"why":"Never go the wrong way on a one-way street.","vis":"oneway"},{"id":"sig-4iy7zs","q":"Regulatory signs tell you about:","a":"Traffic directions, lane use, turning, speed, and parking","o":["Traffic directions, lane use, turning, speed, and parking","Where to find hospitals, hotels, gas stations, and restaurants","Detours, slow road machinery, and surface changes","Highway routes, road types, and trip directions"],"why":"Handbook Section 9I: regulatory signs cover directions, lane use, turning, speed, parking, and special situations."},{"id":"sig-o4eve8","q":"Which signs advise you about intersecting roads and direct you to cities and towns?","a":"Guide signs","o":["Guide signs","Warning signs","Work zone signs","Regulatory signs"],"why":"Handbook Section 9I: guide signs are green, brown, or blue and direct you to cities and towns."},{"id":"sig-11nycyu","q":"Guide signs can help you find:","a":"Hospitals, service stations, restaurants, and hotels","o":["Hospitals, service stations, restaurants, and hotels","Speed limit changes, school zones, curves, and hills","Detours, flaggers, and slow road machinery","Lane use rules, turn limits, and parking rules"],"why":"Handbook Section 9I: guide signs mark points of interest and services."},{"id":"sig-1ngfuah","q":"Traffic signs tell you about:","a":"Rules, hazards, and road locations","o":["Rules, hazards, and road locations","Speeds, tolls, and weather forecasts","Gas prices and hotel rates at each exit","Highway numbers and city populations"],"why":"Handbook Section 9I: signs tell about rules, hazards, locations, directions, and services."},{"id":"sig-xljgj3","q":"What do barriers in a work zone do?","a":"Keep you from entering closed roads or dangerous areas","o":["Keep you from entering closed roads or dangerous areas","Mark a safe place to park beside the work crew and equipment","Show you where to pass slow road machinery","Tell you to speed up through the work area"],"why":"Handbook Section 9I: barriers keep you from entering closed roads or areas with danger."},{"id":"sig-17en3yw","q":"In a work zone with a short-term signal, where do you stop?","a":"At the white line, if there is one","o":["At the white line, if there is one","In the middle of the intersection to get a better view","Past the signal","Beside the flagger"],"why":"Handbook Section 9I: if there is a short-term signal, stop at the white line if there is one."},{"id":"sig-1yn8qqs","q":"Which of these is correct in a work zone?","a":"Slow down, be ready to stop quickly, and do not tailgate","o":["Slow down, be ready to stop quickly, and do not tailgate","Speed up to clear it quickly","Follow closely behind the vehicle ahead so you can see ahead","Change lanes often to find the fastest lane"],"why":"Handbook Section 9I: slow down, be ready to stop quickly, and do not tailgate."},{"id":"sig-veflis","q":"What should you do when you cross railroad tracks?","a":"Look both ways and cross quickly without stopping on the tracks","o":["Look both ways and cross quickly without stopping on the tracks","Stop on the tracks briefly to look both ways, then cross slowly","Shift to a lower gear on the tracks to cross slowly","Cross slowly and put the car in neutral to coast"],"why":"Handbook Section 9I: look both ways and cross the tracks quickly. Do not stop on them."},{"id":"sig-1fyvnik","q":"A train is crossing. When may you drive ahead?","a":"When the train is well down the track","o":["When the train is well down the track","As soon as the last train car passes you","When the train's horn stops sounding","When the car ahead of you starts to go"],"why":"Handbook Section 9I: wait until the train is well down the track before you drive ahead."},{"id":"sig-dwfugs","q":"There are lights and gates at a crossing. When may you go?","a":"When the arms have raised and the lights are off","o":["When the arms have raised and the lights are off","When the gate arms begin to rise slowly","When the first train has passed and the horn has stopped","When the car in front of you drives across"],"why":"Handbook Section 9I: wait until the arms have raised and the lights are off and it is safe."},{"id":"sig-172y2t3","q":"You must stop for traffic near a railroad crossing. Where do you wait?","a":"At the stop line before the tracks","o":["At the stop line before the tracks","On the tracks, as long as the gate is up","Beside the gate arm, if there is room","At the first spot where there is a gap"],"why":"Handbook Section 9I: if you must stop for traffic or a signal, wait at the stop line before the tracks."}]},{"id":"signals","name":"Signals & Markings","icon":"🚦","src":"Handbook: Signals & Pavement Markings","qs":[{"id":"sig-1loskh","q":"What does a steady red light mean?","a":"Stop behind the line and wait for green","o":["Stop behind the line and wait for green","The light is about to change to red","Slow down and proceed with caution","Stop, look both ways, then go straight if clear"],"why":"Stop before the stop line or crosswalk. A right turn on red is allowed after a full stop unless posted.","vis":"red"},{"id":"sig-1fn2edf","q":"What does a steady yellow light mean?","a":"The light is about to turn red","o":["The light is about to turn red","The light is about to turn green","Speed up to clear the intersection","Proceed without caution"],"why":"Yellow warns that red is coming. Prepare to stop.","vis":"yellow"},{"id":"sig-84yz07","q":"What should you do at a flashing yellow light?","a":"Slow down and proceed with caution","o":["Slow down and proceed with caution","Stop completely for ten seconds","Treat it exactly like a stop sign","Treat it like a protected green arrow"],"why":"A flashing yellow means proceed carefully and be ready to stop.","vis":"flashyellow"},{"id":"sig-1wc2c7j","q":"What should you do at a flashing red light?","a":"Stop, check both ways, go when safe","o":["Stop, check both ways, go when safe","Slow down and proceed with caution","Stop if you see cross traffic coming","Come to a full stop, then wait for a steady green"],"why":"A flashing red acts like a stop sign.","vis":"flashred"},{"id":"sig-1f9bzh3","q":"What does a green arrow mean?","a":"Go the arrow's way, yielding to those inside","o":["Go the arrow's way, yielding to those inside","Go in any direction, since the way is clear","Go only after cross traffic has stopped for you","Yield to every car coming from your left"],"why":"A green arrow is a protected move, but you still yield to people already in the intersection.","vis":"greenarrow"},{"id":"sig-1qw039h","q":"What does a flashing yellow arrow mean?","a":"You may turn after yielding to oncoming traffic","o":["You may turn after yielding to oncoming traffic","You have a protected turn; oncoming cars must stop","You must stop, then turn when no cars come","The turn is prohibited until the arrow turns green"],"why":"A flashing yellow arrow allows a permitted turn. Yield first.","vis":"flashyellowarrow"},{"id":"sig-1hb9zx6","q":"What does a red left arrow mean?","a":"Left turns are not allowed; stay stopped","o":["Left turns are not allowed; stay stopped","Left turns are allowed after a full stop","Yield to oncoming traffic, then turn left","Proceed with caution; the signal is about to change"],"why":"A red arrow means that turn is prohibited while it shows.","vis":"redarrow"},{"id":"sig-10pwdbn","q":"On a vertical traffic signal, red is:","a":"On top","o":["On top","In the middle","On the bottom","On any lamp"],"why":"Vertical signals run red, yellow, green from top to bottom."},{"id":"sig-1wist0r","q":"A traffic signal is dark because of a power outage. What do you do?","a":"Stop, then yield to the vehicle on your right","o":["Stop, then yield to the vehicle on your right","Stop, then yield to any vehicle coming from your left","Slow down and proceed as if it were flashing yellow","Stop, then yield to vehicles making a left turn"],"why":"A dead signal means a full stop, then yield to the driver on your right unless an officer directs you."},{"id":"sig-1m2bz6y","q":"A police officer waves you through a red light. You should:","a":"Follow the officer","o":["Follow the officer","Stop for the red","Wait for the light to change","Go around the officer"],"why":"Officer directions override signals and signs."},{"id":"sig-1noxily","q":"When may you turn right on a red light?","a":"After a complete stop, unless a sign says no","o":["After a complete stop, unless a sign says no","After a rolling stop, if the road is clear","After slowing to a safe speed, if no one is near","Whenever a car is waiting behind you"],"why":"Stop first, yield, then turn unless NO TURN ON RED is posted."},{"id":"sig-1kpqmv8","q":"On a green light, you still must:","a":"Yield to pedestrians and vehicles in the intersection","o":["Yield to pedestrians and vehicles in the intersection","Come to a brief stop before entering the intersection","Slow to 10 mph as you cross every intersection","Honk to warn drivers waiting on the cross street"],"why":"A green light does not clear the intersection for you."},{"id":"sig-mzbu5l","q":"What does a solid yellow line pair like this mean?","a":"No passing in either direction","o":["No passing in either direction","Passing allowed from either side","Passing allowed from your side","A bicycle lane"],"why":"Double solid yellow lines forbid passing in both directions.","vis":"dblyellow"},{"id":"sig-1ey98a","q":"A broken yellow centerline means:","a":"Passing is allowed from your side when safe","o":["Passing is allowed from your side when safe","Passing is prohibited in both directions","Passing is allowed on the right side of the road","Passing is allowed after you honk to warn traffic"],"why":"Broken yellow lines permit passing from your side when it is safe.","vis":"dashyellow"},{"id":"sig-1y4y5q5","q":"What do white lane lines show?","a":"Traffic moves in the same direction","o":["Traffic moves in the same direction","Traffic moves in opposite directions","A place where passing is banned","A lane reserved for work crews"],"why":"White lines separate traffic going the same way. Yellow separates opposite directions.","vis":"whitedash"},{"id":"sig-ozpbod","q":"Double white lines beside a carpool lane mean:","a":"Do not cross","o":["Do not cross","Cross to pass","Cross to exit anywhere","Bicycles only"],"why":"You cross only at marked access points.","vis":"dblwhite"},{"id":"sig-6aqjqj","q":"Where must you yield to pedestrians?","a":"In any crosswalk, marked or unmarked","o":["In any crosswalk, marked or unmarked","Only in crosswalks that are marked","Only at intersections with signals","Only in school zones and parking lots"],"why":"Yield to people in any crosswalk."},{"id":"sig-r5aj1y","q":"In a flex lane, what does a red X over the lane mean?","a":"The lane is closed to you","o":["The lane is closed to you","The lane is open to buses","The lane is for left turns","The lane is open if empty"],"why":"A green arrow means use the lane. A red X means do not."},{"id":"sig-98mja9","q":"On a horizontal traffic signal, which light is on the left?","a":"Red","o":["Red","Green","Yellow","Blue"],"why":"On horizontal signals, red is on the left, yellow in the middle, and green on the right."},{"id":"sig-w43mev","q":"You are at this light and want to turn right. When may you turn?","a":"After a full stop, if no sign bans it and it is safe","o":["After a full stop, if no sign bans it and it is safe","Right away without stopping, if the road looks clear","Never, because a red light always means no turns","Only after the light has turned yellow again"],"why":"A right turn on red is allowed after a full stop unless a sign says no.","vis":"red"},{"id":"sig-rxzbfs","q":"An officer at the intersection tells you to stop, but your light is green. What do you do?","a":"Stop for the officer","o":["Stop for the officer","Go, since the light is green","Slow down and go","Honk and then go"],"why":"An officer's directions override signals."},{"id":"sig-2bxkw9","q":"You are going straight on a green light. An officer waves you to turn right. What do you do?","a":"Turn right as the officer says","o":["Turn right as the officer says","Go straight, since the light is green","Stop and wait for the officer's next wave","Slow down, then follow the car ahead of you"],"why":"Follow the officer, even if it differs from the light."},{"id":"sig-1k3ergl","q":"What does this left-turn signal tell you about oncoming traffic?","a":"Oncoming traffic has a green light, so yield","o":["Oncoming traffic has a green light, so yield","Oncoming traffic has a red light, so go ahead","Your turn is protected, so oncoming cars stop","Oncoming traffic has a yellow light, so wait"],"why":"A flashing yellow arrow is a permitted turn. Yield to oncoming traffic and pedestrians.","vis":"flashyellowarrow"},{"id":"sig-1rioizz","q":"Which left-turn signal gives you a protected turn?","a":"A green arrow","o":["A green arrow","A flashing yellow arrow","A solid green light","A steady yellow light"],"why":"The green arrow is a protected move. Solid green and flashing yellow arrow are permitted turns."},{"id":"sig-6t4xhy","q":"A red arrow pointing right means:","a":"No right turns until another signal says go","o":["No right turns until another signal says go","Right turns are allowed after a full stop","Yield to traffic, then turn right when clear","Slow down and turn right with caution"],"why":"A red arrow means that turn is prohibited while it shows."},{"id":"sig-100rv3r","q":"A traffic signal has no stop line or crosswalk painted. Where do you stop at red?","a":"Before the intersection","o":["Before the intersection","In the middle of the intersection","Past the signal","Anywhere you like"],"why":"Stop before the intersection if no line or crosswalk is marked."},{"id":"sig-1362dx0","q":"A crosswalk has no paint at an intersection. Must you yield to pedestrians?","a":"Yes, unmarked crosswalks count too","o":["Yes, unmarked crosswalks count too","No, a crosswalk must be painted to count","No, unless a pedestrian signal is showing","Yes, if a sign is posted at the corner"],"why":"Yield to pedestrians in marked or unmarked crosswalks."},{"id":"sig-1w6uemw","q":"A dashed yellow line is on your side and a solid yellow line is on the other side. May you pass?","a":"Yes, when it is safe and no cars are coming","o":["Yes, when it is safe and no cars are coming","No, you may never pass where a solid line is","Yes, but only at night when roads are empty","No, unless you are driving a slow vehicle"],"why":"You may pass when the dashed line is on your side and it is safe."},{"id":"sig-6g6oru","q":"Yellow center lines separate traffic that is:","a":"Moving in opposite directions","o":["Moving in opposite directions","Moving in the same direction","Traveling at different speeds","Reserved for carpools and buses"],"why":"Yellow lines divide opposite directions. White lines divide the same direction."},{"id":"sig-xnuwzp","q":"Flex lanes may be marked with:","a":"Double-dashed yellow lines","o":["Double-dashed yellow lines","Double solid white lines","A single dashed white line","Solid red lines with arrows"],"why":"Flex lanes often have double-dashed yellow lines on either side."},{"id":"sig-fcbt8v","q":"When are flex lanes used?","a":"During rush hours","o":["During rush hours","On major holidays","During bad weather","During night hours"],"why":"Flex lanes open during rush hours. Check overhead signals first."},{"id":"sig-1e8guby","q":"How do you enter a shared center left-turn lane?","a":"Check mirrors, signal, check your left blind spot, steer in","o":["Check mirrors, signal, check your left blind spot, steer in","Signal right, check your right blind spot, then steer into the lane","Stop in the traffic lane, signal, then wait for a gap","Enter the lane 1,000 feet early, then slow for the turn"],"why":"Signal, check your blind spot, and move in smoothly when it is clear."},{"id":"sig-dv2at0","q":"At a continuous flow intersection, how do you turn left?","a":"Cross at the first signal, then follow the far-left signal","o":["Cross at the first signal, then follow the far-left signal","Turn at the main intersection, then follow the far-left signal","Turn left at the main intersection on a green arrow","Cross at the first signal, then stop in the median"],"why":"Follow the first signal to cross the oncoming lanes and the second signal to finish the turn."},{"id":"sig-1j9d754","q":"In a diverging diamond interchange, traffic on the overpass or underpass:","a":"Briefly drives on the opposite side of the road","o":["Briefly drives on the opposite side of the road","Stops midway across the bridge to wait for a signal","Moves onto the shoulder to pass slower cars","Merges into a single lane shared by all cars"],"why":"Cars cross to the other side of the road for a short stretch, then cross back."},{"id":"sig-9v2cmp","q":"At a thru-U-turn intersection, how do you go left?","a":"Go through, make a signalized U-turn, then turn right","o":["Go through, make a signalized U-turn, then turn right","Turn left at the main intersection, then make a U-turn later","Stop and turn around in the road, then go right","Take the next ramp, loop back, and turn left"],"why":"Left turns are removed. You go through, U-turn, and turn right."},{"id":"sig-pzvd7q","q":"At a single-point urban interchange, when may you make a U-turn from the off-ramp?","a":"When you face a green arrow","o":["When you face a green arrow","When you face a red arrow","When you face a solid green light","When the road looks clear"],"why":"A U-turn from the off-ramp is legal only on a green arrow."},{"id":"sig-xppt26","q":"During a power outage at a single-point urban interchange, you should:","a":"Proceed with extreme caution and courtesy","o":["Proceed with extreme caution and courtesy","Treat it as a regular four-way stop","Proceed as if the signals were flashing yellow","Go quickly through to clear the interchange"],"why":"The handbook says it is not treated as a four-way stop. Use extreme caution and courtesy."},{"id":"sig-1vlxtd7","q":"Does a green light mean it is safe to go?","a":"No, check that the path is clear before you go","o":["No, check that the path is clear before you go","Yes, a green light gives you the right of way to go","Yes, if you are driving in the right lane","No, wait three seconds after it turns green"],"why":"On green, still make sure the intersection is clear and cross traffic has stopped."},{"id":"sig-eudsaw","q":"A vertical traffic signal is red on top. Which color is on the bottom?","a":"Green","o":["Green","Yellow","Red","Blue"],"why":"Vertical lights run red, yellow, green from top to bottom."},{"id":"sig-2po2l3","q":"What does a green traffic light mean?","a":"You may go through with caution if the way is clear","o":["You may go through with caution if the way is clear","The light is about to change, so slow down","Slow down and proceed with caution; be prepared to stop","You may go after coming to a complete stop"],"why":"Handbook Section 9H: go through with caution if the way is clear."},{"id":"sig-1wiqfeo","q":"A left turn red arrow does not change and you are stranded. When may you turn left?","a":"From a one-way street onto a one-way street, when it is safe","o":["From a one-way street onto a one-way street, when it is safe","Onto any road, after waiting 30 seconds with your turn signal on","Onto a road with a center turn lane, when it is safe","From a two-way street onto a one-way street, if it is clear"],"why":"Handbook Section 9H: you may turn left from a one-way onto a one-way street when it is safe."},{"id":"sig-1s1vt7l","q":"Which of these are traffic controls you must obey?","a":"Signals, signs, road markings, and directions from officers, workers, and crossing guards","o":["Signals, signs, road markings, and directions from officers, workers, and crossing guards","Signals, signs, and road markings, but not directions from workers","Signals, signs, and directions from officers, but not workers, crossing guards, or markings","Signals, markings, and directions from officers, workers, and tow truck drivers"],"why":"Handbook Section 9G: controls include signals, signs, markings, and directions from officers, workers, and school crossing guards."},{"id":"sig-5ouoqg","q":"What do pavement markings do?","a":"Divide lanes, show where to pass, and mark turn lanes and crosswalks","o":["Divide lanes, show where to pass, and mark turn lanes and crosswalks","Show the speed limit and parking areas, and warn of sharp curves ahead","Divide lanes and mark parking spaces, but not crosswalks or turn lanes","Mark work zones and show where road repairs will start soon"],"why":"Handbook Section 9D: markings divide lanes, show where you may pass, and mark turn lanes and crosswalks."},{"id":"sig-11kjcvl","q":"At a continuous flow intersection, right turns on red are:","a":"Restricted, so watch for signs showing when you may turn","o":["Restricted, so watch for signs showing when you may turn","Allowed after a full stop, the same as at other intersections","Not allowed at any time of day or night","Allowed when no pedestrians are crossing"],"why":"Handbook Section 9C: free-right and right-on-red are restricted. Watch the traffic control signs."},{"id":"sig-1d0ni0h","q":"Driving straight through a continuous flow intersection, what should you watch for?","a":"Another light just past the intersection that may be red","o":["Another light just past the intersection that may be red","A median where you must stop and wait for a gap in traffic","A second stop sign past the intersection","A pedestrian bridge where you must slow down"],"why":"Handbook Section 9C: a red light past the intersection lets left-turning cars cross in front of you."},{"id":"sig-1wb6gt4","q":"At a single-point urban interchange, what helps guide you into the right lanes?","a":"Dash lines painted through the interchange","o":["Dash lines painted through the interchange","Flashing blue lights hung over each ramp lane","Toll gates at each ramp entrance","Speed bumps that slow cars at each ramp"],"why":"Handbook Section 9B: dash lines guide drivers into proper lanes. Wrong way signs mark ramps."},{"id":"sig-5g0vnl","q":"After a U-turn at a single-point urban interchange, you re-enter the freeway facing:","a":"A red arrow that is meant for the adjacent traffic","o":["A red arrow that is meant for the adjacent traffic","A green arrow that tells you to merge into traffic","A stop sign at the end of the on-ramp","A flashing yellow light that tells you to yield"],"why":"Handbook Section 9B: on the on-ramp you will face a red arrow intended for the adjacent traffic."},{"id":"sig-nkfn5y","q":"You started a U-turn at a single-point urban interchange. What should you do?","a":"Complete the maneuver without stopping in the intersection","o":["Complete the maneuver without stopping in the intersection","Stop in the middle and wait for the next green light to show","Back up to the stop line and start the turn over","Turn on your hazards and wait for a police officer"],"why":"Handbook Section 9B: do not stop in the middle of the intersection. Complete the maneuver once initiated."},{"id":"sig-h741mi","q":"What does a diverging diamond interchange help reduce?","a":"Many left-turn conflicts at the ramps","o":["Many left-turn conflicts at the ramps","Speed limits on the freeway and nearby roads","Noise from the vehicles near the ramps","The number of lanes on the overpass"],"why":"Handbook Section 9C: it eliminates many left-turn conflicts at the ramps."},{"id":"sig-ua5ejt","q":"What do the signals above a flex lane show?","a":"Which lane is safe to travel","o":["Which lane is safe to travel","The speed limit and the next exit only","Which exit is next","When to pay a toll"],"why":"Handbook Section 9A: signals above the lanes show which lane is safe to travel."},{"id":"sig-frjs8f","q":"A flex lane can carry traffic:","a":"In one direction at certain times and the other direction at other times","o":["In one direction at certain times and the other direction at other times","Toward the freeway on weekend mornings and away from it on weekday evenings","In both directions at the same time, once the lane is empty","In the same direction all day, with buses given priority"],"why":"Handbook Section 9A: some lanes carry traffic one way at certain times and the opposite way at other times."},{"id":"sig-1uupuha","q":"How does a four-legged continuous flow intersection work?","a":"Each of the four legs has displaced left turns","o":["Each of the four legs has displaced left turns","Two of the four legs have displaced left turns","Left turns are removed and cars make U-turns","Every leg uses a roundabout instead of a signal"],"why":"Handbook Section 9C: it works like a regular continuous flow intersection, but every leg uses displaced left turns (you cross the oncoming lanes first, then turn left from the far left side), not just two."},{"id":"sig-bwen7x","q":"Which two left-turn signals are permitted turns, where you must yield to oncoming traffic?","a":"A solid green light and a flashing yellow arrow","o":["A solid green light and a flashing yellow arrow","A green arrow and a solid yellow light together","A flashing red light and a solid red arrow","A green arrow and a flashing red arrow"],"why":"Handbook Section 9I: a left turn is permitted on a solid green light or a flashing yellow arrow. A green arrow is a protected turn."}]},{"id":"rightway","name":"Right-of-Way","icon":"🔀","src":"Handbook: Yielding Right-of-Way","qs":[{"id":"rig-1rqgo3e","q":"Two cars reach a four-way stop at the same time. Who goes first?","a":"The driver on the right","o":["The driver on the right","The driver on the left","The larger vehicle","The driver who honks first"],"why":"Yield to the driver on your right when you arrive together."},{"id":"rig-1ps6id2","q":"When turning left at an intersection, you must yield to:","a":"Oncoming traffic","o":["Oncoming traffic","Cars behind you","Only pedestrians","No one on a green light"],"why":"Left-turners yield to oncoming vehicles and pedestrians."},{"id":"rig-rwjtrt","q":"When pulling out of a driveway onto a public road, you must:","a":"Yield to traffic on the road","o":["Yield to traffic on the road","Go first because you are moving slowly","Honk and go","Use the left lane"],"why":"Traffic on the public road has priority."},{"id":"rig-n1t2n2","q":"When entering the interstate from a ramp, you must:","a":"Yield to interstate traffic","o":["Yield to interstate traffic","Expect others to move over for you","Stop at the end of the ramp","Merge at any speed"],"why":"You must find a gap and yield to traffic already on the highway."},{"id":"rig-1lxtwy1","q":"Before entering an intersection, you should look:","a":"Left, right, then left again","o":["Left, right, then left again","Straight ahead, then to the right","Right, then left only","Only at the signal or sign ahead"],"why":"Handbook Section 9C: look left, right, and then left again before moving, and check for cross traffic, pedestrians, and obstructions."},{"id":"rig-1dhhyo9","q":"An oncoming car has its left turn signal on. You should:","a":"Wait until you see it actually turn","o":["Wait until you see it actually turn","Assume it will turn and go ahead of it","Speed up to pass in front of it","Flash your lights, then start moving"],"why":"Do not rely on signals alone. Wait to see what the driver does."},{"id":"rig-7s9m40","q":"Which way does traffic move around a Utah roundabout?","a":"Counterclockwise","o":["Counterclockwise","Clockwise","Whichever lane is open","Straight through the center"],"why":"Utah roundabouts flow counterclockwise."},{"id":"rig-1i23ske","q":"As you enter a roundabout, you must:","a":"Slow down and yield to traffic and pedestrians","o":["Slow down and yield to traffic and pedestrians","Speed up so you merge before traffic arrives","Stop at the center island until traffic clears","Honk once to warn others and enter ahead of them"],"why":"Slow on approach and yield before entering."},{"id":"rig-1ltx4fd","q":"Under the 2026 law change, a turn signal in a roundabout is:","a":"Not required","o":["Not required","Required at every exit","Required only at night","Required only on entry"],"why":"HB 128 (2026) removed the requirement to signal while turning in a roundabout."},{"id":"rig-13jn4yn","q":"A pedestrian is crossing with a white cane or guide dog. You must:","a":"Come to a complete stop","o":["Come to a complete stop","Slow and honk","Go around them","Proceed if they are far away"],"why":"Always stop for pedestrians who are visually impaired."},{"id":"rig-17iftov","q":"A car ahead of you is stopped at a crosswalk. You should:","a":"Stop behind it and never pass","o":["Stop behind it and never pass","Pass slowly on the left if it is clear","Pass on the right using the shoulder","Honk and wait for it to move"],"why":"Handbook Section 14G: never pass a vehicle stopped at a crosswalk. There may be people crossing that you cannot see."},{"id":"rig-y3z5h7","q":"An emergency vehicle with flashing lights comes up behind you. You should:","a":"Pull to the right and stop until it passes","o":["Pull to the right and stop until it passes","Speed up and get ahead of it to clear the road","Stop in your lane and wait for it to pass you","Keep driving at the same speed"],"why":"Handbook Section 14B: drive at once to the right side of the road and stop until the emergency vehicle has passed."},{"id":"rig-1qvew2u","q":"How far before a turn may you enter a shared center left-turn lane?","a":"No more than 500 feet","o":["No more than 500 feet","No more than 50 feet","No more than 1,000 feet","As far ahead as you want"],"why":"Do not enter the shared lane more than 500 feet before your turn."},{"id":"rig-dpqrqh","q":"You and a car on your left and a car on your right reach a four-way stop at the same time. Who goes first?","a":"The car on your right","o":["The car on your right","The car on your left","The car that is biggest","The car that honks first"],"why":"When you arrive together, yield to the driver on your right."},{"id":"rig-1feslev","q":"At a four-way stop, another driver arrives clearly before you. Who goes first?","a":"The driver who arrived first","o":["The driver who arrived first","The driver on your right side","The driver of the faster car","The driver of the bigger vehicle"],"why":"Handbook Section 9J: yield to a driver who is at the intersection before you. The driver on your right goes first only if you both arrive at the same time."},{"id":"rig-12meax1","q":"You turn left on a flashing yellow arrow. A pedestrian is in the street you are entering. What must you do?","a":"Yield to the pedestrian","o":["Yield to the pedestrian","Honk to warn them","Speed up to turn first","Turn only if you have the bigger car"],"why":"Yield to pedestrians when turning."},{"id":"rig-14hj2j2","q":"You are turning right. A bicyclist is going straight beside you. Who yields?","a":"You yield to the bicyclist","o":["You yield to the bicyclist","The bicyclist yields to you","Whoever reaches the corner first","Whoever goes faster"],"why":"Handbook Section 14A: yield to bicyclists in intersections as you would for pedestrians and other vehicles."},{"id":"rig-1y12ez6","q":"A bike path crosses the road ahead. What must you do?","a":"Yield to bicyclists on the path","o":["Yield to bicyclists on the path","Honk to warn them and keep going","Speed up and cross first","Go ahead, since a path is not a street"],"why":"Handbook Section 14A: yield right-of-way when a bicycle path or bike lane intersects a road."},{"id":"rig-1a6tiqz","q":"A car in the lane next to you stops at a crosswalk. What should you do?","a":"Stop too, since a pedestrian may be hidden","o":["Stop too, since a pedestrian may be hidden","Go around it if the lane looks clear","Honk so the car moves on right away","Speed up to pass before the pedestrian steps out"],"why":"Pedestrians can be hidden by the stopped car. Stop and look."},{"id":"rig-13782zo","q":"A mid-block crosswalk has no signs or lights. What should you do?","a":"Watch for it and yield to pedestrians","o":["Watch for it and yield to pedestrians","Ignore it since it has no markings at all","Drive faster to clear it before anyone steps out","Stop only if you see paint on the road"],"why":"Mid-block crosswalks may have few markings, so watch for them."},{"id":"rig-1kzkp9y","q":"You want to pull away from a parallel parking space. Who has the right-of-way?","a":"Traffic already on the road","o":["Traffic already on the road","You, since you are signaling","Whichever vehicle is bigger","Cars that are waiting to park behind you"],"why":"Yield to traffic when pulling from the curb."},{"id":"rig-rmav5m","q":"The light turns green but a pedestrian is still crossing. What do you do?","a":"Wait until they clear","o":["Wait until they clear","Go around them slowly","Tap your horn so they hurry","Go, since you have a green light"],"why":"Yield to people still in the intersection."},{"id":"rig-11j4vuf","q":"Another driver does not yield to you. What should you do?","a":"Slow down and let them go to avoid a crash","o":["Slow down and let them go to avoid a crash","Keep your speed and insist on your right of way","Speed up to get through before they do","Flash your lights and keep going at your speed"],"why":"Never assume you have the right-of-way."},{"id":"rig-sz8gfw","q":"As you enter a roundabout, you must yield to:","a":"Traffic already in the circle and pedestrians","o":["Traffic already in the circle and pedestrians","Large trucks and buses","Nobody, because entering traffic has the priority","Cars coming from your right side, but not pedestrians"],"why":"Handbook Section 9F: slow down as you approach the roundabout, yield to oncoming traffic and pedestrians, and enter when it is clear."},{"id":"rig-bqrywo","q":"In a roundabout, you may enter when:","a":"Pedestrians are clear and a gap opens","o":["Pedestrians are clear and a gap opens","The car behind you honks to move you along","You are in a hurry and the center is empty","Nobody is on the far side of the circle"],"why":"Wait for pedestrians and a gap in circulating traffic."},{"id":"rig-1s49h3k","q":"A fire engine has stopped on your block for an alarm. May you park there?","a":"No, do not drive or park on the same block","o":["No, do not drive or park on the same block","Yes, if you leave plenty of room for the engine","Yes, if you stay inside your car with the engine on","Yes, but only on the opposite side of the street"],"why":"Do not drive or park on the same block where a fire vehicle has stopped for an alarm."},{"id":"rig-e37cl7","q":"Two cars come to opposite ends of a single-lane bridge. Who goes first?","a":"The first driver to arrive","o":["The first driver to arrive","The driver of the larger vehicle","The driver of the faster car","The driver on the right-hand side"],"why":"On single-lane bridges, the first driver to arrive goes first."},{"id":"rig-1hwcee4","q":"You are on a narrow mountain road and meet a car going uphill while you go downhill. Who should back up or yield?","a":"You yield to the uphill car","o":["You yield to the uphill car","The uphill car yields to you","The driver with the bigger vehicle","Whoever got to the curve first"],"why":"The downhill driver yields to uphill traffic."},{"id":"rig-231r76","q":"A pedestrian is crossing your half of the road. When may you go?","a":"After the pedestrian has crossed at least your half of the road","o":["After the pedestrian has crossed at least your half of the road","As soon as the pedestrian has walked past your front bumper and fender","After you honk and the pedestrian steps back","When no other car is behind you or beside you"],"why":"Handbook Section 14G: remain stopped until the pedestrian has crossed at least your half of the road."},{"id":"rig-f062dm","q":"Why should you watch for pedestrians next to parked or stopped vehicles?","a":"Children can run out from between them","o":["Children can run out from between them","They can block your mirror view of the road","They use the lane as a shortcut","They always signal first"],"why":"Handbook Section 14G: watch for pedestrians next to parked or stopped vehicles, and be ready to stop quickly."},{"id":"rig-944qle","q":"Before you back up, you should check for:","a":"Pedestrians","o":["Pedestrians","Only your mirrors","Only the radio","Only parked cars"],"why":"Handbook Section 14G: check for pedestrians before backing up."},{"id":"rig-x4270j","q":"When may you drive in a bicycle lane?","a":"When entering or leaving an alley or driveway","o":["When entering or leaving an alley or driveway","To pass slower traffic when the lane is empty","To get around a traffic jam if the lane is clear","When you stop for a minute to drop off a rider"],"why":"Handbook Section 14A: do not drive, stop, or park in a bike lane unless entering or leaving an alley or driveway, doing official duties, or in an emergency."},{"id":"rig-1q19ku8","q":"How far may you follow a fire vehicle responding to an alarm, if you are not on official business?","a":"No closer than 500 feet","o":["No closer than 500 feet","No closer than 100 feet","No closer than 50 feet","No closer than 1,000 feet"],"why":"Handbook Section 14B: do not follow within 500 feet of a fire vehicle responding to an alarm."}]},{"id":"speed","name":"Speed & Visibility","icon":"🌙","src":"Handbook: Speed, Night Driving, Challenges","qs":[{"id":"spe-14s71ji","q":"With no sign and no hazards, the limit in a business or residential area is:","a":"25 mph","o":["25 mph","20 mph","30 mph","35 mph"],"why":"The handbook gives 25 mph for business or residential areas without signs."},{"id":"spe-jfxrg9","q":"Near a school during recess or when children arrive or leave, the limit is:","a":"20 mph","o":["20 mph","15 mph","25 mph","30 mph"],"why":"Section 9E (Speed): 20 mph during school recess, opening or closing hours, or when flashing lights operate."},{"id":"spe-yhkakj","q":"The basic speed law says you must never drive:","a":"Faster than is reasonable and prudent","o":["Faster than is reasonable and prudent","Faster than the posted limit at night","Faster than most of the cars around","Faster than 55 mph on any highway"],"why":"You must adjust speed to conditions even below the posted limit."},{"id":"spe-ymyg07","q":"Rural Utah interstates can have limits as high as:","a":"80 mph","o":["80 mph","70 mph","65 mph","90 mph"],"why":"Interstate limits run 65 to 80 mph depending on the area."},{"id":"spe-pwadl8","q":"Driving too slowly can get you a ticket if you:","a":"Hold up traffic","o":["Hold up traffic","Go below the limit at all","Use the right lane","Use cruise control"],"why":"Impeding traffic is a violation."},{"id":"spe-2hase4","q":"When must headlights be on?","a":"From sunset to sunrise, or when visibility is low","o":["From sunset to sunrise, or when visibility is low","From midnight to sunrise, or when it is raining","On freeways and highways after dark, not on side streets","When other drivers near you have their lights on"],"why":"Lights are required from sunset to sunrise and in low visibility."},{"id":"spe-1ptwum7","q":"How close to an oncoming car should you dim your high beams?","a":"Within 500 feet","o":["Within 500 feet","Within 1,000 feet","Within 100 feet","Within 50 feet"],"why":"Dim within 500 feet of oncoming vehicles and within 300 feet when following."},{"id":"spe-16fjhfy","q":"If oncoming headlights blind you, look:","a":"Toward the right edge of the road","o":["Toward the right edge of the road","Straight at the oncoming headlights","Toward the left edge of the road","Down at the dashboard instruments"],"why":"Looking right keeps you in your lane without staring into the lights."},{"id":"spe-1q6rche","q":"At night you should:","a":"Not wear sunglasses or tinted lenses","o":["Not wear sunglasses or tinted lenses","Wear sunglasses to reduce the glare","Drive faster to finish the trip sooner","Use only your parking lights in town"],"why":"The handbook advises no sunglasses or colored lenses at night."},{"id":"spe-kay1q0","q":"Hydroplaning can begin at speeds above about:","a":"35 mph","o":["35 mph","20 mph","50 mph","60 mph"],"why":"Tires can ride up on water above 35 mph."},{"id":"spe-c22lmg","q":"Black ice often looks like:","a":"A wet spot on the road","o":["A wet spot on the road","Dry pavement with white edges","Fresh snow on the road","Loose gravel on the road"],"why":"Black ice is hard to see and can look just wet."},{"id":"spe-17u3e8p","q":"In fog, rain, or snow you should use:","a":"Low beams","o":["Low beams","High beams","Parking lights","No lights"],"why":"High beams reflect off the fog or snow. Use low beams."},{"id":"spe-e7s4jm","q":"Metal-stud snow tires are allowed in Utah during which dates?","a":"October 15 through March 31","o":["October 15 through March 31","November 1 through April 30","Any time of year","September 1 through February 28"],"why":"Studded tires are legal October 15 through March 31."},{"id":"spe-cx6ndv","q":"Speeding fines in highway work zones are at least:","a":"Twice the normal fine","o":["Twice the normal fine","The same as normal","Three times the normal fine","A flat $500"],"why":"Courts must impose at least double in a highway construction zone."},{"id":"spe-u3js23","q":"How does the handbook describe driving 10 mph on an icy road?","a":"It may be too fast","o":["It may be too fast","It is always safe","It is required by law","It is too slow to be legal"],"why":"Section 9E (Speed): driving on an icy road at 10 miles per hour may be too fast."},{"id":"spe-ymy9m8","q":"No sign is posted and you are on a major highway. The limit is:","a":"55 mph","o":["55 mph","65 mph","45 mph","70 mph"],"why":"Major highways are 55 mph unless posted otherwise."},{"id":"spe-fxvc6q","q":"Utah rural interstate speed limits can be:","a":"65, 70, 75, or 80 mph","o":["65, 70, 75, or 80 mph","Always 55 mph, the same as other highways","Only 60 or 65 mph in the whole state","From 85 to 90 mph on the longest stretches"],"why":"Rural interstate limits are 65, 70, 75, or 80 mph, as posted."},{"id":"spe-17ryh51","q":"A transition zone on the road between speed limits is marked by:","a":"Pavement markings and extra signs","o":["Pavement markings and extra signs","A police officer standing beside the road","A row of orange cones across the road","A flashing yellow light above the lane"],"why":"Transition zones use markings and signs to show a change."},{"id":"spe-1v0wssq","q":"When does the 20 mph school limit apply?","a":"At recess, arrival and dismissal, or when lights flash","o":["At recess, arrival and dismissal, or when lights flash","On weekends and holidays when children play outside the school","Between sunset and sunrise when it is hard to see","Within 500 feet of a school bus that is in sight"],"why":"The 20 mph limit is for recess, school opening and closing hours, or when flashing lights operate."},{"id":"spe-t9403r","q":"The school zone lights are flashing. What must you do?","a":"Obey the lower school zone speed limit","o":["Obey the lower school zone speed limit","Drive the normal posted limit for the road","Stop for ten minutes before going on","Pass slowly on the right shoulder"],"why":"Flashing school zone lights mean the lower speed limit is in effect."},{"id":"spe-1bd4657","q":"Which of these is a time to slow down?","a":"When you approach a hilltop","o":["When you approach a hilltop","When the road is wide and empty","When you see a green light","When the road is dry and straight"],"why":"Section 9E (Speed): slow down for curves, hilltops, narrow roads, intersections, and crossings."},{"id":"spe-1uoowg0","q":"You are approaching a curve. What should you do?","a":"Slow down before you reach it","o":["Slow down before you reach it","Speed up to get through it","Brake in the middle of it","Stay at the same speed no matter what"],"why":"Slow before the curve so you stay in control and in your lane."},{"id":"spe-cegjpu","q":"You see people walking beside the road. What should you do?","a":"Slow down and give them room","o":["Slow down and give them room","Honk to warn them and keep going","Speed up to pass them quickly","Keep your speed and move over a bit"],"why":"Slow down for special hazards like people walking beside the road."},{"id":"spe-5uhzk8","q":"You see an authorized vehicle with flashing red, red and white, or red and blue lights ahead. You should:","a":"Slow down","o":["Slow down","Speed up","Honk","Flash your high beams"],"why":"Slow down when approaching authorized vehicles with flashing lights."},{"id":"spe-1xsi6b3","q":"Open highway, rain, and night. Even the 25 mph speed may be:","a":"Too fast","o":["Too fast","Too slow","Perfect","Illegal"],"why":"In rain at night on an open road, 25 mph may still be too fast."},{"id":"spe-1o31rmg","q":"You dim your high beams when following another car within:","a":"300 feet","o":["300 feet","100 feet","500 feet","1,000 feet"],"why":"Dim your high beams within 300 feet of the car ahead, and within 500 feet of oncoming cars."},{"id":"spe-qky17s","q":"At night, how much more following distance should you add?","a":"Two seconds or more","o":["Two seconds or more","One second","Half a second","No extra if your high beams are on"],"why":"Handbook Section 11J: increase your following distance at night by at least two seconds."},{"id":"spe-1ucx23d","q":"A car ahead of you passes a sign. You reach the same sign 1 second later. What should you do?","a":"Slow down, since you are following too closely","o":["Slow down, since you are following too closely","Keep your speed, since one second is enough room","Speed up and pass the car, since it is too slow","Flash your high beams so the car moves over"],"why":"The handbook uses a two second following gap. One second is too close."},{"id":"spe-11phh36","q":"Which parts of the road freeze first in winter?","a":"Bridges, ramps, and overpasses","o":["Bridges, ramps, and overpasses","Parking lots and wide shopping center lots","Dry gravel roads on the edge of town","Roads that run under the tree branches"],"why":"Bridges, ramps, and overpasses freeze first because air flows under them."},{"id":"spe-pkj8ar","q":"Your car is front-wheel drive. How should you use snow or all-season tires?","a":"On all four wheels","o":["On all four wheels","On the front wheels only","On the rear wheels only","On none, since studs are enough"],"why":"The handbook says put snow or all-season tires on all four wheels."},{"id":"spe-1e05w1","q":"Bleeding tar on hot days is:","a":"Slippery","o":["Slippery","Safe to drive on","Only a problem at night","Good for traction"],"why":"Tar can bleed up in hot weather and make the road slippery."},{"id":"spe-8og5q9","q":"Most crashes happen between what hours?","a":"2 p.m. and 6 p.m.","o":["2 p.m. and 6 p.m.","Midnight and 4 a.m.","6 a.m. and 9 a.m.","10 a.m. and noon"],"why":"Most crashes occur from 2 p.m. to 6 p.m."},{"id":"spe-iffbqz","q":"Where is the highest crash rate?","a":"Shopping and business areas","o":["Shopping and business areas","Rural farm roads with little traffic","Mountain passes in the winter months","Freeways late at night in good weather"],"why":"Crash rates are highest in shopping and business areas."},{"id":"spe-65pkud","q":"In Utah two-car fatal crashes, how many of the drivers killed were not at fault?","a":"Over half","o":["Over half","About one in ten","About one in four","Almost none"],"why":"Over half of drivers killed in two-car crashes were not at fault, so drive defensively."},{"id":"spe-572z37","q":"In work zones, who is most often killed or hurt?","a":"Drivers, passengers, and pedestrians","o":["Drivers, passengers, and pedestrians","Only the road workers on the crew","Only the truck drivers on the route","Only the flaggers who direct traffic"],"why":"Over 80 percent of the people hurt or killed are drivers, passengers, or pedestrians."},{"id":"spe-1vqoyug","q":"In a work zone you should:","a":"Leave extra room and obey signs until END ROAD WORK","o":["Leave extra room and obey signs until END ROAD WORK","Follow closely behind the car ahead so traffic moves faster","Ignore the signs when you see no workers in sight","Stop and wait for the workers to wave you through"],"why":"Do not tailgate, and obey posted signs until the end of the work zone."},{"id":"spe-1rbzh7","q":"At a short-term work zone signal, you should stop where?","a":"At the white line, if one is marked","o":["At the white line, if one is marked","In the middle of the work area, if it is clear","Next to the barrier closest to your lane","Just past the signal, before the workers"],"why":"Stop at the white line if one is marked."},{"id":"spe-1dguc68","q":"Besides curves and hilltops, you must slow down when you approach:","a":"An intersection or railroad crossing","o":["An intersection or railroad crossing","A green light with no cross traffic","A long, straight road with no other cars","A wide shoulder with a smooth paved surface"],"why":"Section 9E: slow down when approaching and crossing an intersection or railroad crossing."},{"id":"spe-z8wlu7","q":"Which kind of road requires you to slow down?","a":"Any narrow or winding road","o":["Any narrow or winding road","A road with a painted center line","A road with two lanes each way","A road with a shoulder"],"why":"Section 9E: slow down when traveling on any narrow or winding road."},{"id":"spe-1tmlya0","q":"You must slow down any time you:","a":"Cannot see clearly","o":["Cannot see clearly","See a clear road","Have your headlights on","Drive in light traffic"],"why":"Section 9E: slow down any time you cannot see clearly."},{"id":"spe-1xwek7u","q":"The law says you must slow down when speed would cause you to:","a":"Lose control or leave your lane","o":["Lose control or leave your lane","Pass another car on a two-lane road","Reach your destination ahead of schedule","Burn more fuel than you planned"],"why":"Section 9E: slow down when speed would make you fail to keep control or stay in a single lane."},{"id":"spe-150p2hx","q":"At night, driving the posted speed limit:","a":"May be too fast","o":["May be too fast","Is always safe","Is required in every case","Is legal only on freeways"],"why":"Section 11J: especially at night, the posted speed limit may be too fast."},{"id":"spe-252577","q":"You must use your lights any time conditions keep you from seeing how far ahead?","a":"1,000 feet","o":["1,000 feet","500 feet","1,500 feet","2,000 feet"],"why":"Section 11J: use lights when you cannot see 1,000 feet ahead."},{"id":"spe-3paa1v","q":"When driving at night, you should:","a":"Keep your eyes moving and watch for dark shapes","o":["Keep your eyes moving and watch for dark shapes","Stare at the center line to stay in your lane","Watch the taillights ahead of you to stay in the lane","Keep your eyes on the dashboard lights and gauges"],"why":"Section 11J: keep searching the road and look for dark shapes on the roadway."},{"id":"spe-wyzosn","q":"Where should you look to check for the pavement edge and hazards at night?","a":"Glance to the right and left","o":["Glance to the right and left","Only straight into the headlights","Only down at the dashboard","Only up at the sky"],"why":"Section 11J: glance right and left to check the edge of the pavement and hazards."},{"id":"spe-czgdk6","q":"At night you should increase your following distance by at least:","a":"Two seconds","o":["Two seconds","One half second","Ten seconds","Nothing, it stays the same"],"why":"Section 11J: increase following distance at night by at least two seconds."},{"id":"spe-dt8zdh","q":"A driver coming toward you at night does not dim the high beams. You should:","a":"Look toward the right edge of the road","o":["Look toward the right edge of the road","Flash your own high beams back at them","Look straight at the oncoming headlights","Close your eyes until they have passed"],"why":"Section 11J: look at the right side of the road to avoid being blinded."},{"id":"spe-s49tnz","q":"On a rural road where crops or hills block your view, you should:","a":"Slow down and be ready to stop","o":["Slow down and be ready to stop","Speed up to clear the blind area","Honk once and keep your speed","Drive near the center line"],"why":"Section 11K (Limited view): slow down and be ready to stop."},{"id":"spe-zc80cs","q":"On a narrow rural road with ditches instead of shoulders, you should:","a":"Slow down and center in your lane","o":["Slow down and center in your lane","Drive close to the ditch edge to be safe","Drive on the center line to see better","Speed up to pass oncoming cars"],"why":"Section 11K (Narrow roads): slow down and center your vehicle in your lane."},{"id":"spe-7wogac","q":"You come to an open bridge grating or steel bridge. You should:","a":"Slow down and grip the wheel firmly","o":["Slow down and grip the wheel firmly","Speed up so you cross the grating faster","Brake hard once you are on the bridge","Loosen your grip so the car can settle"],"why":"Section 11K: reduce your speed, increase following distance, and keep a firm grip on the wheel."},{"id":"spe-1et8zad","q":"You approach an uncontrolled rural intersection. You should:","a":"Slow down and be ready to stop","o":["Slow down and be ready to stop","Keep your speed since no light is there","Speed up to cross first","Honk and keep going"],"why":"Section 11K: slow down and be ready to stop for crossing or oncoming traffic."},{"id":"spe-h7xif8","q":"On loose gravel or dirt roads you may:","a":"Skid when you stop","o":["Skid when you stop","Stop faster than on pavement","Brake freely","Drive faster for more grip"],"why":"Section 11K (Gravel or dirt): there is less traction and you may skid when stopping."},{"id":"spe-sr064d","q":"A sign shows a maximum safe speed on a mountain road. You should:","a":"Never exceed it","o":["Never exceed it","Ignore it","Exceed it on straight parts","Exceed it when no one is near"],"why":"Section 11I: if a sign shows a maximum safe speed, never exceed it."},{"id":"spe-1ydor8e","q":"Your vehicle struggles up a steep mountain road. You may:","a":"Pull off safely or stay in the right lane","o":["Pull off safely or stay in the right lane","Move to the center to hold the traffic back","Stop in your lane until the hill clears","Speed up to finish the climb more quickly"],"why":"Section 11I: pull off at a safe place or stay in the right lane so others can pass."},{"id":"spe-13swvr7","q":"Going up a steep mountain grade, you should use:","a":"A lower gear","o":["A lower gear","Neutral","The highest gear","The parking brake"],"why":"Section 11I: you need lower gears to drive up hills and steep mountains."},{"id":"spe-zrsdb1","q":"Going down a steep mountain, gravity causes your speed to:","a":"Increase","o":["Increase","Drop on its own","Stay the same","Fall to zero"],"why":"Section 11I: gravity makes your speed increase, so pick a safe speed and use a low gear."},{"id":"spe-60kd0q","q":"A flagger directs you in a work zone. You must:","a":"Do as the flagger directs","o":["Do as the flagger directs","Follow your own judgment instead","Ignore the flagger if the road looks clear","Follow the car ahead only"],"why":"Section 9I (Work zone signs): you must do as the flagger directs."},{"id":"spe-1p5txot","q":"In a work zone you should also:","a":"Increase your following distance","o":["Increase your following distance","Keep the same following distance","Change lanes often to avoid slow cars","Speed up between the work zone signs"],"why":"Section 11G: slow down, increase your following distance, and be prepared to stop."},{"id":"spe-tvngmg","q":"Why should you slow down in a work zone even when you see no workers?","a":"Narrow lanes and rough pavement are risky","o":["Narrow lanes and rough pavement are risky","The fine only applies near workers","Hidden workers are always standing close by","The legal limit drops to 10 mph in every zone"],"why":"Section 11G: always slow down even if there are no workers. Narrow lanes and rough pavement can be dangerous."},{"id":"spe-1tobluy","q":"Highway work zones include work on:","a":"The road, shoulders, utilities, and trees","o":["The road, shoulders, utilities, and trees","Only paving crews working on the main road","Only bridges and tunnels along the highway","Only closed roads that have full barriers"],"why":"Section 11G: work zones include construction, maintenance, utility work, tree trimming, and surveying."},{"id":"spe-1togs1z","q":"You see a roadside barrier in a work zone. It is there to:","a":"Keep you out of closed or dangerous areas","o":["Keep you out of closed or dangerous areas","Mark a legal place to park while the crew works","Show you where to turn around when the road is closed","Mark the end of the work zone one mile ahead"],"why":"Section 9I (Work zone signs): barriers keep you from entering closed roads or other danger areas."},{"id":"spe-h1ds3m","q":"Under the basic speed law, any speed you drive must also be:","a":"Reasonable and prudent for conditions","o":["Reasonable and prudent for conditions","Under 55 mph on every road","At or above the minimum limit of the road","Matched to the car traveling beside you"],"why":"Section 9E: you may never drive faster than is reasonable and prudent under existing conditions."},{"id":"spe-379zmz","q":"A driver is cited for impeding traffic. This means the driver:","a":"Drove so slowly that traffic backed up","o":["Drove so slowly that traffic backed up","Drove too fast for the road conditions","Passed another car in a no passing zone","Parked on the shoulder of a highway"],"why":"Section 9E: peace officers may cite you for impeding the normal flow of traffic."},{"id":"spe-1iwz2j5","q":"Your vehicle has good traction on ice and snow. You should still:","a":"Drive slowly even if you have good traction","o":["Drive slowly even if you have good traction","Drive faster since you have good traction","Pass slow cars since you have good traction","Use cruise control for steady speed"],"why":"Section 11O (Cold weather): even with good traction on ice and snow, drive slowly."},{"id":"spe-1snfgl6","q":"Before driving in snow or ice you should first clear:","a":"All windows, lights, and wipers","o":["All windows, lights, and wipers","Only the front windshield glass","Only the snow piled on the roof","Only the driver's side window"],"why":"Section 11O (Cold weather): clear ice and snow from the headlights, taillights, wipers, and all windows."},{"id":"spe-8zsgfj","q":"When should you put snow tires on your vehicle?","a":"Before the first snowfall","o":["Before the first snowfall","After the first storm","Only in January","When the road is already icy"],"why":"Section 11O (Cold weather): put them on before the first snowfall."},{"id":"spe-11v98m1","q":"After road crews clear the roads in winter, you should expect:","a":"Slippery spots may remain","o":["Slippery spots may remain","The road to be fully dry","The road to be safe at any speed","Ice only on freeways"],"why":"Section 11O (Cold weather): slippery spots may remain after crews clear the roads."}]},{"id":"freeway","name":"Freeways & Merging","icon":"🛣️","src":"Handbook: Freeways, Ramps & Express Lanes","qs":[{"id":"fre-1cywegr","q":"You missed your freeway exit. What should you do?","a":"Take the next exit","o":["Take the next exit","Back up on the shoulder","Make a U-turn across the median","Stop and wait for a gap"],"why":"Never back up or turn around on a freeway."},{"id":"fre-1y91zta","q":"Using an entrance ramp to leave the freeway is:","a":"Illegal, even in a traffic jam","o":["Illegal, even in a traffic jam","Legal if you use your turn signal","Legal during heavy traffic jams","Legal at night when it is empty"],"why":"Entrance ramps are for entering only."},{"id":"fre-xsw6am","q":"What following distance should you keep on the freeway?","a":"At least two seconds","o":["At least two seconds","At least one second","Half a second at 70 mph","At least ten seconds always"],"why":"Keep at least two seconds and more in bad weather."},{"id":"fre-mo45sh","q":"What is the lane outside the solid white edge line for?","a":"Emergencies only","o":["Emergencies only","Passing","Picking up passengers","Slow vehicles"],"why":"Passing or stopping there to pick people up is illegal."},{"id":"fre-1m194vo","q":"You are driving in the left lane and a faster car comes up behind you. You should:","a":"Move right when it is safe","o":["Move right when it is safe","Stay and speed up","Brake to teach them a lesson","Flash your high beams"],"why":"Left-lane drivers move right so they do not impede traffic."},{"id":"fre-22tx4g","q":"Where may you enter or leave an I-15 express lane?","a":"Where the white lines are dotted","o":["Where the white lines are dotted","Anywhere you see an open space","Only at the very end of the lane","Anywhere you signal first"],"why":"Use the dotted-line access points only."},{"id":"fre-6ug33s","q":"Crossing the double white lines beside an express lane is:","a":"Illegal","o":["Illegal","Legal when traffic is light","Legal if you signal","Legal for trucks only"],"why":"Double white lines mean do not cross."},{"id":"fre-odjbqp","q":"How many people must a car carry to use the I-15 express lane for free?","a":"Two or more","o":["Two or more","Three or more","Four or more","One"],"why":"Cars with two or more occupants may use the lane free."},{"id":"fre-146m6td","q":"In a flex lane, a green arrow means:","a":"The lane is open to you","o":["The lane is open to you","The lane is closed to you","You must exit at the next ramp","The lane is for buses only"],"why":"Check overhead signals before entering."},{"id":"fre-v1k5be","q":"On an entrance ramp you should use the acceleration lane to:","a":"Match the speed of traffic","o":["Match the speed of traffic","Stop and wait for a big gap","Pass the slower cars ahead","Slow down before you merge"],"why":"Match speed, find a gap, then merge."},{"id":"fre-zbn76n","q":"A ramp meter shows red and green. How many cars go per green?","a":"One, unless posted otherwise","o":["One, unless posted otherwise","Two, unless posted otherwise","As many as will fit in the gap","Three, unless posted otherwise"],"why":"One vehicle per green unless signs say otherwise."},{"id":"fre-vgr58i","q":"What is a runaway truck ramp for?","a":"Emergencies only, no stopping or parking","o":["Emergencies only, no stopping or parking","Short rest stops for tired truck drivers","Overflow parking for big rigs at night","An extra passing lane for slow-moving trucks"],"why":"Use it only in an emergency and never park on it."},{"id":"fre-b70dsb","q":"On an exit ramp, you may drive:","a":"No faster than the posted limit","o":["No faster than the posted limit","As fast as the traffic on the freeway","Ten over the limit if the ramp is clear","Whatever speed feels safe to you"],"why":"The posted limit applies on exit ramps too."},{"id":"fre-1gjc1ti","q":"Crossing the solid white line into the striped gore area is:","a":"Illegal","o":["Illegal","Fine for passing","Fine to exit late","Fine in traffic"],"why":"The gore area is not for driving."},{"id":"fre-bb1di8","q":"How long is an express lane access point, marked by white dotted lines?","a":"About 3,000 feet","o":["About 3,000 feet","About 1,000 feet","About 5,000 feet","About 300 feet"],"why":"Access points are about 3,000 feet long and sit near most interchanges."},{"id":"fre-1co5wkx","q":"How can you get out of the I-15 express lane safely before your exit?","a":"Exit one interchange before the one you want","o":["Exit one interchange before the one you want","Cross the double white line just before your exit","Slow down in the express lane and wait for a gap","Stop on the shoulder of the express lane and wait"],"why":"The handbook says leave the express lane one interchange early."},{"id":"fre-zouo83","q":"Which one-person vehicle may use the I-15 express lane for free?","a":"A motorcycle","o":["A motorcycle","A pickup truck","A passenger car","A delivery van"],"why":"Motorcycles, buses, and cars with two or more people may use it free."},{"id":"fre-13zvttq","q":"A single driver with no passengers wants to use the I-15 express lane. What is needed?","a":"A UDOT express pass with an active account","o":["A UDOT express pass with an active account","A monthly lane permit from the police","A carpool sticker from the license office","Nothing extra, it is free for solo drivers at night"],"why":"Solo drivers need a UDOT express pass linked to a credit or debit account."},{"id":"fre-1sebzfq","q":"A police car with flashing lights is behind you in the express lane. What may you do?","a":"Move right out of the lane when safe","o":["Move right out of the lane when safe","Cross the double white line when it looks clear","Stop in the lane and let it pass","Speed up to the next access point"],"why":"You may leave the express lane to the right when safe if followed by an emergency vehicle."},{"id":"fre-1t1wx1e","q":"On a freeway, you may change lanes only to:","a":"Pass, exit, or follow a route change","o":["Pass, exit, or follow a route change","Look at the scenery","Slow down for traffic that is merging ahead","Move away from a truck that is passing"],"why":"Section 9B: change lanes only to pass, get off the freeway, or enter the correct lane for a route separation."},{"id":"fre-10qy3wq","q":"You stay in the left lane of a freeway and a faster car comes up behind you. You may be cited for:","a":"Impeding traffic","o":["Impeding traffic","Careless driving","Reckless driving","Failure to signal"],"why":"Left-lane drivers must move right when approached from behind."},{"id":"fre-oea4ul","q":"When should you slow down to leave a freeway?","a":"After you enter the exit lane","o":["After you enter the exit lane","Before you reach the exit lane, on the main road","Anywhere you like","Right at the exit sign"],"why":"Keep steady speed on the freeway, then slow down in the exit or deceleration lane."},{"id":"fre-r61z48","q":"After you merge onto the freeway, you should:","a":"Cancel your turn signal","o":["Cancel your turn signal","Leave it on for the next mile","Tap your horn twice","Flash your high beams"],"why":"Cancel the signal once you have merged."},{"id":"fre-1imtag","q":"The 'meter on' sign at a ramp meter is dark. What should you do?","a":"Enter as usual","o":["Enter as usual","Stop and wait for green","Wait for a police officer","Turn around"],"why":"Meters work only when the sign is lit."},{"id":"fre-kdy7c7","q":"How fast should you drive on a freeway?","a":"Near the speed of other traffic, but never over the limit","o":["Near the speed of other traffic, but never over the limit","Near the speed of other traffic, even if it is over the limit","Much slower than other traffic, to stay on the safe side","Faster than other traffic so you can merge more easily"],"why":"Match traffic but never go over the posted speed."},{"id":"fre-14rt8nh","q":"Driving on the emergency lane outside the solid white line to pass is:","a":"Illegal","o":["Illegal","Allowed for trucks","Allowed in traffic jams","Allowed at night"],"why":"The emergency lane is for emergencies only. Passing or picking up passengers there is illegal."},{"id":"fre-mddobd","q":"You are on an off-ramp. How fast may you go?","a":"No faster than the posted limit","o":["No faster than the posted limit","Freeway speed until the very bottom","As fast as you like if no one is near","10 mph under the limit at all times"],"why":"The posted limit applies on exit ramps too."},{"id":"fre-4dst7q","q":"A runaway vehicle ramp is for:","a":"Emergencies only, never for parking","o":["Emergencies only, never for parking","Passing slower trucks on long upgrades","Resting during a long drive on a hill","Slow trucks that want to leave the road"],"why":"Do not stop, stand, or park on the ramp or in its path."},{"id":"fre-193ehad","q":"What does a flex lane signal show when you can use the lane?","a":"A green arrow","o":["A green arrow","A red X","A flashing yellow light","A white circle"],"why":"Section 9A: a green arrow means you can use the lane and a red X means you cannot."},{"id":"fre-1hpg4wa","q":"A red X above a flex lane means:","a":"You cannot use the lane","o":["You cannot use the lane","You may use it to pass","The lane is for buses only","The lane ends in one mile"],"why":"Section 9A: a red X means you cannot use the lane."},{"id":"fre-19ugjl","q":"A flex lane may be used during:","a":"Rush hours","o":["Rush hours","Midnight only","Holidays","Weekends only"],"why":"Section 9A: a flex lane may be used during rush hours, with signals above showing which lane is safe."},{"id":"fre-7t69bq","q":"How much is the one-time fee for a C decal for an express lane?","a":"$10","o":["$10","$25","$50","$100"],"why":"Section 9B (C decals): C decals need a one-time $10 registration fee."},{"id":"fre-s5gto5","q":"Where is a C decal placed?","a":"Inside the windshield by the mirror","o":["Inside the windshield by the mirror","On the rear bumper or the trunk lid","On the driver's side window, near the top","On the front license plate, in a corner"],"why":"Section 9B (C decals): small stickers go inside the windshield to the right of the rear view mirror."},{"id":"fre-pfvsub","q":"Which vehicles may a C decal let use the express lane toll free with one person?","a":"Certain clean fuel vehicles","o":["Certain clean fuel vehicles","Any vehicle with only one person","Any loud vehicle","Any vehicle that pulls a trailer"],"why":"Section 9B (C decals): limited single-occupant clean fuel vehicles may use the lanes toll free."},{"id":"fre-wndiqb","q":"Express pass transponders are mounted where?","a":"On the windshield","o":["On the windshield","On the license plate","On the roof","Under the hood"],"why":"Section 9B: express pass transponders are mounted to the windshield and read along the corridor."},{"id":"fre-5pwat6","q":"What is the toll for an express lane based on?","a":"Current rate and distance traveled","o":["Current rate and distance traveled","Only the day of the week you drive","Only the number of people in your car","Only the color and model of your car"],"why":"Section 9B: readers charge accounts based on the current express lanes rate and distance traveled."},{"id":"fre-1icuupx","q":"The I-15 express lanes are dedicated mainly for:","a":"High-occupancy vehicles","o":["High-occupancy vehicles","Heavy trucks","Bicycles and slow farm vehicles","Drivers who want to exit soon"],"why":"Section 9B (Carpool lane): express lanes are travel lanes on I-15 for high-occupancy vehicles."},{"id":"fre-1gruvd3","q":"On an entrance ramp you must yield to:","a":"Drivers already on the interstate","o":["Drivers already on the interstate","Drivers who are still behind you on the ramp","Drivers in the farthest right lane only","No one, since you are entering"],"why":"Section 9J: yield to drivers already on an interstate highway if you are on the entrance ramp."},{"id":"fre-11srefu","q":"What is the first step when you enter a multi-lane highway?","a":"Use the acceleration lane to match speed","o":["Use the acceleration lane to match speed","Stop at the end of the ramp and wait for a gap","Slow to 20 mph on the ramp","Move into the far left lane to pick up speed"],"why":"Section 9B (Entering a multi-lane highway): use the acceleration lane to match speed before pulling onto the road."},{"id":"fre-1i6lceg","q":"When you plan to exit a freeway, you should:","a":"Move to the exit lane early at steady speed","o":["Move to the exit lane early at steady speed","Slow down on the main road early","Wait until the last second, then cut over to the exit","Stop at the exit sign and then turn onto the ramp"],"why":"Section 9B (Exiting a roadway): move to the exit lane early and keep a steady speed while on the main road."},{"id":"fre-zbuje3","q":"What does a ramp meter look like?","a":"A signal with only red and green lights","o":["A signal with only red and green lights","A signal with red, yellow, and green lights","A flashing white light above the ramp","A stop sign with a flashing red light"],"why":"Section 9B (Ramp meters): they only have red and green lights that alternate."},{"id":"fre-14nghvm","q":"Where are ramp meters placed?","a":"On freeway on-ramps","o":["On freeway on-ramps","On freeway off-ramps","In the middle of the freeway","At school crossings"],"why":"Section 9B (Ramp meters): ramp meters are placed on the freeway on-ramps."},{"id":"fre-1q5mzp4","q":"Why does Utah use ramp meters?","a":"To prevent stop-and-go slowdowns","o":["To prevent stop-and-go slowdowns","To raise money from drivers","To make drivers slow down on exit ramps","To mark the entrance to school zones"],"why":"Section 9B (Ramp meters): they help prevent slowdowns and stop-and-go traffic."},{"id":"fre-16vxxxh","q":"You are on the freeway and can drive no faster than:","a":"The posted limit, even if others go faster","o":["The posted limit, even if others go faster","The speed of the fastest car in the left lane","Ten over the limit when traffic is flowing fast","The limit posted for nearby side roads"],"why":"Section 9B: you may not legally drive faster than the posted speed limit."},{"id":"fre-1ydxma","q":"Is it legal to make a U-turn on a freeway?","a":"No, it is illegal","o":["No, it is illegal","Yes, if you signal first","Yes, at night","Yes, if there are no cars"],"why":"Section 9B: do not make U-turns on the freeway, it is illegal."},{"id":"fre-115bi70","q":"What are the double-dashed yellow lines to either side of a flex lane for?","a":"They mark a lane that can change direction","o":["They mark a lane that can change direction","They mark a lane for buses and taxis only","They mark a bike path beside the road","They mark a lane that is closed for repairs"],"why":"Section 9A: a flex lane may have double-dashed yellow lines, and signals show which lane is safe."},{"id":"fre-1vkv3v4","q":"How are the white lane lines marked between express lanes and general lanes?","a":"Crossing is prohibited","o":["Crossing is prohibited","Crossing is allowed anywhere","Crossing is optional","Crossing is allowed for trucks only"],"why":"Section 9D (White lane markings): the line separating an express or carpool lane means crossing prohibited."},{"id":"fre-dw1dbn","q":"The I-15 express lane access point is marked by:","a":"White dotted striping","o":["White dotted striping","Double solid yellow lines","Orange cones","Red reflectors"],"why":"Section 9B (Carpool lane): access points have white dotted striping instead of solid lines."}]},{"id":"alcohol","name":"Alcohol & Drugs","icon":"🚫","src":"Handbook: Alcohol & Drugs","qs":[{"id":"alc-nqw32m","q":"Utah's legal limit for adult drivers is over what BAC?","a":"0.05","o":["0.05","0.08","0.10","0.04"],"why":"Section 10C: if you are over 0.05 BAC (0.04 for CDL), you violate the law."},{"id":"alc-msochy","q":"For a driver under 21, how much alcohol is allowed?","a":"None measurable","o":["None measurable","Less than 0.02","Under 0.05 BAC","One drink with a meal"],"why":"Utah's Not-a-Drop law bans any measurable alcohol under 21."},{"id":"alc-1jir98b","q":"Not-a-Drop first offense for a driver under 21 means all driving privileges are denied for:","a":"6 months","o":["6 months","9 months","3 months","18 months"],"why":"The first offense is a six month denial."},{"id":"alc-1oxy9ts","q":"An under-21 driver arrested for a first DUI is restricted to an ignition interlock for:","a":"3 years","o":["3 years","1 year","2 years","6 months"],"why":"Section 10F: three years if under 21 when arrested, 18 months for adults."},{"id":"alc-1n7xu1t","q":"A first DUI at age 21 or older brings a license suspension of:","a":"120 days","o":["120 days","30 days","1 year","18 months"],"why":"First DUI is 120 days. Later DUIs are 2 years."},{"id":"alc-1g8sz3c","q":"Refusing a chemical test brings a revocation of how long for a first offense (adult)?","a":"18 months","o":["18 months","12 months","24 months","36 months"],"why":"Under implied consent, refusal costs 18 months, and 36 months after that."},{"id":"alc-16lx9wb","q":"Alcohol starts affecting your driving:","a":"With the first drink","o":["With the first drink","After three drinks","Only above 0.08","Only on an empty stomach"],"why":"Impairment begins with the first drink."},{"id":"alc-yppmfh","q":"Extreme DUI means a BAC of at least:","a":"0.16","o":["0.16","0.12","0.10","0.20"],"why":"Utah defines extreme DUI as 0.16 or higher."},{"id":"alc-1s99u87","q":"Can you be convicted of impaired driving with a BAC under the limit?","a":"Yes, if alcohol or drugs impair your driving","o":["Yes, if alcohol or drugs impair your driving","No, a test result under the limit ends the case","Only if you are driving after dark","Only if you are under 21 years old"],"why":"Impaired driving below the limit still breaks the law."},{"id":"alc-qwudv0","q":"An ignition interlock device:","a":"Requires a breath sample to start and run the car","o":["Requires a breath sample to start and run the car","Locks the doors automatically if there is a crash","Limits the car's top speed to 55 mph","Records every trip you take for the court"],"why":"The device checks your breath before the engine starts."},{"id":"alc-194vor6","q":"A prescription drug that causes drowsiness:","a":"May make driving unsafe, so ask your doctor","o":["May make driving unsafe, so ask your doctor","Is safe to drive on if it is prescribed to you","Is only a problem if you also drink","Is only a problem on long road trips"],"why":"Medication can cause drowsiness. Doctors may advise against driving."},{"id":"alc-y23y6f","q":"A person under 21 convicted of alcohol possession or consumption loses the license for:","a":"1 year for a first conviction","o":["1 year for a first conviction","90 days for a first conviction","6 months for a first conviction","2 years for a first conviction"],"why":"The suspension is 1 year first and 2 years after."},{"id":"alc-15wvvay","q":"Boating under the influence carries:","a":"The same penalties as driving under the influence","o":["The same penalties as driving under the influence","Lesser penalties than driving under the influence","No penalties because it is not a road","Only a warning for a first offense"],"why":"Utah treats boating DUI like driving DUI."},{"id":"alc-k8pszp","q":"Mixing alcohol and drugs is:","a":"Dangerous, never combine them","o":["Dangerous, never combine them","Safe in small amounts","Fine if the drugs are prescribed","Safe if you eat first"],"why":"Combining them multiplies the effect."},{"id":"alc-191ykte","q":"Vision is affected at what BAC for all drivers?","a":"0.02","o":["0.02","0.05","0.08","0.16"],"why":"The handbook says vision is affected at 0.02, well below the legal limit."},{"id":"alc-1rmkbmq","q":"Alcohol and impairing drugs are involved in about what share of yearly fatal crashes?","a":"About 40 percent","o":["About 40 percent","About 5 percent","About 90 percent","About 1 percent"],"why":"Alcohol and drugs are involved in about 40 percent of deadly crashes."},{"id":"alc-1m2db6t","q":"What is the BAC limit for commercial driver license holders?","a":"0.04","o":["0.04","0.05","0.08","0.10"],"why":"Drivers with CDLs face a 0.04 limit."},{"id":"alc-bm5s2e","q":"A second Not-a-Drop offense within 10 years brings what loss of driving?","a":"Two years, or until age 21, whichever is longer","o":["Two years, or until age 21, whichever is longer","Six months again, the same as the first offense","One year, whether or not you have turned 21","Ninety days with a defensive driving course"],"why":"A second offense is a longer loss than the first."},{"id":"alc-31zfo4","q":"A teen age 15 is convicted of drinking alcohol for the second time. How long is the license suspended?","a":"Two years","o":["Two years","One year","Six months","Ninety days"],"why":"A second or later conviction is a 2 year suspension."},{"id":"alc-1d5vp1o","q":"What does a driver under 21 need to get driving privileges back after a Not-a-Drop offense?","a":"A substance abuse program assessment or a class","o":["A substance abuse program assessment or a class","A signed letter from a parent asking for it back","A new road test and a $50 fee at a DLD office","Nothing, you can just wait until the time runs out"],"why":"Reinstatement needs a program assessment or proof of a Prime For Life class."},{"id":"alc-ovm2d2","q":"Utah law lets the division begin a DUI suspension during which days after the arrest?","a":"The 45th to 60th day","o":["The 45th to 60th day","The day of the arrest","The 5th to 10th day","The 120th day"],"why":"Section 10C: the division may suspend the license beginning on the 45th-60th day after arrest."},{"id":"alc-l59z6u","q":"A first DUI at age 21 or older usually brings an ignition interlock for:","a":"18 months","o":["18 months","12 months","24 months","30 months"],"why":"An adult first DUI is 18 months. Under 21 it is 3 years."},{"id":"alc-qp4bt3","q":"A second DUI brings an ignition interlock for:","a":"2 years","o":["2 years","6 months","18 months","10 years"],"why":"A second or later DUI brings a 2 year interlock."},{"id":"alc-m1i316","q":"An ignition interlock device must be serviced at least how often?","a":"Every 60 days","o":["Every 60 days","Every 6 months","Every year","Every week"],"why":"It must be serviced every 60 days."},{"id":"alc-d24m3u","q":"A driver blows into an interlock and it shows alcohol at 0.02 or higher. What happens?","a":"The requirement is extended 60 days","o":["The requirement is extended 60 days","Nothing happens and the car starts anyway","The device resets for free","The driver gets one free restart each month"],"why":"Handbook Section 10F: a start attempt with alcohol of 0.02 or higher extends the ignition interlock requirement by 60 days each time."},{"id":"alc-18mfwzf","q":"A person on alcohol-restricted status drives with any measurable alcohol. What is the penalty?","a":"A 1 year revocation","o":["A 1 year revocation","A written warning and a small fine","A 30 day suspension of your license","A free alcohol class and no other penalty"],"why":"Any measurable alcohol while restricted brings a revocation of one year."},{"id":"alc-1wcqty6","q":"Under implied consent, what do you agree to by driving in Utah?","a":"A chemical test if you are arrested for DUI","o":["A chemical test if you are arrested for DUI","A search of your car whenever an officer asks","A vision test every year you drive","A $500 fee each time you are stopped"],"why":"Handbook Section 10C: implied consent means that by driving in Utah you agree to take a chemical test of your breath, blood, urine, or oral fluids when an officer asks. Refusing the test means an 18 month license revocation for a first offense."},{"id":"alc-1enb5u6","q":"A driver under 21 refuses a chemical test for the first time. How long is the revocation?","a":"2 years","o":["2 years","18 months","6 months","1 year"],"why":"Refusal by a driver under 21 is 2 years the first time."},{"id":"alc-jsa8gr","q":"A Utah law passed in 2026 says a court may require an interdicted person (someone who cannot buy alcohol) to:","a":"Surrender their Utah driver license or ID card","o":["Surrender their Utah driver license or ID card","Retake the written and road tests every year","Pay a $500 fine each time they renew a license","Drive only with an ignition interlock device"],"why":"New 2026 Laws (HB 59, effective May 6, 2026) and Section 10H: a court may require an interdicted person (someone who cannot buy alcohol) to surrender their license."},{"id":"alc-1y49o8q","q":"A plea held in abeyance for a DUI:","a":"Still counts as a prior offense","o":["Still counts as a prior offense","Is wiped after one year","Does not count as a prior offense later","Counts as a prior after a five year wait"],"why":"Handbook Section 10C: a plea held in abeyance (put on hold by the court) may not show on your record. It still counts as a prior offense."},{"id":"alc-1hby1if","q":"DUI law covers a person who is driving or who is:","a":"In actual physical control of the vehicle","o":["In actual physical control of the vehicle","Walking beside the vehicle after parking it","Riding as a passenger in the back seat","Standing near the vehicle with the engine off"],"why":"Sections 10C and 13E: the law covers driving or being in actual physical control of a vehicle."},{"id":"alc-10z1gy1","q":"A first DUI in Utah is usually a:","a":"Class B misdemeanor","o":["Class B misdemeanor","Class A misdemeanor","Class C misdemeanor","Third degree felony"],"why":"A first DUI is a Class B misdemeanor in most cases."},{"id":"alc-13xpxzg","q":"Can you be charged with DUI for driving after taking a legal prescription drug?","a":"Yes, if it impairs your driving","o":["Yes, if it impairs your driving","No, because the drug is legal to use","No, if you have a prescription for it","Yes, but you must have a drink"],"why":"Handbook Section 10A: prescribed and over the counter drugs can impair driving. Section 10C: driving while unsafely impaired is a violation."},{"id":"alc-6upzd6","q":"Driving without a required ignition interlock may lead to:","a":"Impoundment and revocation","o":["Impoundment and revocation","A thank you note and a free tow home","A written warning that you can ignore","Nothing, if you drive only a short way"],"why":"It can bring impoundment of the vehicle and a revocation."},{"id":"alc-b5xgh0","q":"Alcohol and other impairing drugs reduce your:","a":"Judgment, vision, and reaction time","o":["Judgment, vision, and reaction time","Only your hearing, nothing else","Only your sense of smell, nothing else","Nothing at all if you feel fine"],"why":"Section 10A: they reduce judgment, vision, color distinction, and reaction time."},{"id":"alc-keh1z8","q":"What is the most important sense you use in driving?","a":"Vision","o":["Vision","Hearing","Smell","Touch"],"why":"Section 10A: the most important sense you use in driving is vision."},{"id":"alc-1lz5cr","q":"Alcohol affects your vision by:","a":"Weakening your sense of distance and speed","o":["Weakening your sense of distance and speed","Making colors look brighter and more vivid","Sharpening your focus on distant objects","Widening your view of the road to the sides"],"why":"Section 10A: it blurs vision, slows focus, and reduces the ability to judge distance and speed."},{"id":"alc-1r1sb1l","q":"Which kinds of drugs can affect your driving?","a":"Illegal, over the counter, and prescribed","o":["Illegal, over the counter, and prescribed","Illegal drugs sold on the street, but no others","Prescribed drugs from a doctor, but no others","Drugs that are injected, but no others"],"why":"Section 10A (Impairing drugs): illegal, over the counter, and prescribed drugs can all affect driving."},{"id":"alc-swyuu5","q":"Alcohol should not be mixed with drugs because it:","a":"It can have an unpredictable effect","o":["It can have an unpredictable effect","It always cancels out the drug fully","It makes the drug stronger every single time","It only matters when you drive at night"],"why":"Section 10A: alcohol can have an unpredictable effect on drugs."},{"id":"alc-xvp3xb","q":"A friend has been drinking and wants to drive. You should:","a":"Not let them drive","o":["Not let them drive","Let them drive if they feel fine","Let them drive on side streets","Let them drive if you ride along"],"why":"Section 10A: never let a friend or relative drive if they have been drinking."},{"id":"alc-zq3nzk","q":"What is the handbook's best advice about alcohol and driving?","a":"Do not drive after alcohol or drugs","o":["Do not drive after alcohol or drugs","Wait one hour after drinking, then drive","Eat a full meal first and then drive","Drink only beer and drive slowly"],"why":"Section 10A: the best advice is not to drive after consuming alcohol or other drugs."},{"id":"alc-qqhqzd","q":"Which statement about being under 21 is true?","a":"Buying, owning, or drinking it is illegal","o":["Buying, owning, or drinking it is illegal","You may drink with a meal at a restaurant","You may drink at home with no penalty","You may drink if a friend gives it to you"],"why":"Section 10B: under 21 it is illegal to purchase, possess, and drink alcoholic beverages."},{"id":"alc-esilud","q":"What does a zero tolerance law mean for drivers under 21?","a":"No alcohol in the body","o":["No alcohol in the body","A limit of 0.05, the same as adults","A limit of 0.08 before you can be cited","One small drink is allowed with food"],"why":"Section 10B: zero tolerance laws mean no alcohol in the circulatory system."},{"id":"alc-1bue3t0","q":"Can a person who has not yet been issued a license lose driving rights under Not-a-Drop?","a":"Yes, they can still be denied or suspended","o":["Yes, they can still be denied or suspended","No, a person without a license cannot be denied","No, the law covers just licensed drivers over 18","Yes, but they must wait until they turn 21"],"why":"Section 10B: a person who has yet to be issued a license will still be denied or suspended."},{"id":"alc-1lvt5lw","q":"What can a driver under 21 use as proof for reinstatement after a Not-a-Drop arrest?","a":"Proof of a Prime For Life DUI class","o":["Proof of a Prime For Life DUI class","A signed note from a parent or guardian","A paid receipt for the fine","A signed log of practice driving hours"],"why":"Section 10B: the division accepts evidence of a Prime For Life DUI class instead of an assessment."},{"id":"alc-1o8o0wv","q":"A second or later DUI for a driver 21 or older brings a suspension of:","a":"Two years","o":["Two years","120 days","30 days","Six months"],"why":"Section 10C: 120 days for a first DUI and two years for a second or later."},{"id":"alc-1tf2t43","q":"You refuse a chemical test a second time. How long is the adult revocation?","a":"36 months","o":["36 months","18 months","One year","Two years"],"why":"Section 10C (Implied consent): 18 months for a first refusal and 36 months for later ones."},{"id":"alc-vwuz5","q":"The implied consent law covers which kinds of tests?","a":"Breath, blood, urine, or oral fluids","o":["Breath, blood, urine, or oral fluids","Just a breath test taken at the roadside","Just a blood test taken at a hospital","A balance and walking test at the roadside"],"why":"Section 10C (Implied consent): a chemical test of breath, blood, urine, or oral fluids."},{"id":"alc-bjqy61","q":"A driver is under 0.05 BAC but clearly impaired. Is driving a violation?","a":"Yes, if you are unsafe to drive","o":["Yes, if you are unsafe to drive","No, only the BAC number matters","No, as long as the drug was legal","No, as long as you drive slowly"],"why":"Section 10C: driving is a violation if you are impaired enough to be unsafe even under the limit."},{"id":"alc-6h5ybx","q":"Alcohol-restricted status can last:","a":"2, 3, 5, or 10 years","o":["2, 3, 5, or 10 years","30 days for every offense","6 months for every offense","Exactly 1 year for every offense"],"why":"Section 10D: restricted status lasts 2, 3, 5, or 10 years, or life in some cases."},{"id":"alc-4zf3kt","q":"A lifetime alcohol-restricted status results from:","a":"Automobile homicide or a felony DUI","o":["Automobile homicide or a felony DUI","A first DUI conviction at age 21 or older","A first Not-a-Drop offense at age 20","A first refusal of a chemical test as an adult"],"why":"Section 10D: lifetime status follows a conviction for automobile homicide or felony DUI."},{"id":"alc-18othpc","q":"A felony DUI carries an ignition interlock restriction of:","a":"Three years","o":["Three years","Eighteen months","Two years","Ten years"],"why":"Section 10F: felony DUI is a three-year interlock restriction."},{"id":"alc-18q0asv","q":"Automobile homicide carries an ignition interlock restriction of:","a":"10 years","o":["10 years","3 years","2 years","18 months"],"why":"Section 10F: automobile homicide carries a 10-year interlock restriction."},{"id":"alc-6blrbn","q":"What happens if you are convicted of violating the interlock restricted driver law?","a":"A one year revocation and 2 more years of interlock","o":["A one year revocation and 2 more years of interlock","A one year suspension and 5 more years of interlock","A written warning, then a class about interlocks","A 30 day suspension and a $50 monitoring fee"],"why":"Section 10F: a conviction brings a one-year revocation and another two-year interlock restriction."},{"id":"alc-x9zlm0","q":"A driver without a required interlock device is stopped. What may happen to the vehicle?","a":"It may be impounded","o":["It may be impounded","It is given a free tow home","It is repaired for free","Nothing happens to it"],"why":"Section 10F: the vehicle may be impounded and the driver cited."},{"id":"alc-1n4q83k","q":"What fees must the owner pay to get an impounded DUI vehicle back?","a":"Towing, storage, and administrative costs","o":["Towing, storage, and administrative costs","A parking ticket and a fee for the officer","The cost of the breath test and the blood draw","None, because the state pays for everything"],"why":"Section 10G: fees include towing, storage charges, and administrative costs."},{"id":"alc-6u27yy","q":"An impounded vehicle is not claimed within the allowed time. What happens?","a":"It shall be sold","o":["It shall be sold","It is given to the driver for free","It is held forever","It is scrapped with no sale"],"why":"Section 10G: if an impounded vehicle is not claimed in time, it shall be sold."},{"id":"alc-13j1fbv","q":"How long must a voluntarily interdicted license be kept before you may apply for a regular one?","a":"At least 30 days","o":["At least 30 days","At least 1 year","At least 5 years","No time, you may switch at once"],"why":"Section 10H (Voluntary participation): it must be kept at least 30 days before reapplying for a non-interdicted license."},{"id":"alc-11v48h3","q":"An interdicted driver license or ID card shows that the person:","a":"Cannot buy alcohol at bars or liquor stores","o":["Cannot buy alcohol at bars or liquor stores","Cannot drive a car after dark or on freeways","Cannot own or register a car in their name","Cannot ride in a car as a passenger at night"],"why":"Section 10H: it identifies a person who cannot purchase alcohol in Utah restaurants, bars, or state liquor stores."},{"id":"alc-2y8c1t","q":"Driving after taking a drug can lead to DUI charges if the drug:","a":"Impairs you, even if it is prescribed","o":["Impairs you, even if it is prescribed","Is illegal to own in any amount at all","Is taken as a pill and not as a liquid","Was taken more than a day before you drove"],"why":"Section 10A: illegal, over the counter, and prescribed drugs can impair driving."},{"id":"alc-14bwdfz","q":"Strong emotions such as anger can affect driving by:","a":"Interfering with thinking and attention","o":["Interfering with thinking and attention","Improving your focus on the road","Speeding up your reflexes behind the wheel","Making you a safer driver overall"],"why":"Section 10A (Emotions): emotions can interfere with thinking and attention."}]},{"id":"conditions","name":"Distractions & Weather","icon":"⛈️","src":"Handbook: Distractions & Driving Challenges","qs":[{"id":"con-1nxsy99","q":"Drivers under 18 may use a handheld phone only for:","a":"Emergencies, hazards, crime, or calling a parent","o":["Emergencies, hazards, crime, or calling a parent","Navigation, music, and quick text replies to friends","Calls to friends while you are stopped at lights","Any hands-free call to a classmate or a friend"],"why":"Under 18, only emergency, hazard, criminal activity, or parent or guardian calls."},{"id":"con-1lyhhia","q":"Drivers 18 and older may use a phone only by:","a":"Voice commands","o":["Voice commands","Typing at red lights","Holding it low","Texting short replies"],"why":"No manual texting, dialing, or browsing while driving."},{"id":"con-18rzhpp","q":"A first texting violation in Utah, with no injury, is what level of offense?","a":"A Class C misdemeanor","o":["A Class C misdemeanor","An infraction","A Class A misdemeanor","A third degree felony"],"why":"Handbook Section 11F: a texting violation is a Class C misdemeanor, or a Class B misdemeanor if it causes bodily injury or the driver has a previous texting violation."},{"id":"con-14403ph","q":"If something distracts you, such as pets or children, you should:","a":"Pull over to deal with it","o":["Pull over to deal with it","Reach back while you drive","Slow down to ten mph and fix it","Ignore it until the trip ends"],"why":"Pull over to handle any distraction."},{"id":"con-135jidy","q":"Fatigue tips from the handbook include stopping about how often on long trips?","a":"Every 2 hours","o":["Every 2 hours","Every 6 hours","Every 30 minutes","Once per trip"],"why":"Stop every two hours and avoid late-night driving."},{"id":"con-nwnz2j","q":"How much moving water can carry away most vehicles, including SUVs and pickups?","a":"2 feet","o":["2 feet","6 inches","1 foot","4 feet"],"why":"Six inches can stall a car, and 2 feet of moving water can sweep one away."},{"id":"con-12opvb8","q":"How long can a car float after it enters deep water?","a":"30 to 60 seconds","o":["30 to 60 seconds","About 5 minutes","Up to 10 minutes","About 15 seconds"],"why":"Handbook Section 11N: a car floats on the surface for only 30 to 60 seconds, so get out right away."},{"id":"con-sv4f5n","q":"When your rear wheels skid, you should:","a":"Ease off the gas and steer into the skid","o":["Ease off the gas and steer into the skid","Slam on the brakes and hold the wheel","Steer away from the direction of the skid","Accelerate to pull out of the skid"],"why":"Ease off, steer toward the skid direction, and straighten as traction returns."},{"id":"con-w2r8p5","q":"On a long mountain downgrade you should:","a":"Use a lower gear, never coast in neutral","o":["Use a lower gear, never coast in neutral","Coast in neutral to save wear on your brakes","Ride the brakes all the way down the grade","Shut off the engine to save fuel on the hill"],"why":"Gear down and never coast in neutral."},{"id":"con-1cegrw3","q":"On a narrow mountain road, who yields on a downhill?","a":"The downhill driver yields to uphill traffic","o":["The downhill driver yields to uphill traffic","The uphill driver yields to downhill traffic","The faster driver yields to the slower one","The smaller vehicle yields to the larger"],"why":"Downhill traffic yields to uphill traffic."},{"id":"con-14li15b","q":"A large animal runs onto the road ahead. You should:","a":"Brake without swerving","o":["Brake without swerving","Swerve hard to avoid it","Speed up to get past it","Honk and drive faster"],"why":"Do not swerve. Slow down and stay in your lane."},{"id":"con-obkix7","q":"During lightning you are safest:","a":"In a hard-topped vehicle with windows closed","o":["In a hard-topped vehicle with windows closed","Standing next to your car with the door open","Under a large tree beside the road or trail","Inside a convertible with the top folded down"],"why":"A closed, hard-topped car protects you."},{"id":"con-rt18lg","q":"Stranded in cold weather, how long should you run the engine?","a":"About 10 minutes each hour","o":["About 10 minutes each hour","All night to keep the car warm","30 seconds each hour only","Never, because of exhaust fumes"],"why":"Run it about 10 minutes an hour with a window slightly open and the exhaust clear."},{"id":"con-f6h8wu","q":"In hot weather, how often should you check your tires?","a":"Every 2 hours or 100 miles","o":["Every 2 hours or 100 miles","Once a week at the pump","Only when a tire looks low","Only before a long trip"],"why":"Do not release air from hot tires."},{"id":"con-14c67ws","q":"No workers are visible in a work zone. You should:","a":"Still slow down and obey the signs","o":["Still slow down and obey the signs","Speed up to clear the zone faster","Pass slow cars in the work zone","Ignore the signs until you see workers"],"why":"Slow down even without workers."},{"id":"con-b80leg","q":"Which of these is careless driving?","a":"A moving violation while searching for something in the car","o":["A moving violation while searching for something in the car","A parking violation while searching for something in the car","Driving at the speed limit on a clear, dry day with all lights on","Making a hands-free call by voice command on the freeway"],"why":"Careless driving includes a moving violation while distracted by something inside the vehicle."},{"id":"con-1e6risg","q":"A first road rage conviction can lead to:","a":"A one year license suspension","o":["A one year license suspension","A parking ticket and a short warning","A written warning and no other penalty","A $5 fine and a change of plates"],"why":"The court may order a one year suspension for a first road rage enhancement."},{"id":"con-obrh3j","q":"Which is illegal for a driver 18 or older?","a":"Typing a text message by hand","o":["Typing a text message by hand","Using voice commands for a call","Using hands-free navigation","Listening to the radio"],"why":"Manual writing, sending, or reading messages and browsing are banned."},{"id":"con-ttxsl8","q":"A texting while driving conviction is a Class B misdemeanor when:","a":"It causes bodily injury or is a repeat offense","o":["It causes bodily injury or is a repeat offense","It happens in the daytime on a city street","It happens in a parking lot with no other cars","It happens on a freeway in light traffic"],"why":"It is usually Class C. It is Class B when someone is hurt or it is a repeat."},{"id":"con-usg5cm","q":"When are animals most likely to be on the road?","a":"At dawn and dusk","o":["At dawn and dusk","At noon","At midnight only","Only in winter"],"why":"Be extra careful at dawn and dusk."},{"id":"con-1kx0j3s","q":"Driving through the hot desert, what should you carry?","a":"Water for you and the radiator","o":["Water for you and the radiator","Extra tires and a full set of tools","Heavy blankets for the hot days","A small tent with a pair of boots"],"why":"Carry water for yourself and for the radiator."},{"id":"con-s2rbfa","q":"You break down in the desert. What should you do?","a":"Stay with your vehicle","o":["Stay with your vehicle","Walk toward the nearest town","Take a side road to find help","Flag down a passing car for a ride"],"why":"Do not wander from a broken-down vehicle."},{"id":"con-19l45j7","q":"How much sleep should adults aim for each night?","a":"7 to 9 hours","o":["7 to 9 hours","5 to 6 hours","10 to 12 hours","3 to 4 hours"],"why":"Aim for 7 to 9 hours to avoid drowsy driving."},{"id":"con-w2ib1t","q":"If you feel tired while driving, a short nap of about how long can help?","a":"20 minutes","o":["20 minutes","45 minutes","90 minutes","10 minutes"],"why":"A 20 minute nap helps. Stop every 2 hours too."},{"id":"con-pxg7g9","q":"You cannot remember the last few miles you drove. This is a sign of:","a":"Drowsiness","o":["Drowsiness","Good focus","Hunger","Good weather"],"why":"Missing recent miles is a sign of fatigue."},{"id":"con-1haklb1","q":"How deep can water be before most cars may lose control or stall?","a":"About 6 inches","o":["About 6 inches","About 18 inches","About 3 feet","About 5 feet"],"why":"Six inches can cause loss of control or stalling. Two feet can sweep away most vehicles."},{"id":"con-7ht0mn","q":"You come to a flooded road. What should you do?","a":"Turn around and find another route","o":["Turn around and find another route","Drive through slowly in the center of the road","Speed through so the water splashes less","Follow a big truck through the water"],"why":"Turn around, do not cross flooded roads."},{"id":"con-f84lfw","q":"Your car is sinking and the window will not open. What should you do?","a":"Wait for the pressure to equalize, then kick out the window","o":["Wait for the pressure to equalize, then kick out the window","Keep pushing on the door with all your strength until it opens","Stay in your seat and wait for rescuers to find the car","Call 911 and keep honking the horn until help arrives"],"why":"Water pressure keeps the door shut. Once pressure equalizes, kick the window out."},{"id":"con-meef6r","q":"You have a long drive in hot weather. What should you watch?","a":"Tire pressure, coolant, and oil","o":["Tire pressure, coolant, and oil","Only the radio and the air conditioning","Only the paint and your tire brand","Only your fuel gauge and the clock"],"why":"Check tire pressure every 2 hours or 100 miles and watch coolant and oil."},{"id":"con-c6qyg6","q":"You are stranded in your car in the snow. What should you do?","a":"Stay with the car and run the engine about 10 minutes each hour","o":["Stay with the car and run the engine about 10 minutes each hour","Leave the car and walk toward the nearest road to find help before dark","Run the engine nonstop and keep all windows closed tight","Sleep with the doors locked and all windows closed tight"],"why":"Stay put, clear the exhaust pipe, keep one window open a little, and run the engine about 10 minutes an hour."},{"id":"con-qsdzur","q":"Why keep a window open a little and the exhaust clear when running the engine in the snow?","a":"To prevent carbon monoxide from building up","o":["To prevent carbon monoxide from building up","To keep the engine from overheating at idle","To save gas while you sit and wait for help","To warm the cabin faster with fresh air"],"why":"Exhaust fumes can enter the car if the pipe is blocked."},{"id":"con-3j8sg7","q":"Your car breaks down on the road. Who should you call?","a":"911","o":["911","A friend only","A tow truck only","No one"],"why":"Call 911 and place flares or triangles 200 to 300 feet behind your car."},{"id":"con-mtom99","q":"During lightning, you should avoid:","a":"Touching metal parts of the car","o":["Touching metal parts of the car","Closing the windows in the vehicle","Staying inside the hard-topped car","Wearing your safety belt in the seat"],"why":"Stay in a hard-topped car with doors closed and windows up. Avoid metal surfaces."},{"id":"con-1vo1sv0","q":"On a narrow mountain road with blind sharp curves, you should:","a":"Honk and stay right","o":["Honk and stay right","Honk and move to the center","Slow down and stay left","Speed up and take the curve wide"],"why":"Honk before blind sharp curves on narrow mountain roads and stay right."},{"id":"con-1h0hp75","q":"You drive on a gravel road. What should you do?","a":"Slow down and increase your following distance","o":["Slow down and increase your following distance","Speed up so the loose stones do not spray as much","Brake hard and often to test the traction","Stay close behind the car ahead for shelter"],"why":"Gravel is slippery, so slow down and give more space."},{"id":"con-ydfmo9","q":"Your engine suddenly loses power while driving. What should you do?","a":"Grip firmly, steer, brake gently, and pull off","o":["Grip firmly, steer, brake gently, and pull off","Take your hands off so the wheel can settle itself","Slam the brakes at once and stop in place","Turn off the key and coast without steering"],"why":"Keep control of the wheel, brake gently, and move off the road."},{"id":"con-1jj5rwp","q":"During a skid, you should NOT:","a":"Slam on the brakes","o":["Slam on the brakes","Ease off the gas","Steer toward the skid","Straighten when you regain traction"],"why":"Slamming the brakes can make a skid worse."},{"id":"con-1f53bfo","q":"Which of these counts as a distraction?","a":"Anything that takes your mind or body off driving","o":["Anything that takes your mind or body off driving","Only phone calls and text messages","Only talking passengers in the back seat","Only eating food while you are driving"],"why":"A distraction is anything that takes your mind or body off driving."},{"id":"con-1buj8jr","q":"You are very angry. What should you do before you drive?","a":"Cool off first","o":["Cool off first","Drive fast to calm down","Turn up the radio","Race to your destination"],"why":"Cool off before driving when you are angry or excited."},{"id":"con-x1iuek","q":"You feel impatient about being late. What helps?","a":"Leave earlier next time","o":["Leave earlier next time","Drive faster than other cars","Follow the car ahead closely","Change lanes more often"],"why":"The handbook says leave early when you are impatient."},{"id":"con-1oj7k8c","q":"Before a long trip, you should check:","a":"Tires, fluids, belts, hoses, brakes, and lights","o":["Tires, fluids, belts, hoses, brakes, and lights","The radio presets, cup holders, and floor mats","The paint, the plate frame, and the bumper stickers","The phone case, air freshener, and seat covers"],"why":"Check key parts before you go."},{"id":"con-cic8ap","q":"Which of these is a warning sign of drowsiness?","a":"Hitting a rumble strip or drifting","o":["Hitting a rumble strip or drifting","Feeling hungry for a snack after lunch","Feeling warm in the car on a sunny day","Hearing a favorite song"],"why":"Section 11D: warning signs include hitting a rumble strip or drifting from your lane."},{"id":"con-p401vn","q":"Which is a warning sign of drowsiness?","a":"Yawning again and again","o":["Yawning again and again","Tapping the wheel to a song","Singing along with the radio","Opening a window for fresh air"],"why":"Section 11D: warning signs include yawning repeatedly."},{"id":"con-1o0ba3w","q":"You tailgate or miss signs while driving. This can be a sign of:","a":"Drowsiness","o":["Drowsiness","Good focus","Good weather","A full tank"],"why":"Section 11D: tailgating or missing traffic signs is a warning sign of drowsiness."},{"id":"con-s397ig","q":"Before a long trip, what should you do about your medicine?","a":"Read labels, since some cause sleepiness","o":["Read labels, since some cause sleepiness","Take a double dose before you leave home","Take it while you drive to save some time","Skip the labels and take it as usual"],"why":"Section 11D (Taking a road trip): check the labels on your medicine; some will make you sleepy."},{"id":"con-1h5egtx","q":"Who should go with you on a long trip, if possible?","a":"Another person to watch your driving","o":["Another person to watch your driving","A pet resting in your lap","No one, since you drive alone better","A child riding in the front seat"],"why":"Section 11D: have another person go with you to watch your driving."},{"id":"con-ajjdko","q":"If you start to feel tired, you should:","a":"Stop at a rest area and take a nap","o":["Stop at a rest area and take a nap","Turn up the radio and keep going","Open the window and drive faster","Keep driving until you reach the next town"],"why":"Section 11D: stop driving, pull off at an exit or rest area, and take a 20-minute power nap."},{"id":"con-frx32f","q":"What should you avoid to prevent fatigue?","a":"Driving late at night","o":["Driving late at night","Driving after sleeping","Driving with a passenger","Driving with a rest stop"],"why":"Section 11D: do not drive late at night."},{"id":"con-1o4prmn","q":"Six inches of water can:","a":"Reach the bottom of most cars and stall them","o":["Reach the bottom of most cars and stall them","Carry away a large truck or an SUV right away","Rise above the doors of most passenger cars","Cool the engine and help it run better"],"why":"Section 11E: six inches of water reaches the bottom of most cars, causing loss of control or stalling."},{"id":"con-17hr8sv","q":"Floodwater looks shallow enough to cross. You should:","a":"Not attempt to cross it","o":["Not attempt to cross it","Cross slowly in low gear","Follow another driver","Cross at high speed"],"why":"Section 11E: if the water seems shallow, do not attempt to cross, since it can hide dips."},{"id":"con-4hkrxa","q":"You find a flooded road and no other route. You should:","a":"Go to higher ground and wait for it to drop","o":["Go to higher ground and wait for it to drop","Drive through slowly at night when it is cool","Park in the water and wait for help to come","Wait in the middle of the flooded roadway"],"why":"Section 11E: if there is no other route, proceed to higher ground and wait."},{"id":"con-a0999u","q":"Flash floods can happen:","a":"Within minutes or hours of heavy rain","o":["Within minutes or hours of heavy rain","Only in the spring each year","Only after a full week of steady rain","Never anywhere in the state of Utah"],"why":"Section 11E: flash floods can come rapidly, within minutes or hours of excessive rainfall."},{"id":"con-1o48250","q":"Your car enters water. You should first:","a":"Remove your safety belt","o":["Remove your safety belt","Open the trunk","Call 911 and stay in your seat","Wait for the car to fill with water"],"why":"Section 11N: it floats only 30 to 60 seconds, so first remove the safety belt."},{"id":"con-n9s2ym","q":"When trapped in a sinking car, what should you do with your clothes and shoes?","a":"Remove heavy clothing but keep shoes on","o":["Remove heavy clothing but keep shoes on","Remove your shoes but keep heavy clothing on","Keep all of your clothes and shoes on","Remove all of your clothing, shoes included"],"why":"Section 11N: take off heavy clothing, but keep your shoes on in case you must kick the window."},{"id":"con-3j4iyy","q":"A sinking car has no open window or door. Where is a small pocket of air?","a":"Near the highest part of the vehicle","o":["Near the highest part of the vehicle","Near the part of the vehicle that is lowest","Under the seats at the back of the car","Behind the tires of the vehicle"],"why":"Section 11N: a small air pocket is near the part of the vehicle that is highest in the water."},{"id":"con-1p7s271","q":"Which of these can you do with a hands-free call and voice commands if you are over 18?","a":"Use GPS functions","o":["Use GPS functions","Write texts by hand","Browse the internet by touch","Take photos"],"why":"Section 11F: hands-free and voice-activated use allows GPS functions and reporting hazards."},{"id":"con-kp73on","q":"Can police stop a driver they see texting?","a":"Yes, an officer may pull you over","o":["Yes, an officer may pull you over","No, not unless a crash happens","No, the ticket must come later by mail","Yes, but a second offense must happen first"],"why":"Section 11F: officers may pull a driver over if they observe texting."},{"id":"con-1n5tcso","q":"Which of these is banned for drivers over 18?","a":"Entering data into a phone by hand","o":["Entering data into a phone by hand","Talking on a call by voice command","Following voice-activated GPS directions","Reporting a safety hazard by voice"],"why":"Section 11F: manually writing, sending, reading, dialing, or entering data is prohibited."},{"id":"con-1982w1q","q":"How should you prepare before you start driving to avoid distraction?","a":"Set navigation and secure loose items","o":["Set navigation and secure loose items","Eat your meal while you drive to save time","Text a friend you are leaving","Let your pets move around loose in the car"],"why":"Section 11: set navigation, eat and groom before leaving, and secure loose items."},{"id":"con-ypf1it","q":"How should you carry a pet in your vehicle?","a":"In a pet carrier, not loose","o":["In a pet carrier, not loose","On your lap while you drive","On top of the dashboard","On the front seat beside you"],"why":"Section 11: keep pets in a pet carrier, not loose in a vehicle."},{"id":"con-6q79rm","q":"Which of these should you do to avoid distraction while driving?","a":"Not eat while driving","o":["Not eat while driving","Argue with passengers","Take a call by hand","Groom at red lights"],"why":"Section 11: do not eat, talk on the phone, or text, and do not argue with passengers."},{"id":"con-1qyyall","q":"A bee stings you or you lose a contact lens while driving. You should:","a":"Pull over and take care of it","o":["Pull over and take care of it","Reach for it while still driving","Close your eyes briefly","Speed up to get home and fix it"],"why":"Section 11: pull over immediately to the side of the roadway and take care of the problem."},{"id":"con-12zmwwo","q":"Utah law defines road rage as a criminal offense committed:","a":"With intent to endanger or intimidate","o":["With intent to endanger or intimidate","By accident while changing lanes on a road","Without any intent to hurt or frighten anyone","In a private parking lot"],"why":"Section 11A: the offense is committed in response to a roadway incident with intent to endanger or intimidate."},{"id":"con-gukyzi","q":"When are animals most active?","a":"At dawn and dusk","o":["At dawn and dusk","At noon","At 3 a.m. only","Only on weekends"],"why":"Section 11B: use caution at dawn and dusk when animals are most active."},{"id":"con-mntlk8","q":"What do animal crossing signs mark?","a":"Areas with many animal collisions","o":["Areas with many animal collisions","Parks with wildlife viewing","Farm roads that are closed to car traffic","Places where you may park and view animals"],"why":"Section 11B: signs are placed in areas with many animal/vehicle collisions."},{"id":"con-1rliqk3","q":"You see an animal standing near the road. You should:","a":"Slow down and use caution","o":["Slow down and use caution","Swerve at once to get away","Speed up to get past it quickly","Honk and speed up to scare it"],"why":"Section 11B: slow down near animals since they may bolt or change direction."},{"id":"con-tm8ypj","q":"Your vehicle needs help at the side of the road. What may you do?","a":"Pull off, turn on flashers, raise the hood","o":["Pull off, turn on flashers, raise the hood","Stand in the traffic lane and wave down cars","Keep driving until you find a garage open","Turn off your lights to save the battery"],"why":"Section 11B: pull to the side, turn on flashers, raise your hood, and tie something white or orange to the antenna."},{"id":"con-1mghhwm","q":"You drive in the desert in summer and are not used to the heat. You should:","a":"Skip it, or stay on freeways with A/C","o":["Skip it, or stay on freeways with A/C","Drive at night and carry no water","Take side roads to avoid the traffic","Leave your water at home to save weight"],"why":"Section 11C: do not drive through the desert in summer; if you must, stay on freeways with air conditioning."},{"id":"con-11xc58p","q":"When driving in the desert, side roads are:","a":"Best avoided unless you know the way","o":["Best avoided unless you know the way","A good shortcut that saves time and gas","Safe for every regular car","Paved and well maintained in most places"],"why":"Section 11C: do not take side roads off the freeway unless you know where they go."},{"id":"con-1asdifu","q":"Tire pressure rises in hot weather. You should:","a":"Not let air out","o":["Not let air out","Let air out right away","Add more air","Ignore your tires all day"],"why":"Section 11O (Hot weather): air pressure rises with temperature, so do not let the air out."},{"id":"con-1qn633","q":"How often should you inspect tires in very hot weather?","a":"Every two hours or 100 miles","o":["Every two hours or 100 miles","Every four hours or 300 miles","Once at the start of the trip","Every day before you leave home"],"why":"Section 11O (Hot weather): inspect the tires every two hours or every 100 miles."},{"id":"con-y1rsqn","q":"Your coolant gauge goes above the highest safe mark. You should:","a":"Stop as soon as it is safe to","o":["Stop as soon as it is safe to","Keep driving to the next big town","Turn off the heater and speed up","Pour cold water on a hot engine"],"why":"Section 11O (Hot weather): stop as soon as safely possible to find out what is wrong."},{"id":"con-1x3isqa","q":"How does engine oil help in hot weather?","a":"It helps keep the engine cool","o":["It helps keep the engine cool","It speeds up the engine","It keeps the tires from overheating","It cleans dust off the windshield"],"why":"Section 11O (Hot weather): engine oil helps keep the engine cool."},{"id":"con-1ipo1kw","q":"You are stranded in cold weather. What should you hang from your vehicle?","a":"A brightly colored cloth","o":["A brightly colored cloth","A wet towel from the trunk","Your seat belt buckle","Nothing, since it draws attention"],"why":"Section 11O (Cold weather): hang a brightly colored cloth from the window, mirror, or door handle."},{"id":"con-1byjdl6","q":"Stranded in the cold, who should stay awake?","a":"At least one person","o":["At least one person","No one, since everyone should sleep","Only the driver of the vehicle","Only the children in the vehicle"],"why":"Section 11O (Cold weather): at least one person should remain awake at all times."},{"id":"con-16wqmwk","q":"Why should you not leave your stranded vehicle unless you know where help is?","a":"Many who leave get lost and get too cold","o":["Many who leave get lost and get too cold","A car is warmer than any nearby building","Help usually arrives within a few minutes","Walking in the cold burns too much fuel"],"why":"Section 11O (Cold weather): most deaths occur when people leave their vehicles and become lost."},{"id":"con-3c7r23","q":"Why should you keep the exhaust pipe clear of snow?","a":"Fumes can leak into the vehicle","o":["Fumes can leak into the vehicle","It saves fuel while you wait","It keeps the tires from freezing","It makes the engine run louder"],"why":"Section 11O (Cold weather): exhaust fumes can leak into the vehicle and cause you to black out."},{"id":"con-koi9z4","q":"In freezing weather your brakes may:","a":"Be weak, then suddenly grab","o":["Be weak, then suddenly grab","Get stronger as it gets colder","Never need any checking","Work the same as always"],"why":"Section 11O (Cold weather): brakes may be ineffective for several hundred feet and then suddenly grab."},{"id":"con-eidfkd","q":"To help prevent brake problems in freezing weather, you should:","a":"Lightly touch them now and then","o":["Lightly touch them now and then","Pump them hard and fast","Leave them alone until they thaw out","Press the parking brake to keep it dry"],"why":"Section 11O (Cold weather): lightly touch your brakes occasionally."},{"id":"con-jtvbjw","q":"If your rear wheels skid to the left, you should turn your front wheels:","a":"To the left","o":["To the left","To the right","Straight and brake hard","To the right and speed up"],"why":"Section 11L: if your rear wheels skid to the left, turn your front wheels to the left."},{"id":"con-ab7p8d","q":"Hydroplaning happens when:","a":"Your front tires ride on water","o":["Your front tires ride on water","Your tires get too cold","Your rear tires lose air on a wet road","Your wipers cannot clear the windshield"],"why":"Section 11L: hydroplaning occurs when the front tires ride on water."},{"id":"con-1f6lnks","q":"As you go faster while hydroplaning, you will:","a":"Lose steering control","o":["Lose steering control","Gain more traction on the road","Stop in a shorter distance","Turn more easily at the curve"],"why":"Section 11L: as you go faster, the problem worsens and you lose steering control."},{"id":"con-7gk1kc","q":"What is the best policy about skids?","a":"Prevent them by slowing down","o":["Prevent them by slowing down","Drive faster so you push through","Brake hard at all times","Ignore them until they happen"],"why":"Section 11L: slow down to a speed at which you can control the car."},{"id":"con-13huc1y","q":"Which of these is a lightning rule?","a":"Avoid radios on an outside antenna","o":["Avoid radios on an outside antenna","Stand under a tall tree for cover","Touch metal parts to ground yourself","Leave the windows down for air"],"why":"Section 11H: do not use radios connected to an external antenna mounted on the vehicle."},{"id":"con-10ob9uu","q":"Where is the safest place during a thunderstorm?","a":"Inside a well-built building","o":["Inside a well-built building","Under a lone tree in a field","In the open on flat ground","On top of a hill for a view"],"why":"Section 11H: the safest place is inside a well-constructed building with plumbing and wiring."}]},{"id":"crash","name":"Crashes & Insurance","icon":"💥","src":"Handbook: Crashes & Insurance","qs":[{"id":"cra-1comep7","q":"After a crash you should first:","a":"Stop immediately","o":["Stop immediately","Drive home and call","Wait to see if anyone calls you","Move a mile down the road"],"why":"Leaving the scene is a crime."},{"id":"cra-1jpw77u","q":"You must notify police after a crash with injury, death, or at least how much property damage?","a":"$2,500","o":["$2,500","$500","$1,000","$10,000"],"why":"Call 911 for injury, death, or $2,500 or more in damage."},{"id":"cra-2pif94","q":"Failing to stop at a crash with injuries is:","a":"A third-degree felony","o":["A third-degree felony","A traffic infraction with a fine","A warning for first offenders","A misdemeanor with community service"],"why":"It is a felony."},{"id":"cra-5dpfbi","q":"After a crash you must exchange:","a":"Name, address, registration, and insurance","o":["Name, address, registration, and insurance","Phone numbers and employer details","Driver license and Social Security numbers","Only your name and license plate number"],"why":"Share name, address, vehicle registration number, and insurance details."},{"id":"cra-1a4uvbg","q":"You hit an unattended parked car and cannot find the owner. You should:","a":"Leave a note with your name and address","o":["Leave a note with your name and address","Wait an hour, then drive away without a note","Leave a note with only your phone number","Leave your insurance card under the wiper"],"why":"Leave a note with your name and address."},{"id":"cra-pax2fv","q":"After a property-damage-only crash, you may:","a":"Move your car out of the travel lanes","o":["Move your car out of the travel lanes","Leave both cars exactly where they stopped","Swap seats so the owner drives your car","Remove your plates and take them with you"],"why":"Move to a safe place if possible."},{"id":"cra-1z54yk","q":"Where should you place breakdown flares or triangles?","a":"200 to 300 feet behind the vehicle","o":["200 to 300 feet behind the vehicle","About 20 feet behind the vehicle","About 50 feet in front of the vehicle","Right beside the driver's door"],"why":"Flares and triangles go 200 to 300 feet back."},{"id":"cra-5ygth0","q":"Your brakes fail. What do you try first?","a":"Apply the parking brake slowly","o":["Apply the parking brake slowly","Turn off the engine right away","Shift into reverse immediately","Steer toward oncoming traffic"],"why":"If that fails, shut off the engine and stop well off the road."},{"id":"cra-gtt4w4","q":"Your accelerator sticks. You should:","a":"Shift to neutral, steer, and brake gently","o":["Shift to neutral, steer, and brake gently","Brake as hard as you can until you stop","Shift to park and let the car coast to a stop","Pump the accelerator to try to free the pedal"],"why":"Shift to neutral and pull off."},{"id":"cra-1euyo2i","q":"A front tire blows out while you drive. What should you do?","a":"Hold the wheel firmly and slow down gradually","o":["Hold the wheel firmly and slow down gradually","Slam the brakes and steer away from the tire","Accelerate hard to keep the car going straight","Take your hands off the wheel and coast to a stop"],"why":"Hold the wheel steady and slow gradually."},{"id":"cra-a0gyjb","q":"With ABS brakes on a slippery road, you should:","a":"Press firmly and hold the pedal","o":["Press firmly and hold the pedal","Pump the pedal quickly several times","Tap the brakes in short, steady bursts","Use the parking brake to slow down first"],"why":"A pulsing pedal is normal. Keep pressure on."},{"id":"cra-1m3bw4h","q":"Which coverage does Utah law require?","a":"Liability and personal injury protection","o":["Liability and personal injury protection","Collision and comprehensive coverage together","Roadside assistance and towing coverage","Rental reimbursement and gap coverage"],"why":"Liability and PIP are mandatory. Collision and comprehensive are optional."},{"id":"cra-dyohb2","q":"Proof of insurance must be:","a":"In the vehicle and shown on request","o":["In the vehicle and shown on request","Kept at home and mailed in yearly","Shown only when you renew the plates","Carried only if the car is financed"],"why":"Electronic proof is allowed."},{"id":"cra-15xwzv3","q":"If a wheel drops off the pavement edge, you should:","a":"Slow down gradually and return to the road","o":["Slow down gradually and return to the road","Yank the wheel hard to jump back on the road","Brake hard before you steer back on the road","Speed up to climb back onto the pavement"],"why":"Do not panic. Slow gradually and steer back on."},{"id":"cra-3qdpij","q":"Leaving the scene of a crash can bring a fine of up to:","a":"$2,500","o":["$2,500","$100","$500","$10,000"],"why":"The handbook lists a jail sentence up to 1 year and a fine up to $2,500, plus a license suspension or revocation."},{"id":"cra-5his61","q":"Someone seems badly hurt after a crash. Should you move them?","a":"Not unless it prevents more injury","o":["Not unless it prevents more injury","Yes, right away to the shoulder","Yes, into your car to keep them warm","Yes, so the road stays open for traffic"],"why":"Do not move a seriously hurt person unless needed to prevent further injury."},{"id":"cra-gp9os7","q":"After a crash, what help must you give to hurt people?","a":"Reasonable help, like arranging a ride to a hospital","o":["Reasonable help, like arranging a ride to a hospital","None, you must wait inside your own car for police","Only a call to a friend who can come and help","Help only if the injured person is a family member or friend"],"why":"You must give reasonable help, including arranging transport if treatment is apparent or requested."},{"id":"cra-n50voe","q":"You gave your information to a police officer at the scene. Do you also need to give it to the other drivers?","a":"No, giving it to the officer meets the requirement","o":["No, giving it to the officer meets the requirement","Yes, you must also give it to every driver in the crash","Yes, in writing within a week of the crash","Yes, but only by phone later that same day"],"why":"Giving the information to the officer at the scene covers you."},{"id":"cra-1l5jhyo","q":"A crash causes $1,500 in damage and no one is hurt. What must you do?","a":"Exchange your information","o":["Exchange your information","Call 911 only and then leave","Leave quickly since it is small","Do nothing since no one is hurt"],"why":"911 is required for injury, death, or $2,500 or more in damage. You must always exchange information."},{"id":"cra-1geiy1c","q":"Knowingly driving without required insurance is a:","a":"Class B misdemeanor","o":["Class B misdemeanor","Class A misdemeanor","Class C misdemeanor","Third degree felony"],"why":"It is a class B misdemeanor and can cost you your license, registration, and plates."},{"id":"cra-17u4q61","q":"After a crash, a judgment for damages is not paid. How long before your driving privileges may be suspended?","a":"60 days","o":["60 days","7 days","1 year","10 days"],"why":"If a court judgment is unpaid for 60 days, driving privileges are suspended."},{"id":"cra-jrsae9","q":"How long must SR22 'future proof' insurance be kept after a suspension or revocation?","a":"3 years","o":["3 years","1 year","6 months","10 years"],"why":"SR22 must be kept for 3 years."},{"id":"cra-1yqv2wd","q":"Your vehicle is found to be uninsured. How long do you have to buy insurance before registration is revoked?","a":"30 days","o":["30 days","6 months","90 days","1 year"],"why":"Registration is revoked unless insurance is bought within 30 days."},{"id":"cra-19bkmsp","q":"Which coverage pays for damage to your own car in a crash, but is not required by Utah law?","a":"Collision","o":["Collision","Liability","Personal injury protection","Uninsured motorist"],"why":"Collision covers your car and is not required by law, though lenders often require it."},{"id":"cra-h2cf9d","q":"Which coverage pays for fire, theft, vandalism, or glass damage?","a":"Comprehensive","o":["Comprehensive","Collision","Liability","Personal injury protection"],"why":"Comprehensive covers non-collision damage."},{"id":"cra-qn98q0","q":"Uninsured motorist coverage protects you when:","a":"An uninsured or hit-and-run driver hurts you","o":["An uninsured or hit-and-run driver hurts you","You hit a tree on a snowy mountain road","You get a speeding ticket in a school zone","Your tire goes flat on a busy highway at night"],"why":"It covers you and your passengers if an uninsured or hit-and-run driver causes the crash."},{"id":"cra-36mb5d","q":"Personal injury protection (no-fault) pays benefits:","a":"No matter who caused the crash","o":["No matter who caused the crash","After a court decides who was at fault","Once the other driver's insurer agrees","Mainly for repairs to your own vehicle"],"why":"PIP pays basic benefits for injury without deciding fault."},{"id":"cra-2pcj6e","q":"Who may require you to carry collision and comprehensive insurance?","a":"A lender or lienholder","o":["A lender or lienholder","The Driver License Division","The county motor vehicle office","The Utah Highway Patrol"],"why":"The law does not require them, but a lienholder can."},{"id":"cra-1w6ijdz","q":"You are convicted of driving without insurance or proof. What can you expect?","a":"An SR22 for 3 years","o":["An SR22 for 3 years","A free pass","A warning letter","A check in the mail"],"why":"Conviction brings an SR22 requirement for 3 years and a reinstatement fee."},{"id":"cra-14bvi1f","q":"A brake warning light comes on. What should you do?","a":"Do not drive until brakes are checked","o":["Do not drive until brakes are checked","Keep driving to a shop","Drive only on freeways until it goes off","Ignore it if the road is dry in daytime"],"why":"Section 12B (Braking and brake failure): a brake warning light means brakes are not working, so do not drive."},{"id":"cra-sy5lo2","q":"You use the parking brake to stop a car with failed brakes. How should you apply it?","a":"Slowly, ready to release if you skid","o":["Slowly, ready to release if you skid","As hard as you can in a single pull","After you turn the key to the off position","In short, quick pulls on the brake lever"],"why":"Section 12B: apply it slowly to avoid locking the rear wheels and be ready to release if you skid."},{"id":"cra-15y2sxg","q":"If the parking brake also fails, you should:","a":"Turn off the engine and find a safe spot","o":["Turn off the engine and find a safe spot","Shift into reverse and keep going","Stay on the road and keep driving to a shop","Speed up until you reach a long steep hill"],"why":"Section 12B: turn off the engine and look for a safe place well off the roadway."},{"id":"cra-1dn13cx","q":"The engine shuts off while you drive. The steering wheel:","a":"Hard to turn, but you can turn it","o":["Hard to turn, but you can turn it","Locked and cannot be turned","Easier to turn than usual","Unusable until the engine restarts"],"why":"Section 12B (Power failure): the wheel may be hard to turn, but you can turn it."},{"id":"cra-5jitnn","q":"After a power failure, you should:","a":"Brake gently, steady pressure, pull off","o":["Brake gently, steady pressure, pull off","Brake hard right away and stop in the lane","Take your hands off the wheel until it stops","Keep driving to the next exit"],"why":"Section 12B (Power failure): look for a safe place, brake gently with steady pressure, and pull off."},{"id":"cra-1dxe3zd","q":"A tire goes flat while you drive. You should:","a":"Grip the wheel, steer straight, slow down","o":["Grip the wheel, steer straight, slow down","Brake hard and stop right in the traffic lane","Turn the wheel sharply toward the shoulder","Accelerate to keep control of the vehicle"],"why":"Section 12B (Tire blowout): grip the wheel firmly, steer straight, slow gradually, and do not brake."},{"id":"cra-ydzz70","q":"A rear tire blows out. The vehicle will:","a":"Wobble, shake, and pull to that side","o":["Wobble, shake, and pull to that side","Pull away from the blown tire at once","Speed up on its own for a few seconds","Roll straight and steady with no wobble"],"why":"Section 12B (Tire blowout): a rear blowout makes the vehicle wobble, shake, and pull toward the blown tire."},{"id":"cra-plsy3e","q":"You must stop after a tire blowout. Where?","a":"Off the road, in a safe level spot","o":["Off the road, in a safe level spot","Right in the lane so others can see you","At the top of the next hill for a view","On a curve for others to see"],"why":"Section 12B (Tire blowout): do not stop on the road; pull off in a safe and level spot."},{"id":"cra-1wzmsjh","q":"You have a breakdown. What should you tie to the antenna or door handle?","a":"Something white or orange","o":["Something white or orange","Something red or bright yellow","Something dark green","Something black or dark gray"],"why":"Section 12B (Breakdowns): raise your hood and attach something white or orange to the antenna or door handle."},{"id":"cra-1dyl46d","q":"After a breakdown, what should you do first?","a":"Get the vehicle off the road","o":["Get the vehicle off the road","Stand behind your car and wave","Change the tire in the traffic lane","Wait for help in the traffic lane"],"why":"Section 12B (Breakdowns): get your vehicle off the roadway and away from traffic."},{"id":"cra-1ag9vcl","q":"Why put flares or triangles 200 to 300 feet behind a broken-down vehicle?","a":"Gives drivers time to change lanes or slow","o":["Gives drivers time to change lanes or slow","Marks a safe spot where other cars can park","Blocks the whole lane so nobody can pass it","Warns deer and other animals to stay away"],"why":"Section 12B (Breakdowns): it gives other drivers time to change lanes or slow down."},{"id":"cra-g8kv29","q":"A vehicle problem happens on a freeway. What is better than risking your life?","a":"A shredded tire or bent rim","o":["A shredded tire or bent rim","Stopping in a traffic lane","Fixing the problem in traffic","Walking along the freeway lanes"],"why":"Section 12B: a shredded tire or bent rim is better than risking your life."},{"id":"cra-nz6sr","q":"If you are off to the side and need help, you should:","a":"Stay in your vehicle if you can","o":["Stay in your vehicle if you can","Walk along the road for help","Stand behind your car and wave","Cross the road to flag down help"],"why":"Section 12B: stay in your vehicle and keep walking on the road to a minimum."},{"id":"cra-2ea0uk","q":"How can you steer around a hazard?","a":"Use both hands, steer where you want","o":["Use both hands, steer where you want","Use one hand and brake hard the whole time","Take both hands off the wheel and glide","Steer straight at the hazard"],"why":"Section 12B (Steering): ensure a good grip with both hands and steer in the direction you want."},{"id":"cra-1sscywn","q":"After you steer around a hazard, you should:","a":"Straighten out and slow down","o":["Straighten out and slow down","Speed up to get away","Keep swerving left and right","Stop at once in the lane"],"why":"Section 12B (Steering): once you have missed the hazard, straighten and slow down."},{"id":"cra-1jpc91t","q":"With ABS, a pulsing pedal and clicking noise are:","a":"Normal, and you can still steer","o":["Normal, and you can still steer","A sign you should let go of the pedal","A sign that the brakes have failed","A reason to pump the pedal harder"],"why":"Section 12B (ABS): the pedal may vibrate and click; this is normal, and you can still steer."},{"id":"cra-aaknte","q":"What does ABS help you do?","a":"Stop without skidding, keep steering","o":["Stop without skidding, keep steering","Drive faster on a slick road with less risk","Save fuel on long highway trips","Park without using the parking brake"],"why":"Section 12B (ABS): ABS helps you stop without skidding and helps keep steering control."},{"id":"cra-1fwsa9l","q":"A defensive driving course will:","a":"Lower your chance of a crash","o":["Lower your chance of a crash","Raise your chance of a crash","Have no effect on your crash risk","Make your driving riskier overall"],"why":"Section 12A: studies show your chances of a crash are much less after a defensive driving course."},{"id":"cra-9uqr2s","q":"What does defensive driving involve?","a":"Watching for crashes and others' mistakes","o":["Watching for crashes and others' mistakes","Driving faster than most others around you","Trusting other drivers to follow the rules","Skipping mirror and blind spot checks"],"why":"Section 12A: defensive driving involves looking for possible crashes and mistakes other drivers may make."},{"id":"cra-wqjfxf","q":"A national study found driver error is a factor in about what share of crashes?","a":"75 percent","o":["75 percent","10 percent","25 percent","5 percent"],"why":"Section 12A: driver error is a factor in 75% of all car crashes."},{"id":"cra-by02vr","q":"How many people will be in a crash in the next four years?","a":"One in four","o":["One in four","One in a hundred","One in two","One in ten"],"why":"Section 12A: one in four persons will be in a crash in the next four years."},{"id":"cra-4tgujn","q":"Motor vehicle crashes are the leading cause of death for which ages?","a":"1 to 24","o":["1 to 24","40 to 60","65 and over","25 to 39"],"why":"Section 12A: the leading cause of death for ages 1 to 24."},{"id":"cra-192yoce","q":"Who may a crash report be released to?","a":"An insurance company","o":["An insurance company","A neighbor who heard about it","A witness who saw the crash","A coworker of the driver"],"why":"Section 12E: reports may go to persons involved (not witnesses), parents, attorneys, insurers, investigators, or the media."},{"id":"cra-o0821u","q":"The reinstatement fee after a conviction for no insurance is:","a":"$40","o":["$40","$10","$400","$4"],"why":"Section 12D: an SR22 for three years and a $40 reinstatement fee."},{"id":"cra-8yglbk","q":"Does uninsured motorist coverage generally pay property damage?","a":"No, it generally does not","o":["No, it generally does not","Yes, always, to the full amount","Yes, but for fences only","Only when you are on a freeway"],"why":"Section 12D: property damage losses are generally not paid under uninsured motorist coverage."},{"id":"cra-1l8nd3t","q":"Collision coverage is:","a":"Not required by law, but lenders may ask for it","o":["Not required by law, but lenders may ask for it","Required by Utah law for every registered vehicle","Required for drivers who drive at night","Required of every new driver under age 21"],"why":"Section 12D: not required by law but generally required by a lien holder."},{"id":"cra-11fz7vg","q":"Comprehensive coverage pays for damage from:","a":"Fire, theft, vandalism, or broken glass","o":["Fire, theft, vandalism, or broken glass","Collision with another car","Speeding tickets and other traffic fines","Medical bills for injuries to passengers"],"why":"Section 12D: it covers damage by causes other than collisions, such as fire, theft, vandalism, or glass."},{"id":"cra-sf5vbr","q":"Bodily injury and property damage liability pays for:","a":"Injuries or damage you cause others","o":["Injuries or damage you cause others","Repairs to your own car after a crash","Medical bills for you and your passengers","Your own parking tickets"],"why":"Section 12D: it pays for injuries or damages caused by your negligence to another person or property."},{"id":"cra-1ec2fl2","q":"You hit a parked car and the owner cannot be found. The note must include:","a":"Your name, address, and plate number","o":["Your name, address, and plate number","Your phone number and insurance company","Your name and the exact time of the crash","Your license number and your birth date"],"why":"Section 12: leave a note with the driver's name and address and the vehicle plate number."},{"id":"cra-13j82l5","q":"Who must call 911 after a crash with injuries?","a":"Anyone involved in the crash","o":["Anyone involved in the crash","Only the other driver","Only a witness who stopped","No one, if both cars can move"],"why":"Section 12: if the crash results in injuries, death, or $2,500 in damage, you must notify law enforcement."},{"id":"cra-h3akn8","q":"After a crash with only property damage, you should stay at the scene:","a":"Until all requirements are done","o":["Until all requirements are done","For about five minutes","Until the other driver has left the scene","If police officers arrive at the scene"],"why":"Section 12: you shall remain at the scene or location described until other requirements are fulfilled."}]},{"id":"points","name":"Points & Penalties","icon":"⚖️","src":"Handbook: Suspensions & Your Record","qs":[{"id":"poi-uczjrt","q":"A driver under 21 can face a hearing at how many points in 3 years?","a":"70","o":["70","200","100","50"],"why":"Under 21 the threshold is 70 points in three years."},{"id":"poi-16fag1m","q":"A driver 21 or older can face a hearing at how many points in 3 years?","a":"200","o":["200","70","100","300"],"why":"Over 21 it is 200 points in three years."},{"id":"poi-5wmift","q":"Reckless driving is how many points?","a":"80","o":["80","60","50","35"],"why":"Reckless driving is 80 points."},{"id":"poi-qkwmr1","q":"Running a red light or stop sign is how many points?","a":"50","o":["50","35","60","80"],"why":"Each is 50 points."},{"id":"poi-m798m3","q":"Following too closely or failing to yield is how many points?","a":"60","o":["60","50","40","80"],"why":"Each is 60 points."},{"id":"poi-v35vls","q":"A defensive driving course can remove how many points?","a":"50, once every 3 years","o":["50, once every 3 years","100, once every year","25, any time you ask","All points, once every 3 years"],"why":"Course credit is 50 points, once per 3 years."},{"id":"poi-1w54m2e","q":"Driving while suspended can bring up to:","a":"90 days in jail plus a fine","o":["90 days in jail plus a fine","A written warning for a first time","A fine of $20 and no jail time","One day in jail and no fine at all"],"why":"The suspension is also extended by the original period."},{"id":"poi-zhnvw2","q":"Convictions stay on your driving record for how long (non-alcohol)?","a":"3 years","o":["3 years","1 year","5 years","10 years"],"why":"Most show for 3 years. Alcohol and drug violations show for 10."},{"id":"poi-1wema3b","q":"What happens after a Move Over law conviction?","a":"A 4-hour class in 90 days, or a suspension","o":["A 4-hour class in 90 days, or a suspension","A $500 fine and a retake of the driving skills test","A written warning and 20 points added to your record","Community service and a 30-day license suspension"],"why":"Take the class or the license is suspended 90 days."},{"id":"poi-2td46o","q":"How many points can a speeding violation carry?","a":"35 to 75, depending on how bad it is","o":["35 to 75, depending on how bad it is","20 to 40, depending on how fast you go","50 to 100, depending on how bad it is","40 to 80, depending on the speed limit"],"why":"Speeding points range from 35 to 75."},{"id":"poi-qmd119","q":"Texting while driving adds how many points?","a":"50","o":["50","10","80","200"],"why":"Texting while driving is 50 points."},{"id":"poi-173dhpj","q":"Driving on the wrong side of the road is how many points?","a":"60","o":["60","10","30","200"],"why":"Wrong side of the road and wrong way on a one-way street are 60 points each."},{"id":"poi-ow88ht","q":"Improper passing or improper lookout is how many points?","a":"50","o":["50","20","60","80"],"why":"Both are 50 points."},{"id":"poi-1ayoajq","q":"Most other moving violations carry how many points?","a":"40","o":["40","5","90","200"],"why":"Other moving violations are 40 points."},{"id":"poi-1s0jre8","q":"After one full year with no moving violation conviction, what happens to your points?","a":"Half are removed","o":["Half are removed","All are removed","None are removed","They double"],"why":"Half your total points are removed after a clean year."},{"id":"poi-8bfas9","q":"After two straight years with no conviction, what happens to your points?","a":"All are removed","o":["All are removed","Half are removed","None are removed","Only 10 are removed"],"why":"All points are cleared after two clean years."},{"id":"poi-qgp3lb","q":"Points from an individual violation drop off after:","a":"3 years","o":["3 years","1 year","6 months","10 years"],"why":"Points drop off 3 years after the violation date."},{"id":"poi-168u5jt","q":"What can happen after a point hearing?","a":"Probation, a defensive driving course, or suspension","o":["Probation, a defensive driving course, or suspension","A court fine, community service, or a short jail stay","A free license renewal, a new photo, or fewer points","A letter of warning, followed by a lifetime driving ban"],"why":"Outcomes depend on your record and range from probation to suspension."},{"id":"poi-1gsgxgn","q":"Which action brings a mandatory license revocation?","a":"Fleeing from a police signal","o":["Fleeing from a police signal","A single parking ticket downtown","One speeding ticket on a freeway","Forgetting to signal at a turn"],"why":"Fleeing an officer is a mandatory revocation."},{"id":"poi-1vcasdi","q":"You do not show up in court for a traffic ticket. What can happen?","a":"Your license may be suspended","o":["Your license may be suspended","The ticket is canceled after 90 days","A warning letter is mailed and nothing else","You get a second chance with no penalty"],"why":"Failing to appear can lead to a suspension."},{"id":"poi-qsl4p3","q":"You ignore a ticket from another state that belongs to the Non-Resident Violator Compact. What can happen in Utah?","a":"Your Utah license can be suspended","o":["Your Utah license can be suspended","Your Utah vehicle registration is canceled","Nothing happens, since it was out of state","Your insurance company is told to drop you"],"why":"Utah can suspend your license for failing to answer a ticket in an NRVC state."},{"id":"poi-1wtpl3r","q":"Under 21 drivers have which kind of point system?","a":"A separate provisional point system","o":["A separate provisional point system","The same system that everyone else uses","A system that gives a free first ticket","A shorter system that ends at age 18"],"why":"Provisional Class D licenses use a separate point system."},{"id":"poi-1o48gyt","q":"Driving on a suspension that was alcohol related can bring a fine up to:","a":"$1,000 and up to 6 months in jail","o":["$1,000 and up to 6 months in jail","$50 and a warning letter","$100 and a defensive driving class","$10,000 and 5 years in jail"],"why":"The handbook lists a fine up to $1,000 and up to six months in jail."},{"id":"poi-181rmnp","q":"Which of these is a mandatory revocation?","a":"Not stopping to help after a crash that hurts someone","o":["Not stopping to help after a crash that hurts someone","A first speeding ticket that adds 35 points to your record","Driving with a burned-out headlight","One ticket for an illegal U-turn"],"why":"Handbook Section 13E: failing to stop and give aid after a crash that injures or kills someone brings a mandatory revocation."},{"id":"poi-1i5t7sc","q":"A wrong way on a one-way street costs how many points?","a":"60","o":["60","40","50","80"],"why":"Section 13F: wrong way on a one-way street is 60 points."},{"id":"poi-1v5lwxb","q":"Improper lookout costs how many points?","a":"50","o":["50","60","80","35"],"why":"Section 13F: improper lookout is 50 points."},{"id":"poi-go5f2s","q":"A hearing for a point violation may lead to a denial or suspension of:","a":"One month to one year","o":["One month to one year","Five years in every case","Ten days at most","Life in every case"],"why":"Section 13F: denial or suspension may be one month to one year depending on your record."},{"id":"poi-1sdd1m0","q":"What is a defensive driving course for point removal different from?","a":"Traffic school offered by some courts","o":["Traffic school offered by some courts","The course the division recommends for points","The Utah Safety Council defensive driving course","A course that removes 50 points"],"why":"Section 13F: it is different from the traffic school offered by some courts."},{"id":"poi-1wth0dw","q":"How many points do you need within three years to be asked to a hearing if you are over 21?","a":"200","o":["200","70","100","300"],"why":"Section 13F: over 21, 200 or more points within three years."},{"id":"poi-22eu1q","q":"A careless driving conviction may lead to revocation if:","a":"A judge orders it","o":["A judge orders it","You pay a fine","You wear a belt","It happens at night"],"why":"Section 13E: revocation applies if convicted of careless driving and a judge has ordered the revocation."},{"id":"poi-189coz7","q":"Careless driving includes:","a":"Two or more moving violations in one drive","o":["Two or more moving violations in one drive","One parking ticket given while you are away","A late registration renewal with a small fee","Driving in daylight with your lights turned on"],"why":"Definitions: two or more moving traffic violations within a single continuous period of driving."},{"id":"poi-c8wnzb","q":"What happens after two reckless or impaired driving charges in one year?","a":"Mandatory revocation","o":["Mandatory revocation","Mandatory suspension","Mandatory probation","Mandatory retesting"],"why":"Section 13E: two reckless or impaired driving charges in one year bring mandatory revocation."},{"id":"poi-1wms6d7","q":"What is reckless driving?","a":"Willful disregard for safety of people or property","o":["Willful disregard for safety of people or property","Driving a few miles per hour over the limit on a clear day","Forgetting to signal once before a lane change","Parking a few inches away from the curb"],"why":"Section 13E: operating a vehicle in a willful and/or wanton disregard for the safety of persons or property."},{"id":"poi-1wozd3w","q":"Which of these can cause a mandatory revocation?","a":"Using a vehicle to commit a felony","o":["Using a vehicle to commit a felony","One speeding ticket on a city street","Driving with a cracked windshield","Failing to signal at a turn"],"why":"Section 13E: using a motor vehicle to commit or facilitate a felony."},{"id":"poi-1n21xm4","q":"Which of these brings a mandatory revocation?","a":"A false statement under oath for a license","o":["A false statement under oath for a license","Using the wrong lane one time on a freeway","Forgetting your wallet at home before a drive","A ticket for a noisy muffler"],"why":"Section 13E: making a false statement under oath when applying for a license."},{"id":"poi-37t6o4","q":"Discharging a firearm from a vehicle can bring:","a":"Mandatory revocation","o":["Mandatory revocation","Mandatory suspension","A written warning and a fine","Mandatory probation"],"why":"Section 13E: discharging or allowing the discharge of a firearm from a vehicle."},{"id":"poi-153316a","q":"Two road rage enhanced citations in one year can bring:","a":"Revocation","o":["Revocation","A warning","A free class","Nothing"],"why":"Section 13E: two citations enhanced as road rage violations in one year."},{"id":"poi-1qdi84a","q":"A driver who is convicted of a texting violation may have:","a":"A suspension, if a judge orders it","o":["A suspension, if a judge orders it","Points removed from your driving record","A longer license term","No penalty if it was your first offense"],"why":"Section 13D: the judge may order a suspension for a texting conviction."},{"id":"poi-2fallj","q":"Which of these can lead to a license suspension?","a":"Failing to pay child support","o":["Failing to pay child support","Driving a car with a dirty windshield","Parking the wrong way","Forgetting to use your turn signal once"],"why":"Section 13D: failure to pay child support is a listed suspension reason."},{"id":"poi-154zrrm","q":"Failing to show proof of insurance or security can lead to:","a":"A license suspension","o":["A license suspension","A bonus point on your record","Nothing at all","A free insurance policy"],"why":"Section 13D: failing to show proof of no-fault insurance or other security."},{"id":"poi-1xr4113","q":"Using false proof of age to buy alcohol under 21 can lead to:","a":"A license suspension","o":["A license suspension","A warning with nothing else","A free class with no penalty","Nothing at all"],"why":"Section 13D: under 21 and using false or improper proof of age to get alcohol or enter a bar."},{"id":"poi-mgukgb","q":"You drive while your license is suspended. The original suspension period will be:","a":"Increased by the original period","o":["Increased by the original period","Cut in half if you finish a course","Erased after a year","Left as it was with a new fine added"],"why":"Section 13C: the original time will be increased by the same amount."},{"id":"poi-1ego1gb","q":"Driving on a suspension for DUI can lead to:","a":"Impoundment of your vehicle","o":["Impoundment of your vehicle","A written warning","A smaller fine and a ten-day suspension","A license term that is one year longer"],"why":"Section 13C: your vehicle may be impounded if the suspension is for DUI or similar offenses."},{"id":"poi-18bjj4m","q":"How long do alcohol and drug violations stay on your record?","a":"10 years","o":["10 years","3 years","1 year","6 months"],"why":"Section 13B: all alcohol and drug related violations remain on the record for 10 years."},{"id":"poi-3aicn4","q":"What does your driving record contain besides convictions?","a":"Suspensions and your crash record","o":["Suspensions and your crash record","Your credit history","Your school grades and attendance record","Your medical files and health insurance"],"why":"Section 13B: the division keeps a computerized driving and crash record of every driver."},{"id":"poi-z7wfgs","q":"Wrong side of the road is 60 points. Which is also 60 points?","a":"Tailgating","o":["Tailgating","Running a red light","Texting while driving","Rolling a stop sign"],"why":"Section 13F: following too closely, wrong side, wrong way, and failing to yield are 60 points each."},{"id":"poi-2dmzv6","q":"Points for an individual conviction are removed automatically after:","a":"Three years after the violation date","o":["Three years after the violation date","Five years after the violation date","Ten years after the violation date","Four years after the date of conviction"],"why":"Section 13F: points are removed three years after the date of the violation."},{"id":"poi-13sghs2","q":"Texting while driving is 50 points. Which other violation is also 50 points?","a":"Improper passing","o":["Improper passing","Reckless driving","Failure to yield","Following too closely"],"why":"Section 13F: red light, stop sign, improper lookout, improper passing, and texting are 50 points."}]},{"id":"share","name":"Sharing the Road","icon":"🚲","src":"Handbook: Sharing the Road","qs":[{"id":"sha-6buix5","q":"When you pass a bicyclist, how much space must you leave?","a":"At least 3 feet","o":["At least 3 feet","At least 1 foot","At least 5 feet","Enough to avoid touching"],"why":"Give bicyclists at least 3 feet and slow down."},{"id":"sha-zbhep8","q":"You may stop, park, or drive in a marked bike lane (solid white line) when:","a":"You are entering a driveway or in an emergency","o":["You are entering a driveway or in an emergency","You need to pass slow traffic that is ahead of you","You are waiting for a gap before turning left","You are dropping off or picking up passengers"],"why":"Handbook Section 14A: stay out of bike lanes. You may enter one for a driveway, an emergency, or an officer's orders."},{"id":"sha-1n4g1e9","q":"Before you open your car door or back up you should:","a":"Check for bicyclists","o":["Check for bicyclists","Turn on the hazard lights","Roll down the window first","Honk to warn other drivers"],"why":"Doors opened into bike traffic cause crashes."},{"id":"sha-8wjall","q":"At night you should dim your headlights within how far of a bicyclist?","a":"500 feet","o":["500 feet","100 feet","1,000 feet","50 feet"],"why":"Dim lights within 500 feet of a bicyclist."},{"id":"sha-w0jdwa","q":"Bicyclists on the road have:","a":"The same rules as drivers","o":["The same rules as drivers","Special rules that skip stop signs","Rules that apply on sidewalks alone","Right-of-way over cars"],"why":"Handbook Section 14A: bicyclists have the same rights and duties as drivers."},{"id":"sha-1yq2laj","q":"Pedestrians can be hard to see when you turn. You should:","a":"Slow down, look twice, and yield","o":["Slow down, look twice, and yield","Honk and turn before they step out","Turn quickly so you clear the crosswalk","Wait for them to look at you first"],"why":"Many pedestrian crashes happen during turns."},{"id":"sha-3qsmv4","q":"How much of a lane do motorcycles deserve?","a":"A full lane","o":["A full lane","Half a lane","Whatever is left","The shoulder"],"why":"Never share a lane with a motorcycle."},{"id":"sha-1s18gbe","q":"A motorcycle's turn signal is flashing. You should:","a":"Not assume it is turning","o":["Not assume it is turning","Assume it is about to turn","Pass it on the right quickly","Speed up to get ahead of it"],"why":"Motorcycle signals often do not cancel."},{"id":"sha-1hxg9pn","q":"How far back should you follow a motorcycle?","a":"At least 2 seconds, more when wet","o":["At least 2 seconds, more when wet","Just one second, even when it is wet","About one car length, even in the rain","Bumper to bumper when traffic is slow"],"why":"Riders can brake and swerve fast."},{"id":"sha-1tos4hr","q":"Utah lane filtering is only legal for a motorcycle going:","a":"15 mph or less","o":["15 mph or less","25 mph or less","5 mph or less","45 mph or less"],"why":"Filtering also needs a stopped vehicle in the lane and a safe gap. Splitting is illegal."},{"id":"sha-1z0w5qp","q":"Motorcycle riders and passengers under what age must wear a helmet?","a":"21","o":["21","18","16","25"],"why":"Under 21 means a DOT approved helmet."},{"id":"sha-1kj4m4j","q":"If you cannot see a truck driver in the side mirror:","a":"The driver cannot see you","o":["The driver cannot see you","You are safe","You are in the no-zone only at night","You are too close but it is fine"],"why":"The no-zone includes sides, rear, and front."},{"id":"sha-z3xcv2","q":"After passing a truck you should:","a":"Wait to see its whole front in your mirror","o":["Wait to see its whole front in your mirror","Pull in as soon as you are alongside its cab","Cut in quickly to get out of its blind spot","Brake hard in front of it so it can see you"],"why":"Make sure there is plenty of room."},{"id":"sha-h549tl","q":"Why do trucks swing left before a right turn?","a":"Their long trailers need extra room","o":["Their long trailers need extra room","The driver cannot see the right side","They are trying to hog the lane","They must avoid the curb signs"],"why":"Never squeeze between a truck and the curb."},{"id":"sha-1pqk2sc","q":"An emergency vehicle with flashing lights approaches. You should:","a":"Pull to the right and stop","o":["Pull to the right and stop","Stop right where you are","Pull to the left and stop","Keep driving at your speed"],"why":"Move to the right edge and stop until it passes."},{"id":"sha-1o85un","q":"You may follow a fire engine responding to an alarm no closer than:","a":"500 feet","o":["500 feet","100 feet","50 feet","1,000 feet"],"why":"Do not follow one closer than 500 feet."},{"id":"sha-moqo2j","q":"The Move Over law tells you to:","a":"Slow down and change lanes away from it","o":["Slow down and change lanes away from it","Stop behind it and wait for it to leave","Pass it quickly on the shoulder side","Speed up to clear the area fast"],"why":"Move over or slow down for stationary hazard vehicles."},{"id":"sha-1yoxc0x","q":"A school bus on a two-lane road has flashing red lights. Who stops?","a":"Traffic in both directions","o":["Traffic in both directions","Only the traffic behind it","Only the oncoming traffic","Nobody, if there is no sign"],"why":"On two-lane roads both directions stop."},{"id":"sha-119vfjp","q":"A school bus on a divided highway with a median has flashing red lights. Who stops?","a":"Only vehicles behind the bus","o":["Only vehicles behind the bus","Traffic in both directions","Only the oncoming traffic","Nobody, if the median is wide"],"why":"With a median, only traffic behind the bus stops."},{"id":"sha-1xigc59","q":"An orange triangle on the back of a vehicle means it travels:","a":"Under 25 mph","o":["Under 25 mph","Over 55 mph","Only at night","Only on farm roads"],"why":"A slow-moving vehicle emblem."},{"id":"sha-1tmzodz","q":"Passing a horse and rider you should:","a":"Pass with care, not honk or rev","o":["Pass with care, not honk or rev","Honk once to warn the horse and rider","Rev your engine so they hear you coming","Pass quickly to clear the area fast"],"why":"Noise can spook animals."},{"id":"sha-1jr8jt3","q":"A police officer pulls you over. You should:","a":"Pull right, stop safely, and keep your hands on the wheel","o":["Pull right, stop safely, and keep your hands on the wheel","Keep driving at a slow speed until you find a well-lit road","Get out and walk back to the officer's car with your documents","Stay in your lane, flash your lights, and wait for a signal"],"why":"Park, turn the engine off, and stay put."},{"id":"sha-dbqgcj","q":"The operator of farm machinery on the road:","a":"May not hear your vehicle","o":["May not hear your vehicle","Is required to pull over for you","Can see behind well from the cab","Will always move to the shoulder"],"why":"Pass with care."},{"id":"sha-184sx25","q":"How are dedicated bike lanes marked?","a":"With solid white lines","o":["With solid white lines","With dashed yellow lines","With red cones","With green paint only"],"why":"Dedicated bike lanes are marked with solid white lines."},{"id":"sha-v8fvrh","q":"When may you sound your horn close to a bicyclist?","a":"Only if a crash is likely","o":["Only if a crash is likely","Whenever you are about to pass one","To say hello to a rider","To warn them every time you are close"],"why":"Handbook Section 14A: avoid sounding your horn close to bicyclists unless there is a chance of a crash."},{"id":"sha-2ts70w","q":"You are about to pass a bicyclist but a hill crest blocks your view. What should you do?","a":"Do not pass","o":["Do not pass","Pass quickly","Honk and pass","Pass on the right"],"why":"Do not pass a bicyclist near the crest of a hill or a curve with a blocked view."},{"id":"sha-nugnjc","q":"You may not pass a bicycle within what distance of an intersection or railroad crossing?","a":"100 feet","o":["100 feet","10 feet","50 feet","300 feet"],"why":"Do not pass within 100 feet of an intersection or railroad crossing."},{"id":"sha-102qd6d","q":"A bicyclist keeps both hands on the handlebars and does not signal a turn. Why?","a":"They may need both hands to stay in control","o":["They may need both hands to stay in control","They forgot how to give a signal on the road","Hand signals are against the law for bicyclists","They did not plan to turn at any point"],"why":"Bicyclists may skip hand signals when road conditions need both hands on the bars."},{"id":"sha-h88oax","q":"Which of these may a bicycle NOT have?","a":"A siren or whistle","o":["A siren or whistle","A white headlight at night","A red taillight or reflector","Reflectors on the sides"],"why":"A bicycle cannot have a siren or whistle. At night it needs a white headlight, a red taillight or reflector, and side reflectors."},{"id":"sha-lmm2xu","q":"How many bicyclists may ride side by side on a Utah road?","a":"No more than two","o":["No more than two","No more than four","No more than three","Just one"],"why":"Handbook Section 14A: bicyclists ride no more than two abreast, and only if they would not impede traffic."},{"id":"sha-j65g2t","q":"A Class 1 electric-assisted bicycle gives pedal assist only up to:","a":"20 mph","o":["20 mph","10 mph","28 mph","35 mph"],"why":"Class 1 is pedal-assist only and cuts off at 20 mph. Class 3 cuts off at 28 mph."},{"id":"sha-109z0q9","q":"A bicycle must be able to stop how quickly?","a":"Within 25 feet from 10 mph","o":["Within 25 feet from 10 mph","Within 5 feet from 5 mph","Within 100 feet from 30 mph","Within 50 feet from 20 mph"],"why":"The brake must stop it within 25 feet from 10 mph."},{"id":"sha-pk21on","q":"What does a bicyclist need at night?","a":"A white headlight, red taillight or reflector, side reflectors","o":["A white headlight, red taillight or reflector, side reflectors","A white headlight and a red taillight, plus a horn or a loud bell","A red headlight, a white taillight, and reflectors on the wheels","A bright light on the helmet and a reflector on the back"],"why":"Night riding needs a white headlight, red taillight or reflector, and side reflectors seen from 500 feet."},{"id":"sha-h524y5","q":"A bicycle, by Utah's definition, has wheels at least what diameter?","a":"14 inches","o":["14 inches","6 inches","10 inches","30 inches"],"why":"Bicycles have wheels at least 14 inches across."},{"id":"sha-geij","q":"A bicyclist rides slowly on a sidewalk. What must the rider do?","a":"Yield to pedestrians and give a sound signal before passing","o":["Yield to pedestrians and give a sound signal before passing","Ride in the crosswalk at full speed and signal with the horn","Ride at a normal pace and honk to move the walkers aside","Stay on the sidewalk but never slow down for walkers"],"why":"On sidewalks, bicyclists must ride slowly, yield, and signal before passing."},{"id":"sha-1jux4hc","q":"A bicyclist on a road with three or more lanes is going slowly. May you use the center left-turn lane to pass?","a":"Yes, if the cyclist is below a reasonable speed","o":["Yes, if the cyclist is below a reasonable speed","No, the center lane is for left turns and nothing else","Yes, but only at night when traffic is light","Yes, but only after the bicyclist waves you by"],"why":"The handbook allows it on roads with three or more lanes."},{"id":"sha-zrt8wb","q":"You pass a bicyclist and want to turn right soon after. What should you not do?","a":"Turn sharply in front of them","o":["Turn sharply in front of them","Slow down and watch for them","Check your mirrors before turning","Signal well ahead of the turn"],"why":"Do not turn sharply in front of a bicyclist or force them off the road."},{"id":"sha-ii4ibb","q":"Where should a pedestrian walk if there is no sidewalk?","a":"On the left shoulder, facing traffic","o":["On the left shoulder, facing traffic","On the right shoulder, with the traffic","In the middle of the lane, near the line","Behind the parked cars"],"why":"Handbook Section 14G: if there are no sidewalks, always walk or jog facing traffic on the left side of the shoulder or roadway."},{"id":"sha-cvjn6y","q":"A school traffic patrol member is signaling you. What should you do?","a":"Stop and yield","o":["Stop and yield","Slow down and pass them","Honk and go","Speed up to clear the area"],"why":"Handbook Section 14G: stop and yield as signaled at school crossings where there is a traffic patrol."},{"id":"sha-1f42u9m","q":"Most pedestrian deaths in Utah happen at what time?","a":"In the evening, around 9 p.m.","o":["In the evening, around 9 p.m.","At noon on school days","At 6 a.m. as people go to work","Around 3 p.m. after school ends"],"why":"Over 2015-2025 the deadliest hour was 9 p.m. (51 deaths), then 6 p.m. and 7 p.m. (45 each)."},{"id":"sha-jfw70k","q":"A leading driver factor in Utah pedestrian deaths is:","a":"Failing to yield right-of-way","o":["Failing to yield right-of-way","Driving too slowly in the right lane","Using high beams in the daytime","Using hazard lights on city streets"],"why":"Failing to yield right-of-way was the leading driver factor in 2025 pedestrian deaths. Disregarding traffic signals was next."},{"id":"sha-85pruz","q":"Riders on motorcycles may swerve suddenly because of:","a":"Potholes, gravel, seams, or railroad crossings","o":["Potholes, gravel, seams, or railroad crossings","Left turn signals from the cars far ahead of them","Clear roads with wide lanes and dry pavement","Warm weather and a smooth freeway surface"],"why":"Riders may swerve for road hazards, so give them room."},{"id":"sha-mcfkty","q":"A large truck has a front no-zone of about:","a":"20 feet","o":["20 feet","2 feet","200 feet","5 feet"],"why":"Truck blind spots reach up to 20 feet in front of the cab."},{"id":"sha-1pozflp","q":"A large truck has a rear no-zone that can reach:","a":"Up to 200 feet","o":["Up to 200 feet","Up to 100 feet","Up to 500 feet","Up to 50 feet"],"why":"The blind spot behind a trailer can reach 200 feet."},{"id":"sha-1ttamia","q":"Which side of a truck has the biggest blind spot?","a":"The right side","o":["The right side","The left side","The front only","The back only"],"why":"The right side is the truck's largest blind spot."},{"id":"sha-1k2hpxs","q":"A tractor-trailer going 55 mph and fully loaded may need more than what distance to stop?","a":"400 feet","o":["400 feet","50 feet","130 feet","200 feet"],"why":"A car at 55 mph stops in about 130 to 140 feet. A loaded tractor-trailer may need over 400."},{"id":"sha-4mc8k3","q":"When you meet a large truck on a two-lane road you should:","a":"Move as far right as you can","o":["Move as far right as you can","Move toward the center line to give room","Brake hard to let the truck pass","Flash your lights to get its attention"],"why":"Wind blasts from trucks can push you, so move right."},{"id":"sha-1vy24q5","q":"You see a single lane work zone ahead and a truck is beside you. What should you not do?","a":"Try to beat the truck into the zone","o":["Try to beat the truck into the zone","Slow down and stay behind the stop line","Follow the flagger's directions closely","Let the truck go first"],"why":"Handbook Section 14C: do not try to beat a truck into a single-lane construction zone."},{"id":"sha-1sbfg2m","q":"Most deadly crashes involving a truck and another vehicle are caused by:","a":"The other vehicle, usually a car","o":["The other vehicle, usually a car","The truck driver, usually from speeding","The weather, usually from heavy rain","The road, usually from construction"],"why":"NHTSA says 71 percent are caused by the other vehicle."},{"id":"sha-kil9j","q":"A large vehicle is stopped on a hill ahead of you. What should you watch for?","a":"Stalling or rolling backward","o":["Stalling or rolling backward","It speeding up fast on the hill","It honking at you to get closer","Nothing, since trucks never roll back"],"why":"Stay back in case it stalls or rolls back."},{"id":"sha-9hjr4l","q":"A school bus has flashing yellow lights. This means:","a":"It is about to stop, so slow down","o":["It is about to stop, so slow down","It has stopped, so you may pass at speed","It is leaving the road for a break","It is a signal to speed up and pass"],"why":"Yellow lights warn that the bus is getting ready to stop."},{"id":"sha-3tl4hc","q":"A school bus has flashing red lights on a four-lane road with no median. Who must stop?","a":"Traffic in both directions","o":["Traffic in both directions","Only traffic behind the bus","Only traffic coming toward the bus","No one"],"why":"Without a median, traffic in both directions must stop."},{"id":"sha-1xvg3j0","q":"A school bus stops with flashing red lights on a road with five lanes, including a center turn lane. Who must stop?","a":"Only vehicles behind the bus","o":["Only vehicles behind the bus","Traffic in both directions","Only vehicles coming toward the bus","No one"],"why":"With five or more lanes, oncoming traffic does not have to stop."},{"id":"sha-je0o8y","q":"When may you go after a school bus stops with flashing red lights?","a":"When the red lights stop flashing","o":["When the red lights stop flashing","When the bus driver waves you around","After counting to ten seconds","As soon as the children have crossed"],"why":"Do not proceed until the flashing red light or signal has stopped."},{"id":"sha-1hfp6xn","q":"A police officer signals you to stop while you are in the HOV or express lane. What should you do?","a":"Pull to the right, even through the other lanes","o":["Pull to the right, even through the other lanes","Stop in the lane you are in, even in the HOV lane","Speed up and find a place to stop on the left side","Pull to the left shoulder if it is closer"],"why":"Pull to the right and stop, even if you are in an HOV lane."},{"id":"sha-nojqox","q":"During a police stop, you should keep your seat belt:","a":"On","o":["On","Off","Half on","Off, so you can reach your papers"],"why":"Park, turn off the engine, lower the window, keep your belt on, and keep your hands on the wheel."},{"id":"sha-1779bsz","q":"You approach a stationary vehicle with amber lights while in the HOV lane. What should you do?","a":"Leave the HOV lane when practical","o":["Leave the HOV lane when practical","Speed up and pass the vehicle on the right","Stay in the lane at the same speed","Honk to warn the stopped vehicle"],"why":"Move out of the HOV lane when practical."},{"id":"sha-wvl0fi","q":"Golf cart operators may not:","a":"Drink alcohol while driving","o":["Drink alcohol while driving","Follow bicycle rules","Check local ordinances before driving","Drive on a road that city rules allow"],"why":"Handbook Section 14J: golf cart operators follow the same rules as a bicycle and may not drink alcohol while operating a golf cart."},{"id":"sha-16k2ixj","q":"A farm tractor is on the road. How should you pass?","a":"With care, since the operator may not hear you","o":["With care, since the operator may not hear you","Quickly while honking your horn the whole time","Around the right side at high speed","By following it for miles without passing"],"why":"Farm machinery operators may not hear your vehicle, so pass with care."},{"id":"sha-1b3b64w","q":"A driver is convicted of not following the Move Over law. What must the driver do?","a":"Take a four hour live defensive driving class","o":["Take a four hour live defensive driving class","Retake the written knowledge test within 30 days","Complete a one hour online safety course","Serve a one year suspension and pay a fine"],"why":"The class must be done within 90 days, or the license is suspended for 90 days."},{"id":"sha-azojmk","q":"Under what age may a person not operate a Class 3 electric-assisted bicycle?","a":"16","o":["16","12","14","18"],"why":"An individual under 16 may not operate a Class 3 electric-assisted bicycle."},{"id":"sha-1d0jk2f","q":"A pedestrian crosses with a white cane or guide dog. What must you do?","a":"Come to a complete stop","o":["Come to a complete stop","Slow down and pass on the left","Honk to warn them","Yield only if cars are behind you"],"why":"Always yield to the visually impaired and stop completely."},{"id":"sha-1q254d5","q":"A vehicle is stopped at a crosswalk ahead of you. You should:","a":"Never pass it, since people may be crossing unseen","o":["Never pass it, since people may be crossing unseen","Pass on the left if the lane is clear and you see nobody","Honk twice and pass slowly on the right side","Pass on the right shoulder if it is paved"],"why":"Never pass vehicles stopped at a crosswalk."},{"id":"sha-10pih49","q":"You may not drive or park on the same block where:","a":"A fire vehicle has stopped to answer an alarm","o":["A fire vehicle has stopped to answer an alarm","A police car is parked beside a crash to write a report","A delivery truck is unloading its cargo","A tow truck is working to move a car"],"why":"Unless on official business, stay off the block where the fire vehicle stopped."},{"id":"sha-hpoq3i","q":"Which of these is a vulnerable user of the highway under Utah law?","a":"A person riding a horse","o":["A person riding a horse","The driver of an enclosed car","A truck driver","A bus driver"],"why":"Utah law includes a person riding an animal, along with pedestrians, bicyclists, and motorcyclists."}]},{"id":"rail","name":"Railroads & Light Rail","icon":"🚆","src":"Handbook: Trains & Railroad Crossings","qs":[{"id":"rai-1wnd8uq","q":"How far from the nearest rail should you stop at a crossing?","a":"15 to 50 feet from the nearest rail","o":["15 to 50 feet from the nearest rail","5 to 10 feet from the nearest rail","75 to 100 feet from the nearest rail","Right at the edge of the rail"],"why":"Stop 15 to 50 feet back."},{"id":"rai-rjrpnu","q":"Flashing red lights at a crossing mean:","a":"Stop, and do not go while they flash","o":["Stop, and do not go while they flash","Slow down and cross when it looks clear","Yield to the cars on the cross road","Proceed if you cannot see a train"],"why":"Always stop."},{"id":"rai-1odw7ki","q":"The gates at a crossing are down. You may:","a":"Wait until they rise and lights stop","o":["Wait until they rise and lights stop","Go around them if no train is seen","Drive under them slowly and carefully","Cross quickly before the train arrives"],"why":"Never drive around or under a gate."},{"id":"rai-5gly03","q":"When a train and a vehicle meet, who has the right-of-way?","a":"The train, every time","o":["The train, every time","The larger vehicle","Emergency vehicles","The first one to the crossing"],"why":"Trains have the right-of-way, even over ambulances and police."},{"id":"rai-16eh8jl","q":"Your car stalls on the tracks. What do you do first?","a":"Get everyone out and away from the tracks","o":["Get everyone out and away from the tracks","Try to restart the engine before you leave","Stay inside the car and wait for tow help","Honk the horn to warn the train driver"],"why":"People first. Move away from the tracks at an angle, away from the train."},{"id":"rai-1hgv20a","q":"How much room does a 100-car freight train at 55 mph need to stop?","a":"More than a mile","o":["More than a mile","About 100 yards","About 500 feet","About 2 football fields"],"why":"Trains cannot stop quickly."},{"id":"rai-c64saq","q":"A flashing train logo at an intersection is:","a":"A warning only; obey the signals and signs","o":["A warning only; obey the signals and signs","A signal that you must stop before the tracks","A sign that the crossing is closed for repairs","A sign that you may pass other cars here"],"why":"The flashing train logo is not an indication to stop but merely an additional warning device."},{"id":"rai-3xzvqj","q":"With light rail (TRAX) you should:","a":"Never try to beat it through the crossing","o":["Never try to beat it through the crossing","Cross fast because light rail is slow","Follow the car ahead across the tracks","Stop on the tracks if traffic is backed up"],"why":"Wait until gates rise and the lights stop."},{"id":"rai-tktdkj","q":"You should never stop:","a":"On the tracks","o":["On the tracks","Behind the gate","Before the crossing","At a stop line"],"why":"Make sure you can fully clear the tracks."},{"id":"rai-g1brq9","q":"Which vehicles must stop at every railroad crossing?","a":"School buses and hazmat trucks","o":["School buses and hazmat trucks","Only commercial trucks and buses","Only motorcycles and bicycles","Only vehicles with trailers"],"why":"They also never shift gears on the crossing."},{"id":"rai-cqwun3","q":"At a crossing you should never:","a":"Pass a vehicle going your direction","o":["Pass a vehicle going your direction","Slow down and look both ways for trains","Turn the radio down so you can hear","Stop behind the line and wait for the gates"],"why":"Never pass at a crossing."},{"id":"rai-1v2onbo","q":"A train looks like it is moving slowly. You should know that:","a":"It is closer and faster than it seems","o":["It is closer and faster than it seems","It is as slow as it looks from the road","It will stop before it reaches the crossing","It is probably very far away from you"],"why":"Trains are quieter and faster than they look."},{"id":"rai-1ko8l8b","q":"Where may you walk on railroad tracks?","a":"Nowhere, it is illegal and dangerous","o":["Nowhere, it is illegal and dangerous","Anywhere, as long as you watch for trains","At night when the track lights are showing","Beside the rails, if you stay a few feet back"],"why":"Tracks are private property."},{"id":"rai-1t9uz4x","q":"You approach a crossing. What should you do with the radio?","a":"Turn it down so you can hear","o":["Turn it down so you can hear","Turn it up to stay alert at crossings","Leave it at the same level as before","Turn it off after dark"],"why":"Handbook Section 14L: trains sound their horns as they approach a crossing, so turning down the car radio is a good safety measure."},{"id":"rai-1yrqfqa","q":"It is night and you do not see a train. May you assume none is coming?","a":"No, trains can come at any time","o":["No, trains can come at any time","Yes, because trains do not run at night","Yes, after midnight when schedules end","Only on weekdays when freight runs"],"why":"Do not assume no train is coming at night."},{"id":"rai-18pwqqf","q":"A TRAX light rail train can reach 65 mph in about how long?","a":"21 seconds","o":["21 seconds","2 minutes","5 minutes","10 minutes"],"why":"TRAX reaches 65 mph in about 21 seconds, so it covers distance fast."},{"id":"rai-rv91l3","q":"How far past the rails can a train reach?","a":"3 feet or more","o":["3 feet or more","Under 1 foot","6 inches at most","Less than 3 inches"],"why":"Handbook Section 14L: a train may extend three feet or more outside the steel rail."},{"id":"rai-1cndk3p","q":"A train has just passed. When may you cross?","a":"When the gates are up and the lights have stopped","o":["When the gates are up and the lights have stopped","As soon as the last car of the train has passed","Right away, after you honk your horn to warn others","After a short wait of about five or ten seconds"],"why":"Wait until gates rise and lights stop flashing."},{"id":"rai-10pp2um","q":"A train has just passed but the lights keep flashing. What should you do?","a":"Wait, because another train may be coming","o":["Wait, because another train may be coming","Cross at once since the first train passed","Drive around the gates to save time","Honk and go once you see no train"],"why":"Always check for another train, especially at multi-track crossings."},{"id":"rai-1y17su5","q":"Your car stalls on the tracks and a train is coming. Where should you run?","a":"Away from the tracks at an angle","o":["Away from the tracks at an angle","Under the crossing gate to the road","Back into the car to wait for help","Along the tracks in the same direction"],"why":"Get everyone out and run away from the tracks at an angle, away from the train."},{"id":"rai-1phoqkm","q":"Your car is stuck on the tracks. Who should you notify?","a":"The authorities","o":["The authorities","Your insurance agent","A relative","A mechanic or tow shop"],"why":"Handbook Section 14L: if your vehicle stalls on a crossing, get everyone out and off the tracks, then notify local authorities right away."},{"id":"rai-1h2ucib","q":"A railroad crossing has no stop line. Where do you stop?","a":"15 to 50 feet from the nearest rail","o":["15 to 50 feet from the nearest rail","Within 5 to 10 feet of the nearest rail","About 100 feet back from the nearest rail","At the edge of the first track"],"why":"Handbook Section 8H: if there is no stop line, stop more than 15 feet but not more than 50 feet from the nearest rail."},{"id":"rai-1lewwb1","q":"A crossing has a flashing train logo on an overhead sign. What does it mean?","a":"It is a warning only","o":["It is a warning only","The crossing is closed","It is safe","Train is passing now"],"why":"The train logo is a warning. Follow the signals and signs."},{"id":"rai-a7o8sm","q":"After a full stop you think the crossing lights are broken. You may cross only with a clear view down the tracks of at least:","a":"One mile in both directions","o":["One mile in both directions","100 feet in both directions","500 feet in both directions","A quarter mile in one direction"],"why":"You also need no sign of a train, and you must be able to cross safely."},{"id":"rai-1ozuhyc","q":"How close may you park to a railroad crossing, unless signs or local law allow it?","a":"No closer than 50 feet","o":["No closer than 50 feet","No closer than 10 feet","No closer than 25 feet","No closer than 100 feet"],"why":"Do not park closer than 50 feet from a crossing."},{"id":"rai-rfh4ug","q":"A stop line, an X, and the letters RR are painted on the road. What do they mean?","a":"A crossing is ahead, so watch for a train","o":["A crossing is ahead, so watch for a train","Parking is allowed in this area at night","Trains must stop here before the road","You may pass other vehicles here if clear"],"why":"These markings warn you of a crossing ahead."},{"id":"rai-14m0l1s","q":"Where are crossbuck signs found?","a":"At all public crossings","o":["At all public crossings","Only at crossings with gates","Only at crossings in cities","Only at crossings with flashing lights"],"why":"If there is more than one track, a sign below shows the number of tracks."},{"id":"rai-th3wxq","q":"Rails are on the ties, but the track has weeds and looks rusty. You should assume:","a":"The track is still in use","o":["The track is still in use","The track is abandoned","Trains only run there at night","It is safe to walk on"],"why":"If there are rails on the ties, assume the track is in use."},{"id":"rai-yvspr2","q":"If a sign below a crossbuck is posted, what does it show?","a":"The number of tracks","o":["The number of tracks","The train's speed","How far away the train is","The phone number of the railroad"],"why":"Handbook Section 14L: crossbuck signs, the railroad crossing signs, are found at all public crossings. If there is more than one set of tracks, a sign below shows the number of tracks."},{"id":"rai-6u4mcz","q":"What should a school bus or hazmat truck driver avoid doing on a railroad crossing?","a":"Shifting gears","o":["Shifting gears","Looking both ways","Listening for trains","Making a gradual stop before the tracks"],"why":"Handbook Section 14L: these drivers must stop at every crossing and must not shift gears on the crossing."}]},{"id":"equip","name":"Equipment & Towing","icon":"🔧","src":"Handbook: Vehicle Equipment & Towing","qs":[{"id":"equ-17w5z4i","q":"High beam headlights must light the road about how far?","a":"350 feet","o":["350 feet","100 feet","500 feet","1,000 feet"],"why":"Low beams reach about 100 feet."},{"id":"equ-jztmwt","q":"Your horn must be heard from at least:","a":"200 feet","o":["200 feet","50 feet","500 feet","1,000 feet"],"why":"Horns must be audible from 200 feet."},{"id":"equ-1g4s5eu","q":"Tail lights and stop lights must be visible from:","a":"500 feet","o":["500 feet","100 feet","200 feet","1,000 feet"],"why":"Rear lights must show from 500 feet."},{"id":"equ-aj1jl9","q":"Which of these may you hang from your mirror or windshield?","a":"Nothing that blocks your view","o":["Nothing that blocks your view","Anything under four inches long","Only a parking permit or tag","Only a small air freshener"],"why":"Windshield must be clear of obstruction."},{"id":"equ-dne20f","q":"Red or blue lights visible from the front are for:","a":"Only emergency and other authorized vehicles","o":["Only emergency and other authorized vehicles","Any large truck that is hauling a wide load","Taxis and rideshare drivers who work at night","Delivery vans that work in busy city traffic"],"why":"Others may not use them."},{"id":"equ-a92xqg","q":"Sirens, whistles, and bells are for:","a":"Authorized emergency vehicles only","o":["Authorized emergency vehicles only","Any vehicle that is in an emergency","Trucks that weigh over 10,000 pounds","School buses and city buses on routes"],"why":"Keep them off personal vehicles."},{"id":"equ-1xftktl","q":"A drawbar between two vehicles can be at most:","a":"15 feet","o":["15 feet","5 feet","25 feet","50 feet"],"why":"Rope or chain tows need a flag at least 12 inches square."},{"id":"equ-1lhg5hm","q":"A load extending 4 feet or more past the vehicle needs:","a":"Flags or lights on the end","o":["Flags or lights on the end","A police escort in front of it","A horn mounted on the load itself","Nothing extra if it is tied down tight"],"why":"Use red flags by day and lights at night."},{"id":"equ-csfgcj","q":"Is a fire extinguisher legally required in a car?","a":"No, but it is recommended","o":["No, but it is recommended","Yes, in every passenger car","Yes, in cars with trailers","Yes, in cars over five years old"],"why":"Recommended for all drivers."},{"id":"equ-13g4mv2","q":"What is the maximum width of most vehicles?","a":"8 and a half feet","o":["8 and a half feet","7 and a half feet","9 and a half feet","10 and a half feet"],"why":"Farm tractors may be 9 feet."},{"id":"equ-1jfvith","q":"Driver assist features like lane keeping mean you:","a":"Must stay engaged and keep sensors clean","o":["Must stay engaged and keep sensors clean","Can let the car drive itself on any road","Can look away from the road briefly","Can skip your head check on lane changes"],"why":"You are still the driver."},{"id":"equ-16cqk1j","q":"Which vehicles must have a parking brake?","a":"All except motorcycles","o":["All except motorcycles","Only trucks and buses","Only vehicles with a stick shift","Only vehicles over 3,000 pounds"],"why":"One working parking brake is required."},{"id":"equ-1m0njat","q":"How many white headlights does a car need?","a":"At least two, one on each side","o":["At least two, one on each side","One, placed in the center of the car","Three, with one in the center of the car","None, if there are fog lights on the car"],"why":"At least two white headlights, one per side."},{"id":"equ-mxqsv","q":"Your license plate light must make the plate readable from:","a":"50 feet","o":["50 feet","10 feet","500 feet","5 feet"],"why":"The light must make the plate readable from 50 feet."},{"id":"equ-19ow3qt","q":"Turn signals must be visible from:","a":"100 feet","o":["100 feet","10 feet","500 feet","1,000 feet"],"why":"Turn signals must be visible from 100 feet."},{"id":"equ-1etbijl","q":"Parking lights on the front of a car are:","a":"White or amber","o":["White or amber","Red or blue","Green or purple","Blue or green"],"why":"Parking lights in front are white or amber."},{"id":"equ-1glp2mk","q":"How many windshield wipers must a vehicle have at least?","a":"One","o":["One","Two","Three","None"],"why":"At least one working wiper is required."},{"id":"equ-1i2490s","q":"A towed vehicle must have:","a":"A safety chain or cable","o":["A safety chain or cable","A siren and a flashing light","A radio and a loud horn","A bumper sticker with a warning"],"why":"Towed vehicles need safety chains or cables."},{"id":"equ-6ok1x4","q":"A flag on a load that sticks out 4 feet or more must be at least:","a":"12 inches square","o":["12 inches square","1 inch square","6 inches square","48 inches square"],"why":"Flags on the load must be at least 12 inches square."},{"id":"equ-po17ss","q":"Advanced driver assist systems may not work well in:","a":"Rain, snow, ice, fog, hills, or curves","o":["Rain, snow, ice, fog, hills, or curves","Clear, dry weather on a flat, straight road","Straight highways in good daylight","Parking lots on a calm, sunny day"],"why":"Stay engaged, because the systems may fail in bad weather or on curves."},{"id":"equ-1dm02o7","q":"Reflectors on the sides of a vehicle must be seen from:","a":"500 feet","o":["500 feet","50 feet","100 feet","10 feet"],"why":"Reflectors must be visible from 500 feet."},{"id":"equ-r7n9sb","q":"Buses, RVs, and trailers 80 inches or wider need:","a":"Clearance lights","o":["Clearance lights","A rear-view camera","Fog lights and a horn","A loud back-up alarm"],"why":"These vehicles need two amber lights in front and two red in the rear, plus side lights, visible from 500 feet."},{"id":"equ-6hd293","q":"Which safety features may you not use during the driving skills test?","a":"Parking assist and cruise control","o":["Parking assist and cruise control","Turn signals, mirrors, and the horn","Seat belts, headlights, and the wipers","The parking brake and the hazard lights"],"why":"The handbook says you cannot use features such as parking assist and cruise control on the test."},{"id":"equ-zpldvn","q":"Your car has ABS and you brake on a slippery road. What should you do?","a":"Apply constant, firm pressure","o":["Apply constant, firm pressure","Pump the brakes rapidly and often","Tap once and then release fully","Pump the brakes three times in a row"],"why":"With ABS it is unnecessary to pump the brakes."},{"id":"equ-14ztf81","q":"Emergency flares, reflectors, and lights must be seen from at least:","a":"600 feet","o":["600 feet","100 feet","300 feet","1,000 feet"],"why":"They must be seen and distinguished at not less than 600 feet."},{"id":"equ-i2zqjr","q":"Trucks, truck tractors, and buses must carry how many flares, reflectors, or red electric lights?","a":"Three","o":["Three","Five","Eight","Twelve"],"why":"They must also carry two red flags with standards."},{"id":"equ-191329p","q":"Which vehicles may not carry flares or fuses?","a":"Those carrying explosives or flammable materials","o":["Those carrying explosives or flammable materials","Trucks and buses that must carry three red flares","Buses that carry students to and from school","Trucks that haul grain and other farm crops"],"why":"Flares and fuses may not be carried in vehicles hauling explosives, flammable liquids, or compressed gas."},{"id":"equ-dxkocy","q":"Pollution control devices that came on your vehicle must be:","a":"Kept as effective as the original equipment","o":["Kept as effective as the original equipment","Removed once the vehicle is over ten years old","Replaced with new parts every two years","Optional on any used car being sold or traded"],"why":"Owners must keep and maintain the equipment."},{"id":"equ-l5jjlr","q":"Emergency flares must be able to burn for at least how long?","a":"12 hours","o":["12 hours","15 minutes","1 hour","6 hours"],"why":"Handbook Section 15: flares must be capable of burning for 12 hours. Fuses must burn for at least 15 minutes."},{"id":"equ-gx3o52","q":"Mud flaps or guards are required on a vehicle with a gross weight rating of:","a":"10,500 pounds or more","o":["10,500 pounds or more","More than 8,000 pounds in total weight","7,500 pounds or more","9,500 pounds or more"],"why":"Handbook Section 15: vehicles with a gross vehicle weight rating of 10,500 pounds or more need mudguards, flaps, or splash aprons."}]},{"id":"moto","name":"Motorcycles & Small Vehicles","icon":"🏍️","src":"Handbook: Sections 4, 14 (motorcycles, scooters, ATVs)","qs":[{"id":"mot-138rfta","q":"What do you need to ride a motorcycle on Utah highways?","a":"A motorcycle endorsement on your license","o":["A motorcycle endorsement on your license","A boat license and a safety card","A truck permit with an extra stamp","Nothing special beyond a regular license"],"why":"Your driver license must have a motorcycle endorsement (M)."},{"id":"mot-1bger6r","q":"Can a first-time rider get a motorcycle learner permit?","a":"Yes, if you have not been licensed to ride before","o":["Yes, if you have not been licensed to ride before","No, a rider must hold a full motorcycle license first","Yes, but you must be 30 years old or older","Yes, but you must also hold a CDL first"],"why":"A person never licensed to ride may be issued a motorcycle learner permit."},{"id":"mot-2jhdt1","q":"How can a rider skip the rider skills part of the motorcycle test?","a":"By finishing a division approved motorcycle course","o":["By finishing a division approved motorcycle course","By paying an extra fee at the front counter window","By riding with a licensed rider for six weeks","By passing a written test with a perfect score"],"why":"The division may waive the skills test after an approved motorcycle education course."},{"id":"mot-1l5tv61","q":"How do the motorcycle endorsement requirements compare to an operator license?","a":"Same requirements, but different tests","o":["Same requirements, but different tests","Same tests, but a longer waiting period","No test of any kind is needed","A separate state exam replaces the tests"],"why":"The requirements are the same as for an operator license, except that the tests are different."},{"id":"mot-1vpvtnd","q":"A street-legal motorcycle in Utah must carry:","a":"Liability insurance","o":["Liability insurance","A spare tire and tool kit","A first aid kit","A windshield and a sidecar"],"why":"Handbook Section 14F: all motorcycles licensed for street use must have liability insurance."},{"id":"mot-1u8cze2","q":"A 19 year old passenger is on the back of a motorcycle. What must the passenger wear?","a":"An approved DOT helmet","o":["An approved DOT helmet","Nothing, since passengers are exempt","Only goggles to protect the eyes","A baseball cap with a chin strap"],"why":"Any operator or passenger under 21 must wear an approved DOT helmet."},{"id":"mot-6e94rl","q":"Lane filtering by a motorcycle is legal only if the rider is going:","a":"15 mph or less","o":["15 mph or less","30 mph or less","45 mph or less","No faster than traffic"],"why":"Lane filtering needs 15 mph or less, a stopped vehicle in the lane, and a safe move."},{"id":"mot-1wjpml7","q":"Lane filtering is allowed only on roads with a speed limit of:","a":"45 mph or less, or on an off-ramp","o":["45 mph or less, or on an off-ramp","65 mph or less on any highway","75 mph or less on the interstate","Any speed if the rider is careful"],"why":"The road must be 45 mph or less, or the rider must be on an off-ramp."},{"id":"mot-1ra1d7q","q":"Where is lane filtering NOT allowed?","a":"On an on-ramp","o":["On an on-ramp","On an off-ramp","On a multi-lane road with a stopped car","On a road posted 35 mph"],"why":"The handbook says it is not permitted on an on-ramp."},{"id":"mot-50s2j4","q":"During lane filtering, the vehicle being passed must be:","a":"Stopped","o":["Stopped","Going 15 mph","Going 45 mph","Signaling"],"why":"The overtaken vehicle must be stopped."},{"id":"mot-1ytsezf","q":"A motorcycle waits at a signal that does not detect it. When may a rider 16 or older go?","a":"After 90 seconds if no one is near, age 16 or older","o":["After 90 seconds if no one is near, age 16 or older","After 30 seconds if no one is near, age 16 or older","Right away, since the signal is probably broken","Not until a car pulls up and trips the signal"],"why":"Operators 16 or older may go after waiting 90 seconds when it is safe."},{"id":"mot-123dhib","q":"Which of these describes a motorcycle in the handbook's definitions?","a":"A saddle for the rider and no more than three wheels on the ground","o":["A saddle for the rider and no more than three wheels on the ground","A steering wheel for the driver and at least four wheels on the ground","A bench seat for the driver and an enclosed passenger shell","Pedals for the rider and an electric motor of under 750 watts"],"why":"A motorcycle has a saddle for the rider and not more than three wheels in contact with the ground."},{"id":"mot-juyfyd","q":"A motor-assisted scooter rider is under 15. What is required?","a":"Supervision by a parent or guardian","o":["Supervision by a parent or guardian","A helmet and nothing else","A motorcycle endorsement on a license","Nothing, since scooters are exempt from rules"],"why":"Handbook Section 14E: a person under 15 can ride a motor-assisted scooter only with parent supervision or a course certificate."},{"id":"mot-1gs1vpd","q":"Where may motor-assisted scooters NOT be used?","a":"On highways posted over 15 mph","o":["On highways posted over 15 mph","On a street posted at 10 mph","On a private path with no posted limit","In a private driveway at home"],"why":"Handbook Section 14E: a motor-assisted scooter may not be used on a highway posted above 15 mph or on a highway with four or more lanes."},{"id":"mot-l3tf4z","q":"A street-legal ATV on a highway may go no faster than:","a":"The posted limit or 50 mph, whichever is less","o":["The posted limit or 50 mph, whichever is less","75 mph on any state highway that is not posted","The same speed as the cars that are around it","60 mph on all roads that allow a street-legal ATV"],"why":"The top highway speed is the lesser of the posted limit or 50 mph."},{"id":"mot-1wlvpom","q":"Which license can drive a street-legal ATV, UTV, or FSV?","a":"Class D or a CDL","o":["Class D or a CDL","Learner permit only","A boat license","No license"],"why":"Class D or CDL holders may operate them."},{"id":"mot-1i37o50","q":"A pedestrian vehicle for a person with a disability can go no faster than:","a":"30 mph","o":["30 mph","10 mph","45 mph","60 mph"],"why":"Pedestrian vehicles cannot exceed 30 mph."},{"id":"mot-w4bwz5","q":"A low-speed vehicle is a four-wheeled electric vehicle with a top speed of:","a":"25 mph","o":["25 mph","15 mph","45 mph","65 mph"],"why":"Low-speed vehicles are limited to 25 mph and carry no more than four people."},{"id":"mot-p2w283","q":"A rider under 21 on a street-legal ATV must wear:","a":"A DOT-approved helmet","o":["A DOT-approved helmet","Nothing, since helmets are optional","A cap with a visor only","Gloves and boots only"],"why":"Operators under 21 must wear a DOT approved helmet."},{"id":"mot-13kfusp","q":"Lane splitting is:","a":"Illegal","o":["Illegal","Always legal","Legal on freeways","Legal at night"],"why":"Lane splitting is illegal. Only lane filtering under strict rules is allowed."},{"id":"mot-1pmnviy","q":"What is the fee for a motorcycle endorsement in the handbook's fee table?","a":"$18.00","o":["$18.00","$9.00","$39.00","$52.00"],"why":"The fee table lists $18.00 for a motorcycle endorsement."},{"id":"mot-1h1gdlm","q":"A person 16 or older who rides a motor-assisted scooter:","a":"May ride without supervision","o":["May ride without supervision","Needs a parent riding beside them","Needs a course certificate to ride","Must stay on sidewalks"],"why":"Handbook Section 14E: under 15, supervision or a course certificate is needed. From 16 up, no supervision is required."},{"id":"mot-nyfen9","q":"A street-legal ATV, UTV, or FSV may be operated on a highway that has:","a":"One lane in each direction","o":["One lane in each direction","Two lanes in each direction","Four lanes with a center median","A center turn lane alone"],"why":"Handbook Section 14K: a street-legal ATV, UTV, or FSV may use a highway with one lane in each direction."},{"id":"mot-1yai6pv","q":"A street-legal ATV on a highway posted over 50 mph must:","a":"Stay on the extreme right and carry a reflector or reflective tape","o":["Stay on the extreme right and carry a reflector or reflective tape","Stay on the extreme left and carry a reflector or reflective tape","Stay on the extreme right and carry a flag on a tall pole","Drive at the posted speed with the headlight and taillight on"],"why":"The operator must ride on the extreme right-hand side of the roadway."},{"id":"mot-1csyzxq","q":"A motorcycle has a turn signal flashing. What should you assume?","a":"The rider may have forgotten to cancel it","o":["The rider may have forgotten to cancel it","The rider is surely about to turn left or right","The signal cancels by itself in a block","Motorcycles do not have turn signals"],"why":"Handbook Section 14F: do not believe a motorcycle is turning because its signal flashes. Many motorcycle signals do not self-cancel."},{"id":"mot-kgeesg","q":"How should you share a lane with a motorcycle?","a":"Give the rider a whole lane","o":["Give the rider a whole lane","Share it if the road is wide","Share it when traffic is slow","Share it if the rider moves over"],"why":"Handbook Section 14F: give motorcycles an entire lane and do not share the lane."},{"id":"mot-cmh1sx","q":"A pedestrian vehicle for a person with a disability must be less than how wide?","a":"48 inches","o":["48 inches","36 inches","60 inches","80 inches"],"why":"Handbook Section 14H: it must be less than 48 inches wide, with an engine under 300 cc and not capable of exceeding 30 mph."},{"id":"mot-1voopsl","q":"A motor-assisted scooter is not allowed on a highway starting at how many lanes?","a":"Four lanes","o":["Four lanes","Two lanes","Three lanes","Six lanes"],"why":"Handbook Section 14E: a motor-assisted scooter may not be used on a highway with four or more lanes or on one posted above 15 mph."},{"id":"mot-12vdlb8","q":"Compared with motorcycles, scooters and mopeds travel at:","a":"A much lower speed","o":["A much lower speed","A much higher speed","About the same speed","A speed set by traffic lights"],"why":"Handbook Section 14F: scooters and mopeds travel at a much lower speed than motorcycles."},{"id":"mot-8crre4","q":"How can you apply for a motorcycle learner permit?","a":"Book a duplicate license visit at dld.utah.gov","o":["Book a duplicate license visit at dld.utah.gov","Mail a signed form to the Highway Patrol office","Visit a motorcycle dealer and ask for a form","Take the permit tests at a high school class"],"why":"Handbook Section 14F: you can apply by scheduling a duplicate license appointment at dld.utah.gov."}]},{"id":"towing","name":"Towing & Warning Devices","icon":"🚛","src":"Handbook: Section 16 (Towing) and loads","qs":[{"id":"tow-z3uktc","q":"A big vehicle is stopped on the road for more than how long before warning devices are required?","a":"10 minutes","o":["10 minutes","1 minute","1 hour","30 minutes"],"why":"Vehicles 80 inches wide or 30 feet long must put out warning devices after 10 minutes."},{"id":"tow-1mxhvqy","q":"Where should you place the first warning device after stopping a wide or long vehicle?","a":"On the side toward oncoming traffic","o":["On the side toward oncoming traffic","Behind the driver seat of the vehicle","In front of the hood of the vehicle","In the glove box until it is dark"],"why":"Place the first device toward oncoming traffic."},{"id":"tow-k7e668","q":"How far should warning devices be placed in front and behind a stopped vehicle?","a":"100 feet","o":["100 feet","10 feet","20 feet","500 feet"],"why":"Place devices 100 feet front and rear."},{"id":"tow-165c6zt","q":"On a one-way street, how far behind your vehicle should you place a rear warning flag?","a":"200 feet","o":["200 feet","20 feet","50 feet","1,000 feet"],"why":"The handbook says 200 feet behind on one-way streets."},{"id":"tow-127yqq7","q":"When are warning devices not needed?","a":"When light shows the vehicle from 1,000 feet","o":["When light shows the vehicle from 1,000 feet","When it is windy outside and the road is cold","When a passing driver sees the vehicle from 100 feet","When the driver is waiting for help to arrive"],"why":"They are not needed when light shows the vehicle from 1,000 feet."},{"id":"tow-mzrdjl","q":"How should you handle a flare?","a":"Keep it away from your face and fuel","o":["Keep it away from your face and fuel","Hold it close to your face to see it","Tie it to the bumper so it stays put","Light it near a fuel leak to test it"],"why":"Keep flares away from your eyes and fuel, and do not attach them to the vehicle."},{"id":"tow-2u5dip","q":"What is the best way to put out a tire fire?","a":"Use water","o":["Use water","Use a blanket","Let it burn","Use gasoline"],"why":"Water is the best remedy for tire fires."},{"id":"tow-1ly1gre","q":"You may NOT fight a gasoline or oil fire with:","a":"Water","o":["Water","A fire extinguisher","Dirt","Sand"],"why":"Do not use water on a gasoline or oil fire."},{"id":"tow-1xm01h","q":"When you fight a fire outdoors, where should the wind be?","a":"At your back","o":["At your back","In your face","From the side","It does not matter"],"why":"Fight fires with the wind at your back."},{"id":"tow-1qa863o","q":"How far may a load extend in front of a truck?","a":"3 feet","o":["3 feet","10 feet","1 foot","20 feet"],"why":"Loads may extend no more than 3 feet in front and 6 feet at the rear."},{"id":"tow-n82d17","q":"How far may a load extend behind a truck?","a":"6 feet","o":["6 feet","3 feet","20 feet","50 feet"],"why":"The rear limit is 6 feet."},{"id":"tow-gciys9","q":"A towed car swerves and whips dangerously. What should you do?","a":"Do not tow it that way","o":["Do not tow it that way","Speed up so it settles down","Honk to warn drivers and keep going","Keep going and watch the rear mirror"],"why":"Do not operate a vehicle train when a towed unit whips or swerves."},{"id":"tow-l3o5mn","q":"Which single-axle trailer must be registered?","a":"One that is used for hire","o":["One that is used for hire","A homemade yard trailer","A camping trailer weighing 700 pounds","A trailer you keep on private land"],"why":"Handbook Appendix C: register a single-axle trailer if it is commercial or used for hire. Travel, camping, and fifth-wheel trailers need it over 750 pounds empty."},{"id":"tow-fwsu4w","q":"How far apart can two towed vehicles be using a drawbar?","a":"15 feet","o":["15 feet","3 feet","30 feet","50 feet"],"why":"The maximum is 15 feet."},{"id":"tow-kjbm34","q":"What is a flag on a rope or chain tow connection for?","a":"To make it visible to others","o":["To make it visible to others","To decorate the front bumper","To signal a left turn","To cool the engine during towing"],"why":"A red flag at least 12 inches square must be on a chain, rope, or cable connection."},{"id":"tow-1e972du","q":"No vehicle, including its load, may be taller than:","a":"14 feet","o":["14 feet","10 feet","12 feet","16 feet"],"why":"The height limit is 14 feet, including any load."},{"id":"tow-12d67u6","q":"A motor home pulling a boat may not exceed a total length of:","a":"65 feet","o":["65 feet","45 feet","30 feet","80 feet"],"why":"Other combinations may not exceed 65 feet in length, 8 feet in width, and 14 feet in height."},{"id":"tow-d44hra","q":"A load may not extend more than how far past the right-side fenders?","a":"Six inches","o":["Six inches","Three feet","One foot","Two feet"],"why":"On the left side a load may not extend beyond the fender line."},{"id":"tow-87orxo","q":"When are warning devices not required for a stopped wide or long vehicle?","a":"When it is legally parked in an urban district","o":["When it is legally parked in an urban district","When it is stopped beside a rural road at night","When the hazard lights have been turned on","When the driver stays inside and waits for help"],"why":"Warning devices are also not needed when picking up or letting off passengers lawfully."},{"id":"tow-1f4rftf","q":"Where should warning devices be placed on the road?","a":"In the center of the lane where the vehicle is stopped","o":["In the center of the lane where the vehicle is stopped","On the shoulder beside the lane where the vehicle stopped","On the center line between the two lanes of traffic","Attached to the rear bumper of the stopped vehicle"],"why":"If the vehicle is entirely off the road, place them on the shoulder."},{"id":"tow-np6vgd","q":"What is the smallest flag allowed on a chain, rope, or cable tow connection?","a":"12 inches square","o":["12 inches square","6 inches square","18 inches square","24 inches square"],"why":"Handbook Section 16: a red flag or other signal no smaller than 12 inches (one foot) square must be attached to a chain, rope, or cable connection."},{"id":"tow-fa4gx0","q":"A curve blocks the view of your stopped vehicle. How far away may a warning device be placed, at most?","a":"500 feet","o":["500 feet","300 feet","1,000 feet","200 feet"],"why":"Handbook Section 16: the device may not be placed more than 500 feet from the vehicle, and no closer than 100 feet."},{"id":"tow-kb4lig","q":"May you attach a flare or fuse to your vehicle?","a":"No, it is hazardous and illegal","o":["No, it is hazardous and illegal","Yes, on the rear bumper","Yes, at night for extra visibility","Yes, with a clip if the flame faces out"],"why":"Handbook Section 16: do not attach any flare or fuse to your vehicle. It is hazardous and illegal."},{"id":"tow-15vn8v8","q":"What is the smallest vehicle that must show warning devices after a stop of over 10 minutes?","a":"80 inches wide or 30 feet long","o":["80 inches wide or 30 feet long","60 inches wide or 20 feet long","100 inches wide or 40 feet long","96 inches wide or 35 feet long"],"why":"Handbook Section 16: a vehicle that is 80 inches wide or 30 feet long must show flares, flags, or lights if stopped on the road over 10 minutes."},{"id":"tow-ir62of","q":"What can sometimes slow a tire fire enough to get the tire off?","a":"Shoveling dirt on the tire","o":["Shoveling dirt on the tire","Covering the tire with a blanket","Driving faster to cool the tire","Letting the air out of the tire"],"why":"Handbook Section 16: shoveling dirt on the tire can sometimes retard the fire enough to get the tire off."},{"id":"tow-111unia","q":"A tire fire cannot be put out and the tire cannot be removed. What is a last resort?","a":"Drop your trailer to save one unit","o":["Drop your trailer to save one unit","Park next to a building for help","Keep the trailer attached and wait","Pour water on the fuel tank"],"why":"Handbook Section 16: as a last resort, drop your trailer. You will at least save one of the units."},{"id":"tow-1939jvo","q":"Which habit helps prevent a tire fire?","a":"Checking tires and brakes for heat","o":["Checking tires and brakes for heat","Driving on a soft tire to the next exit","Leaving the parking brake on while you drive","Ignoring a hot tire if it is not smoking"],"why":"Handbook Section 16: check tires and brakes frequently for heat, change soft or flat tires, and release the parking brake before moving."},{"id":"tow-1v6qd83","q":"How should you use the limited contents of a fire extinguisher?","a":"Aim carefully so every burst counts","o":["Aim carefully so every burst counts","Empty it all at once into the air","Spray it from far away in a wide arc","Save it until the fire is out of control"],"why":"Handbook Section 16: the contents are limited, so carefully aim to make every burst count."},{"id":"tow-1lytiix","q":"How many main rules does the handbook list for towing another vehicle?","a":"Three","o":["Three","Five","Seven","Ten"],"why":"Handbook Section 16: when towing there are only three rules to remember: connection length, a flag on soft connections, and no dangerous swerving."},{"id":"tow-1xt4k24","q":"Which situation excuses you from placing warning devices for a stopped wide or long vehicle?","a":"Stopping to avoid conflict with other traffic","o":["Stopping to avoid conflict with other traffic","Stopping to check a text message from a friend","Stopping to eat a meal at the side of the road","Stopping for a short nap along the roadside"],"why":"Handbook Section 16: devices are not required when legally parked in an urban district, picking up or letting off passengers, avoiding traffic conflict, or following an officer or traffic signal."}]},{"id":"health","name":"Health, Vision & Appendices","icon":"🩺","src":"Handbook: Section 5 and Appendices","qs":[{"id":"hea-paafec","q":"You cannot pass the vision test, even with glasses. What do you need?","a":"A Certificate of Visual Examination from an ophthalmologist","o":["A Certificate of Visual Examination from an ophthalmologist","A hearing with a judge before your application can be accepted","A vision card signed by a licensed driving instructor","A signed letter from a pharmacist about your glasses"],"why":"Handbook Section 5A: if you cannot pass the vision test, take a Certificate of Visual Examination (CVE) to an ophthalmologist (an eye doctor). The completed form must be presented before your application can be accepted."},{"id":"hea-1fgua6z","q":"A driver older than 65 applies for a license. What is required?","a":"Passing a vision test","o":["Passing a vision test","Nothing extra","A road test every year","A repeat written test only"],"why":"Applicants older than 65 must pass a vision test."},{"id":"hea-11lxpq3","q":"A health condition may affect your driving. What must you do?","a":"Tell the division and seek a medical evaluation","o":["Tell the division and seek a medical evaluation","Wait for the division to send you a letter first","Stop driving until your next license renewal","Tell your friends and keep driving as usual"],"why":"You must report it to DLD and get medical evaluation."},{"id":"hea-11vv88q","q":"Can a doctor take away your driving privilege directly?","a":"No, doctors report and the division decides","o":["No, doctors report and the division decides","Yes, doctors can end your license on the spot","Yes, if you ask for it in writing","Yes, for a period of up to 30 days"],"why":"The health care professional completes the form for the division. The division, through a hearing officer, decides on restrictions."},{"id":"hea-zy9ylk","q":"What does the Driver License Medical Advisory Board focus on?","a":"Functional ability to drive","o":["Functional ability to drive","Your age and your last name","Your income and your car type","Your school grades and your job"],"why":"Its guidelines, Functional Ability in Driving, help doctors advise patients and the division about driving safety."},{"id":"hea-1dwbkpb","q":"Does a review examination automatically take away your license?","a":"No, drivers often keep driving with restrictions","o":["No, drivers often keep driving with restrictions","Yes, your license is taken away once it is ordered","Yes, for one year after every review exam","Yes, until you pass the written knowledge test"],"why":"A review does not automatically remove privileges."},{"id":"hea-mlgqi0","q":"Which is a warning sign of an emotional problem that affects driving?","a":"Constant anger at other drivers","o":["Constant anger at other drivers","Singing along to the radio while driving","Leaving a few minutes early for a trip","Listening to the radio to stay focused"],"why":"Constant anger at other drivers is a warning sign."},{"id":"hea-gnj2fs","q":"One organ donor can save up to how many lives?","a":"Eight","o":["Eight","Twelve","Fifty","Sixteen"],"why":"One donor can save up to eight lives, and tissue donors help over 75 people."},{"id":"hea-qnohwv","q":"A tissue donor can help over how many people?","a":"75","o":["75","7","10","500"],"why":"Tissue donors can help over 75 people."},{"id":"hea-zigw7w","q":"Organ recovery costs the donor's family:","a":"Nothing","o":["Nothing","The hospital bill","$5,000","The funeral bill"],"why":"Organ recovery costs the donor's family nothing."},{"id":"hea-hlob1d","q":"How long should you let a car idle before turning it off to cut pollution?","a":"Turn it off if idling will last more than 30 seconds","o":["Turn it off if idling will last more than 30 seconds","Turn it off if idling will last more than five minutes","Idle for at least five minutes to warm it up","Turn it off once the engine is fully warmed up"],"why":"Turn the engine off if you expect to idle over 30 seconds."},{"id":"hea-1jv2vn6","q":"Identity fraud in Utah is:","a":"A felony","o":["A felony","A parking ticket","A written warning only","Legal if you return the card"],"why":"Identity fraud is a felony under Utah law."},{"id":"hea-225shs","q":"Submitting fake documents to the Driver License Division will result in:","a":"Prosecution","o":["Prosecution","A warning letter","A reminder to retake the test","No penalty if it is a first try"],"why":"Fraudulent documents are prosecuted."},{"id":"hea-lye5az","q":"How many emergency contacts may you list with the division?","a":"Up to two","o":["Up to two","Up to three","Up to five","Up to four"],"why":"You may list up to two individuals in the emergency contact database."},{"id":"hea-1b1o74l","q":"Medications can cause drowsiness. What should you do?","a":"Ask a doctor whether it is safe to drive","o":["Ask a doctor whether it is safe to drive","Drink a cup of coffee and drive as usual","Keep driving unless you start to feel dizzy","Ignore the drowsiness and keep on driving"],"why":"A doctor may advise against driving until the dose is safe."},{"id":"hea-n2m3lx","q":"To drive a Class D vehicle, the guidelines require vision of at least:","a":"20/40 in at least one eye","o":["20/40 in at least one eye","20/70 in at least one eye","20/100 in at least one eye","20/200 in both eyes together"],"why":"They also require a visual field of at least 90 degrees."},{"id":"hea-16elwv3","q":"Who completes the Functional Ability Evaluation (FAE) form?","a":"Your health care professional","o":["Your health care professional","A police officer who stopped you","A driving instructor you studied with","Your insurance agent or lender"],"why":"The division mails the form for you to take to your health care professional."},{"id":"hea-1gqqayz","q":"What happens if a driver does not complete a required review examination?","a":"Driving privileges are withdrawn","o":["Driving privileges are withdrawn","Nothing happens, the review is optional","The driver pays a small fine and moves on","The review is canceled and the file closed"],"why":"A review does not automatically lead to withdrawal, but skipping it does."},{"id":"hea-1xzooqg","q":"You feel angry or upset before a drive. What does the handbook suggest?","a":"Give yourself time to cool off first","o":["Give yourself time to cool off first","Drive faster to burn off the anger","Honk at slow drivers to feel better","Roll down the windows and keep on driving"],"why":"Take a walk or talk to a friend, and stay off the road until you cool down."},{"id":"hea-1iu79u2","q":"Idling for long periods in cold weather can:","a":"Cause excessive engine wear","o":["Cause excessive engine wear","Clean carbon out of the engine","Lower the pollution from the car","Save fuel on a cold morning"],"why":"Modern vehicles need little warm-up and are most efficient when driven."},{"id":"hea-1xu7okn","q":"The 'Out and About' homebound transportation contribution is:","a":"$1.00","o":["$1.00","$2.00","$5.00","$10.00"],"why":"The voluntary $1.00 contribution helps with public transportation for seniors and people with disabilities."},{"id":"hea-1pc2jtj","q":"Which agency handles vehicle registration in Utah?","a":"The Division of Motor Vehicles","o":["The Division of Motor Vehicles","The Driver License Division","The Highway Patrol","The Department of Transportation"],"why":"The Driver License Division handles licenses and ID cards."},{"id":"hea-6zojny","q":"Which of these is a health care professional (HCP) in the handbook?","a":"A physician assistant","o":["A physician assistant","A licensed pharmacist","A registered dentist","A physical therapist"],"why":"Handbook Section 5A: HCPs are medical doctors, physician assistants, and advanced practice nurses."},{"id":"hea-p7c7pk","q":"How many categories do the Medical Advisory Board guidelines address?","a":"11","o":["11","6","9","14"],"why":"Handbook Section 5A: the guidelines address 11 categories known to affect driving safety."},{"id":"hea-1j8tz4f","q":"What visual field is required to drive a Class D vehicle?","a":"At least 90 degrees","o":["At least 90 degrees","At least 45 degrees","At least 120 degrees","At least 180 degrees"],"why":"Handbook Section 5A: the guidelines require 20/40 vision in at least one eye and a visual field of at least 90 degrees."},{"id":"hea-1wpdl3a","q":"After a review examination, who discusses the results with the driver?","a":"A hearing officer","o":["A hearing officer","A police sergeant","The driver's own doctor","A court clerk"],"why":"Handbook Section 5C: a hearing officer discusses the results and reviews the medical evaluation, then decides on restrictions."},{"id":"hea-132mfh3","q":"Who has the final responsibility for knowing your driving abilities?","a":"You, the driver","o":["You, the driver","Your doctor","Your insurance agent","The hearing officer"],"why":"Handbook Section 5B: you have the final responsibility for knowing your abilities and for driving safely."},{"id":"hea-g45cs3","q":"Which of these can lead the division to request a review examination?","a":"A report from a law enforcement officer","o":["A report from a law enforcement officer","Buying a new car from a local dealer","Moving to a new city in another county","Getting a parking ticket in a loading zone"],"why":"Handbook Section 5C: a request can come from a medical professional, a confidential report, a law enforcement officer, an agency, or a returned FAE form."},{"id":"hea-1kdjbri","q":"Which tip helps you concentrate on driving when your mind is elsewhere?","a":"Listen to the radio or sing to yourself","o":["Listen to the radio or sing to yourself","Text a friend about how you feel at the time","Watch a video at red lights","Argue with your passengers"],"why":"Handbook Section 5A (Mental health), Tip 2: do something that allows you to concentrate, such as listening to the radio or singing."},{"id":"hea-ghbk89","q":"Which group gets the optional contribution for vision screening?","a":"Friends For Sight","o":["Friends For Sight","Out and About Fund","Organ Donation Fund","DonorConnect"],"why":"Handbook Appendix A: when you apply for a license, you may add a contribution for vision screening. It is sent to Friends For Sight."}]}];
